730:   /* ── hook ──────────────────────────────────────────────── */
731:   fireHook() {
732:     const h = this.hook;
733:     if (h.state === 'flying' || h.state === 'attached' || h.state === 'retracting') return;
734:     if (h.cooldown > 0) return;
735:     this.audio.init();
736:     this.updateMouseWorld();
737:     const p = this.player.position;
738:     const hand = this.hand();
739:     let dx = this.mouse.wx - p.x, dy = this.mouse.wy - p.y;
740:     const d = Math.hypot(dx, dy) || 1;
741:     dx /= d; dy /= d;
742:     const hit = castRay(this.level.segments, hand.x, hand.y, hand.x + dx * HOOK_RANGE, hand.y + dy * HOOK_RANGE, HOOK_RANGE);
743:     h.state = 'flying';
744:     h.miss = !hit;
745:     h.from = { x: hand.x, y: hand.y };
746:     h.to = hit ? { x: hit.x, y: hit.y } : { x: hand.x + dx * HOOK_RANGE, y: hand.y + dy * HOOK_RANGE };
747:     h.pos = { ...h.from };
748:     h.t = 0;
749:     h.attachedFor = 0;
750:     h.anchor = null;
751:     h.dur = hit ? clamp(Math.hypot(hit.x - hand.x, hit.y - hand.y) / 3400, .07, .2) : .19;
752:     this.reeling = true;
753:     this.audio.hookFire();
754:     if (hit) this.toast('');
755:   }
756: 
757:   applyHook(dt) {
758:     const h = this.hook;
759:     if (!h.anchor) return;
760:     const p = this.player.position;
761:     const dx = h.anchor.x - p.x, dy = h.anchor.y - p.y;
762:     const dist = Math.hypot(dx, dy);
763:     if (dist < 1) return;
764:     if (dist > h.ropeLen) {
765:       const nx = dx / dist, ny = dy / dist;
766:       const stretch = dist - h.ropeLen;
767:       const rv = this.player.velocity.x * nx + this.player.velocity.y * ny;
768:       const accel = clamp(stretch * 0.00009 + Math.max(0, rv) * 0.012, 0, 0.02);
769:       Body.applyForce(this.player, p, { x: nx * accel * PLAYER_MASS, y: ny * accel * PLAYER_MASS });
770:       if (stretch > 220) {
771:         // rope rescue cap so a bad catch does not fling you into orbit
772:         const v = this.player.velocity;
773:         const sp = Math.hypot(v.x, v.y);
774:         if (sp > 1.9) Body.setVelocity(this.player, { x: v.x / sp * 1.9, y: v.y / sp * 1.9 });
775:       }
776:     }
777:   }
778: 
779:   releaseHook(silent = false) {
780:     const h = this.hook;
781:     this.reeling = false;
782:     if (h.state === 'attached' || h.state === 'flying') {
783:       if (!silent) this.toast('');
784:       const hand = this.hand();
785:       h.state = 'retracting';
786:       h.t = 0;
787:       h.dur = .18;
788:       h.anchor = null;
789:     }
790:   }
791: 
792:   detachHook(silent = true) {
793:     this.reeling = false;
794:     this.hook.state = 'ready';
795:     this.hook.anchor = null;
796:     this.hook.cooldown = .3;
797:     const hand = this.hand();
798:     this.hook.pos = { ...hand };
799:   }
