257:   // Raycast segments from every static body's true world vertices.
258:   const segments = [];
259:   for (const plat of platforms) {
260:     const v = plat.body.vertices;
261:     for (let i = 0; i < v.length; i++) {
262:       const a = v[i], b = v[(i + 1) % v.length];
263:       segments.push({ ax: a.x, ay: a.y, bx: b.x, by: b.y, platform: plat });
264:     }
265:   }
