40: export function preparePlatforms(level) {
41:   for (const p of level.platforms) {
42:     const rand = mulberry32(hashStr(p.id + p.type));
43:     const L = p.len, T = p.t;
44:     const tex = {
45:       specks: [], cracks: [], tufts: [], seams: [], nails: [], joints: [],
46:       veins: [], facets: [], blocks: [], boulders: [], lichen: [], vines: [],
47:     };
48:     const n = Math.min(54, Math.max(16, Math.floor(L / 10)));
49:     for (let i = 0; i < n; i++) {
50:       tex.specks.push({ x: (rand() - .5) * L, y: (rand() - .5) * T, r: .6 + rand() * 2.1, a: .08 + rand() * .28 });
51:     }
52:     const cracks = Math.min(9, Math.max(2, Math.floor(L / 58)));
53:     for (let i = 0; i < cracks; i++) {
54:       const x = (rand() - .5) * L * .86;
55:       const y = (rand() - .5) * T * .5;
56:       const seg = [{ x, y }];
57:       let cx = x, cy = y;
58:       for (let j = 0; j < 4; j++) {
59:         cx += (rand() - .5) * T * .9;
60:         cy += (rand() - .25) * T * .5;
61:         seg.push({ x: cx, y: cy });
62:       }
63:       tex.cracks.push(seg);
64:     }
65:     const tufts = Math.max(4, Math.floor(L / 26));
66:     for (let i = 0; i < tufts; i++) {
67:       tex.tufts.push({ x: (rand() - .5) * L * .96, h: 5 + rand() * 13, lean: (rand() - .5) * 7, a: rand() });
68:     }
69:     const seams = Math.max(2, Math.floor(L / 58));
70:     for (let i = 0; i < seams; i++) tex.seams.push((rand() - .5) * L * .9);
71:     for (let i = 0; i < Math.max(4, Math.floor(L / 46)); i++) {
72:       tex.nails.push({ x: (rand() - .5) * L * .92, y: (rand() - .5) * T * .4, o: rand() });
73:     }
74:     const joints = Math.max(2, Math.floor(L / 70));
75:     for (let i = 0; i < joints; i++) tex.joints.push((rand() - .5) * L);
76:     for (let i = 0; i < Math.max(3, Math.floor(L / 55)); i++) {
77:       tex.veins.push({ x0: (rand() - .5) * L, x1: (rand() - .5) * L, y: (rand() - .5) * T * .6, w: .5 + rand() * 1.5 });
78:     }
79:     // rock facets: chunky planes that break up the box silhouette
80:     const facets = Math.max(3, Math.floor(L / 70));
81:     for (let i = 0; i < facets; i++) {
82:       const x = (rand() - .5) * L * .92;
83:       const w = 26 + rand() * Math.min(90, L * .22);
84:       const h = T * (.35 + rand() * .7);
85:       const y = -T * .2 + rand() * T * .5;
86:       tex.facets.push({ x, y, w, h, a: .018 + rand() * .035, warm: rand() > .5 });
87:     }
88:     // sediment bands and embedded boulders
89:     tex.strata = [];
90:     const bands = Math.max(2, Math.floor(T / 26));
91:     for (let i = 0; i < bands; i++) {
92:       tex.strata.push({ y: -T / 2 + (i + .5) * (T / bands) + (rand() - .5) * 6, h: 3 + rand() * 9, a: .05 + rand() * .09 });
93:     }
94:     tex.embedded = [];
95:     for (let i = 0; i < Math.max(2, Math.floor(L / 100)); i++) {
96:       tex.embedded.push({ x: (rand() - .5) * L * .8, y: -T * .05 + rand() * T * .35, r: 6 + rand() * Math.min(22, T * .3), a: rand() });
97:     }
98:     // masonry courses for temple stone
99:     const rows = Math.max(2, Math.floor(T / 26));
100:     for (let r = 0; r < rows; r++) {
101:       const off = (r % 2) * 26 + rand() * 10;
102:       for (let x = -L / 2 + off; x < L / 2; x += 52 + rand() * 12) {
103:         tex.blocks.push({ x, y: -T / 2 + (r / rows) * T, h: T / rows, w: 46 + rand() * 18 });
104:       }
105:     }
106:     // loose stones that sit on broad shoulders
107:     for (let i = 0; i < Math.min(7, Math.max(2, Math.floor(L / 90))); i++) {
108:       tex.boulders.push({ x: (rand() - .5) * L * .9, r: 3.5 + rand() * 8, a: rand() });
109:     }
110:     for (let i = 0; i < Math.floor(L / 34); i++) {
111:       tex.lichen.push({ x: (rand() - .5) * L * .94, y: (rand() - .5) * T * .7, r: 4 + rand() * 14, a: .04 + rand() * .1 });
112:     }
113:     for (let i = 0; i < Math.max(2, Math.floor(L / 10)); i++) {
114:       tex.vines.push({ x: (rand() - .5) * L * .95, len: 14 + rand() * 70, lean: (rand() - .5) * 8, a: rand() });
115:     }
116:     p.tex = tex;
117:     p.shape = buildLedgeShape(p, rand);
118:     p.seed = rand();
119:   }
120: }
