161: /* ── distant coast ─────────────────────────────────────────── */
162: 
163: export function drawUndercliffs(ctx, game) {
164:   if (!game._distant) {
165:     const rand = mulberry32(70731);
166:     // Little sister stacks on the open-water side of the isle.
167:     game._distant = [];
168:     for (let i = 0; i < 5; i++) {
169:       const x = -1720 - i * 210 + rand() * 90;
170:       const w = 120 + rand() * 220;
171:       const h = 120 + rand() * 360;
172:       const lean = (rand() - .5) * 40;
173:       game._distant.push({ x, w, h, lean, a: .22 + rand() * .16, seed: rand() });
174:     }
175:   }
176:   const sea = game.level.seaY;
177:   ctx.save();
178:   for (const d of game._distant) {
179:     // they sit far out in the haze, so they read flat and pale
180:     const g = ctx.createLinearGradient(d.x, sea - d.h, d.x, sea);
181:     g.addColorStop(0, `rgba(98,130,126,${d.a})`);
182:     g.addColorStop(.7, `rgba(74,108,108,${d.a * 1.1})`);
183:     g.addColorStop(1, `rgba(56,88,92,${d.a * 1.2})`);
184:     ctx.fillStyle = g;
185:     ctx.beginPath();
186:     ctx.moveTo(d.x - d.w / 2, sea);
187:     ctx.quadraticCurveTo(d.x - d.w * .42, sea - d.h * .45, d.x - d.w * .28 + d.lean, sea - d.h * .78);
188:     ctx.lineTo(d.x - d.w * .12 + d.lean, sea - d.h);
189:     ctx.lineTo(d.x + d.w * .08 + d.lean, sea - d.h * .93);
190:     ctx.quadraticCurveTo(d.x + d.w * .34, sea - d.h * .5, d.x + d.w / 2, sea);
191:     ctx.closePath();
192:     ctx.fill();
193:     // a pale rim facing the sunset
194:     ctx.strokeStyle = 'rgba(240,206,150,.12)';
195:     ctx.lineWidth = 1.4;
196:     ctx.beginPath();
197:     ctx.moveTo(d.x - d.w * .12 + d.lean, sea - d.h);
198:     ctx.quadraticCurveTo(d.x - d.w * .42, sea - d.h * .45, d.x - d.w / 2, sea);
199:     ctx.stroke();
200:   }
201:   ctx.restore();
202: 
203:   // rock roots that tie every shelf into the cliff face
204:   for (const p of game.level.platforms) {
205:     if (p.id === 'beach' || p.ship || p.log) continue;
206:     if (p.type === 'wood') continue;
207:     const rand = mulberry32(hashStr(p.id + 'root'));
208:     const bx = p.cx + p.ux * p.len * .18 + p.nx * p.t * .42;
209:     const by = p.cy + p.uy * p.len * .18 + p.ny * p.t * .42;
210:     const w = Math.min(140, p.len * .26) * (.7 + rand() * .5);
211:     const h = 140 + rand() * 280;
212:     const drift = 30 + rand() * 100;
213:     const pts = [
214:       { x: bx - w * .5, y: by - 8 },
215:       { x: bx + w * .55, y: by - 8 },
216:       { x: bx + w * .35 + drift * .3, y: by + h * .5 },
217:       { x: bx + w * .12 + drift, y: by + h },
218:       { x: bx - w * .2 + drift * .8, y: by + h * .82 },
219:       { x: bx - w * .42 + drift * .2, y: by + h * .35 },
220:     ];
221:     poly(ctx, pts);
222:     const rg = ctx.createLinearGradient(bx - w, by, bx + w, by + h);
223:     rg.addColorStop(0, 'rgba(65,77,60,.8)');
224:     rg.addColorStop(.45, 'rgba(43,56,50,.85)');
225:     rg.addColorStop(1, 'rgba(17,28,29,.92)');
226:     ctx.fillStyle = rg;
227:     ctx.fill();
228:     // lit seaward edge of the root
229:     ctx.strokeStyle = 'rgba(255,196,128,.2)';
230:     ctx.lineWidth = 1.6;
231:     ctx.beginPath();
232:     ctx.moveTo(bx - w * .5, by - 8);
233:     ctx.quadraticCurveTo(bx - w * .55, by + h * .4, bx - w * .2 + drift * .8, by + h * .82);
234:     ctx.stroke();
235:     // strata crossing the root
236:     ctx.strokeStyle = 'rgba(5,10,10,.18)';
237:     ctx.lineWidth = 1.4;
238:     for (let i = 1; i < 5; i++) {
239:       const yy = by + (h * i) / 5;
240:       ctx.beginPath();
241:       ctx.moveTo(bx - w, yy);
242:       ctx.quadraticCurveTo(bx, yy + 8, bx + w + drift, yy - 4);
243:       ctx.stroke();
244:     }
245:   }
246: 
247:   // The beach's supporting cliff, kept dark so the sand reads bright.
248:   for (const p of game.level.platforms) {
249:     if (p.id !== 'beach') continue;
250:     const rand = mulberry32(hashStr(p.id + 'cliff'));
251:     const depth = 820;
252:     const x1 = p.x1, y1 = p.y1, x2 = p.x2, y2 = p.y2;
253:     const midx = (x1 + x2) / 2, midy = (y1 + y2) / 2;
254:     const spread = 240;
255:     const left = { x: x1 - spread + (rand() - .5) * 40, y: y1 + depth * .55 };
256:     const middle = { x: midx + (rand() - .5) * 80, y: midy + depth };
257:     const right = { x: x2 + spread + (rand() - .5) * 40, y: y2 + depth * .62 };
258:     const pts = [
259:       { x: x1 + 2, y: y1 + 8 }, { x: x2 - 2, y: y2 + 8 },
260:       { x: x2 + 120, y: y2 + depth * .3 }, right, middle, left,
261:       { x: x1 - 120, y: y1 + depth * .3 },
262:     ];
263:     poly(ctx, pts);
264:     const g = ctx.createLinearGradient(0, y1, 0, midy + depth);
265:     g.addColorStop(0, '#6e5636');
266:     g.addColorStop(.3, '#4b3a25');
267:     g.addColorStop(.72, '#2d2418');
268:     g.addColorStop(1, '#17140f');
269:     ctx.fillStyle = g;
270:     ctx.fill();
271: 
272:     ctx.save();
273:     poly(ctx, pts);
274:     ctx.clip();
275:     const r2 = mulberry32(hashStr(p.id + 'strata'));
276:     for (let i = 0; i < 24; i++) {
277:       const yy = y1 + 30 + i * 34 + r2() * 18;
278:       ctx.strokeStyle = `rgba(12,10,7,${.1 + r2() * .16})`;
279:       ctx.lineWidth = 1 + r2() * 4;
280:       ctx.beginPath();
281:       ctx.moveTo(x1 - 220, yy);
282:       ctx.bezierCurveTo(midx - 300, yy + 18, midx + 200, yy - 14, x2 + 260, yy + 8);
283:       ctx.stroke();
284:     }
285:     for (let i = 0; i < 12; i++) {
286:       const bx = x1 - 100 + r2() * (x2 - x1 + 220);
287:       const by = y1 + 80 + r2() * depth * .7;
288:       const r = 22 + r2() * 70;
289:       ctx.fillStyle = i % 2 ? 'rgba(255,226,180,.03)' : 'rgba(0,0,0,.18)';
290:       ctx.beginPath();
291:       ctx.ellipse(bx, by, r, r * .55, r2() * 3, 0, TAU);
292:       ctx.fill();
293:     }
294:     ctx.restore();
295: 
296:     // boulders at the tide line
297:     const br = mulberry32(hashStr(p.id + 'boulders'));
298:     for (let i = 0; i < 9; i++) {
299:       const bx = x1 - 140 + br() * (x2 - x1 + 280);
300:       const by = y1 + 44 + br() * 80;
301:       const r = 18 + br() * 44;
302:       ctx.fillStyle = i % 3 === 0 ? '#3b3226' : '#453a2b';
303:       blob(ctx, bx, by, r, r * .55, br, 7, .22);
304:       ctx.fill();
305:       ctx.fillStyle = 'rgba(255,225,175,.06)';
306:       ctx.beginPath();
307:       ctx.ellipse(bx - r * .15, by - r * .3, r * .5, r * .18, -.2, 0, TAU);
308:       ctx.fill();
309:     }
310:   }
311: }
