313: /* ── ledge drawing ─────────────────────────────────────────── */
314: 
315: function drawBeach(ctx, p, time) {
316:   const L = p.len, T = p.t;
317:   const rand = mulberry32(hashStr(p.id + 'beachart'));
318: 
319:   // dunes behind the walkable line (drawn first, so the pirate stands in front)
320:   ctx.save();
321:   ctx.beginPath();
322:   ctx.moveTo(-L / 2, -T / 2 + 2);
323:   let x = -L / 2;
324:   let i = 0;
325:   while (x < L / 2) {
326:     const w = 110 + rand() * 190;
327:     const h = 7 + rand() * 28;
328:     ctx.quadraticCurveTo(x + w * .5, -T / 2 - h, x + w, -T / 2 + 2);
329:     x += w;
330:     i++;
331:   }
332:   ctx.lineTo(L / 2, -T / 2 + 4);
333:   ctx.lineTo(-L / 2, -T / 2 + 4);
334:   ctx.closePath();
335:   const dg = ctx.createLinearGradient(0, -T / 2 - 34, 0, -T / 2 + 4);
336:   dg.addColorStop(0, '#c6a066');
337:   dg.addColorStop(1, '#b08a54');
338:   ctx.fillStyle = dg;
339:   ctx.fill();
340:   ctx.restore();
341: 
342:   // beach body: a bright dune lip over a dark, eroded sand cliff
343:   const top = -T / 2;
344:   const g = ctx.createLinearGradient(0, top, 0, top + 330);
345:   g.addColorStop(0, '#efd9a2');
346:   g.addColorStop(.035, '#dcbb7d');
347:   g.addColorStop(.1, '#c49a61');
348:   g.addColorStop(.24, '#a87c4a');
349:   g.addColorStop(.48, '#88633d');
350:   g.addColorStop(.75, '#654a2e');
351:   g.addColorStop(1, '#443120');
352:   ctx.fillStyle = g;
353:   ctx.beginPath();
354:   ctx.moveTo(-L / 2 + 2, top);
355:   ctx.lineTo(L / 2 - 2, top);
356:   ctx.lineTo(L / 2 - 22, top + T * .82);
357:   ctx.quadraticCurveTo(L / 2 - 90, top + T * 1.08, L / 2 - 240, top + T);
358:   ctx.lineTo(-L / 2 + 260, top + T);
359:   ctx.quadraticCurveTo(-L / 2 + 90, top + T * 1.04, -L / 2 + 26, top + T * .8);
360:   ctx.closePath();
361:   ctx.fill();
362: 
363:   ctx.save();
364:   ctx.clip();
365:   // shadow cast by the lip onto the cliff face
366:   const cast = ctx.createLinearGradient(0, top + 2, 0, top + 90);
367:   cast.addColorStop(0, 'rgba(26,18,10,.3)');
368:   cast.addColorStop(1, 'rgba(26,18,10,0)');
369:   ctx.fillStyle = cast;
370:   ctx.fillRect(-L / 2, top + 2, L, 92);
371:   // eroded sand strata
372:   for (let i = 0; i < 22; i++) {
373:     const y = top + 24 + i * 13 + Math.sin(i * 2.7) * 7;
374:     ctx.strokeStyle = i % 3 === 0 ? 'rgba(255,232,186,.09)' : 'rgba(52,36,20,.14)';
375:     ctx.lineWidth = .8 + (i % 4) * .6;
376:     ctx.beginPath();
377:     ctx.moveTo(-L / 2, y);
378:     for (let xx = -L / 2; xx < L / 2; xx += 130) {
379:       ctx.quadraticCurveTo(xx + 65, y + Math.sin(xx * .013 + i) * 5, xx + 130, y);
380:     }
381:     ctx.stroke();
382:   }
383:   // dry sand runs off the lip in fine vertical veins
384:   const sr = mulberry32(7788);
385:   for (let i = 0; i < 26; i++) {
386:     const sx = -L / 2 + sr() * L;
387:     const len = 30 + sr() * 130;
388:     ctx.strokeStyle = sr() > .5 ? 'rgba(228,197,144,.13)' : 'rgba(74,50,28,.16)';
389:     ctx.lineWidth = .8 + sr() * 1.6;
390:     ctx.beginPath();
391:     ctx.moveTo(sx, top + 4);
392:     ctx.bezierCurveTo(sx + 5, top + len * .4, sx - 6, top + len * .7, sx + 2, top + len);
393:     ctx.stroke();
394:   }
395:   // roots and vines let go of the dune lip
396:   const vr = mulberry32(2321);
397:   for (let i = 0; i < 12; i++) {
398:     const vx = -L / 2 + vr() * L;
399:     const len = 36 + vr() * 140;
400:     ctx.strokeStyle = 'rgba(79,58,34,.4)';
401:     ctx.lineWidth = 1.2;
402:     ctx.beginPath();
403:     ctx.moveTo(vx, top + 1);
404:     ctx.bezierCurveTo(vx + 10, top + len * .3, vx - 8, top + len * .65, vx + 5, top + len);
405:     ctx.stroke();
406:   }
407:   // wet sand / surf zone at the bottom
408:   const wet = ctx.createLinearGradient(0, top + T * .7, 0, top + T);
409:   wet.addColorStop(0, 'rgba(60,84,74,0)');
410:   wet.addColorStop(.55, 'rgba(58,80,72,.22)');
411:   wet.addColorStop(1, 'rgba(45,68,67,.38)');
412:   ctx.fillStyle = wet;
413:   ctx.fillRect(-L / 2, top + T * .62, L, T * .4);
414:   // pebbles / shells / footprints on the dry sand
415:   for (let i = 0; i < 70; i++) {
416:     const px = (rand() - .5) * L;
417:     const py = top + 6 + rand() * 36;
418:     if (i % 11 === 0) {
419:       ctx.fillStyle = 'rgba(244,236,214,.5)';
420:       ctx.beginPath();
421:       ctx.ellipse(px, py, 2.2 + rand() * 2.4, 1.2 + rand() * 1.2, rand() * 3, 0, TAU);
422:       ctx.fill();
423:     } else {
424:       ctx.fillStyle = i % 3 === 0 ? 'rgba(255,240,205,.2)' : 'rgba(88,64,38,.3)';
