816: export function drawChest(ctx, x, y, time, open, scale = 1) {
817:   ctx.save();
818:   ctx.translate(x, y);
819:   ctx.scale(scale, scale);
820:   shadowBlob(ctx, 0, 3, 52, 10, .35);
821:   // glow
822:   ctx.save();
823:   ctx.globalCompositeOperation = 'lighter';
824:   glow(ctx, 0, -30, 110, 'rgba(255,190,70,A)', .12 + open * .28);
825:   ctx.restore();
826:   const bodyG = ctx.createLinearGradient(0, -34, 0, 4);
827:   bodyG.addColorStop(0, '#8a5a26');
828:   bodyG.addColorStop(1, '#4c2d10');
829:   ctx.fillStyle = bodyG;
830:   rr(ctx, -44, -34, 88, 38, 3); ctx.fill();
831:   ctx.strokeStyle = '#2a1707'; ctx.lineWidth = 2.4; ctx.stroke();
832:   // bands
833:   ctx.fillStyle = '#c79b45';
834:   for (const bx of [-26, 26]) ctx.fillRect(bx - 3, -34, 6, 38);
835:   ctx.fillStyle = '#e3ba62';
836:   // lid
837:   ctx.save();
838:   ctx.translate(0, -34);
839:   ctx.rotate(-open * 1.12);
840:   const lidG = ctx.createLinearGradient(0, -26, 0, 0);
841:   lidG.addColorStop(0, '#a06c2e');
842:   lidG.addColorStop(1, '#6d4519');
843:   ctx.fillStyle = lidG;
844:   ctx.beginPath();
845:   ctx.moveTo(-44, 0);
