256:   setupUI() {
257:     $('#begin-btn').addEventListener('click', () => { this.audio.init(); this.beginRun(); });
258:     $('#how-btn').addEventListener('click', () => this.openHow());
259:     $('#how-close').addEventListener('click', () => this.closeHow());
260:     $('#how-begin').addEventListener('click', () => { this.closeHow(); this.beginRun(); });
261:     $('#resume-btn').addEventListener('click', () => this.resume());
262:     $('#restart-btn').addEventListener('click', () => { this.resume(); this.returnToCheckpoint(false); });
263:     $('#quit-btn').addEventListener('click', () => this.backToTitle());
264:     $('#again-btn').addEventListener('click', () => { this.hide('#end-screen'); this.beginRun(); });
265:     $('#end-title-btn').addEventListener('click', () => this.backToTitle());
266: 
267:     this.updateSaveUI();
268:     $('#sound-lbl').textContent = this.audio.muted ? 'off' : 'on';
269:   }
