418:   drawWater(t) {
419:     const { ctx } = this;
420:     if (this.cam.y > SEA_Y + 900) return;
421:     ctx.save();
422:     const left = -6000, right = 6000, top = SEA_Y;
423:     const g = ctx.createLinearGradient(0, top, 0, top + 1500);
424:     g.addColorStop(0, 'rgba(58,110,108,.8)');
425:     g.addColorStop(.12, 'rgba(32,82,88,.9)');
426:     g.addColorStop(.5, 'rgba(14,48,57,.95)');
427:     g.addColorStop(1, 'rgba(7,29,37,.98)');
428:     ctx.fillStyle = g;
429:     ctx.fillRect(left, top, right - left, 2600);
430: 
431:     // reflection of the low sun
432:     const z = this.cam.zoom;
433:     const sunWX = (this.w * .23 - this.w / 2) / z + this.cam.x;
434:     const refl = ctx.createLinearGradient(sunWX - 180, top, sunWX + 180, top);
435:     refl.addColorStop(0, 'rgba(255,190,110,0)');
436:     refl.addColorStop(.5, 'rgba(255,206,140,.2)');
437:     refl.addColorStop(1, 'rgba(255,190,110,0)');
438:     ctx.fillStyle = refl;
439:     ctx.fillRect(sunWX - 180, top, 360, 220);
440: 
441:     ctx.save();
442:     ctx.beginPath();
443:     ctx.rect(left, top - 80, right - left, 260);
444:     ctx.clip();
445:     for (let i = 0; i < 26; i++) {
446:       const yy = top + i * 8;
447:       const a = .03 + .028 * Math.sin(i * 1.7 + t * .8);
448:       ctx.strokeStyle = `rgba(190,226,213,${a})`;
449:       ctx.lineWidth = 1.2;
450:       ctx.beginPath();
451:       const off = Math.sin(t * .4 + i) * 40;
452:       ctx.moveTo(left, yy + Math.sin(i) * 2);
453:       for (let x = left; x <= right; x += 300) {
454:         ctx.quadraticCurveTo(x + 150, yy + Math.sin(x * .01 + t + i) * 3, x + 300, yy + Math.sin(x * .013 + t * .7) * 2);
455:       }
456:       ctx.stroke();
457:       void off;
458:     }
459:     // warm sun glitter
460:     for (let i = 0; i < 90; i++) {
461:       const gx = sunWX + (Math.sin(i * 12.9898) * .5) * (50 + i * 2.2);
462:       const gy = top + 4 + ((i * 47) % 190);
463:       const a = .05 + .12 * Math.sin(t * 2.2 + i * 1.3);
464:       ctx.fillStyle = `rgba(255,218,150,${Math.max(0, a)})`;
465:       ctx.fillRect(gx, gy, 2 + (i % 4), 1);
466:     }
467:     // cool sparkle elsewhere
468:     for (let i = 0; i < 30; i++) {
469:       const x = -1500 + ((i * 733) % 3000);
470:       const y = top + 6 + ((i * 91) % 120);
471:       const a = .07 + .07 * Math.sin(t * 2 + i);
472:       ctx.fillStyle = `rgba(240,228,180,${a})`;
473:       ctx.fillRect(x, y, 2, 1);
474:     }
475:     ctx.restore();
476:     // foam line
477:     ctx.strokeStyle = 'rgba(220,232,210,.28)';
478:     ctx.lineWidth = 1.4;
479:     ctx.beginPath();
480:     for (let x = left; x <= right; x += 100) {
481:       const y = top + Math.sin(x * .01 + t * 1.1) * 2.5;
482:       if (x === left) ctx.moveTo(x, y); else ctx.lineTo(x, y);
483:     }
484:     ctx.stroke();
485:     ctx.restore();
486:   }
