618:   drawMotes(t) {
619:     const { ctx, game } = this;
620:     const cam = this.cam;
621:     const z = cam.zoom;
622:     const vw = this.w / z, vh = this.h / z;
623:     const l = cam.x - vw / 2, r = cam.x + vw / 2, tp = cam.y - vh / 2, bt = cam.y + vh / 2;
624:     ctx.save();
625:     ctx.globalCompositeOperation = 'lighter';
626:     for (const m of this.motes) {
627:       if (m.x < l - 40 || m.x > r + 40 || m.y < tp - 40 || m.y > bt + 40) continue;
628:       const zone = game.level.zoneAt(m.y);
629:       let color, a;
630:       if (zone.id === 'jungle') { color = '190,235,120'; a = .5; }
631:       else if (zone.id === 'summit') { color = '255,215,120'; a = .55; }
632:       else if (zone.id === 'ruins') { color = '215,205,175'; a = .28; }
633:       else if (zone.id === 'wreck') { color = '240,190,120'; a = .3; }
634:       else { color = '235,235,215'; a = .28; }
635:       const wob = Math.sin(t * m.sp + m.ph) * 14;
636:       const wob2 = Math.cos(t * m.sp * .7 + m.ph) * 10;
637:       const x = m.x + wob, y = m.y + wob2;
638:       const alpha = a * (.55 + .45 * Math.sin(t * 2.2 + m.ph));
639:       const g = ctx.createRadialGradient(x, y, 0, x, y, m.s * 5);
640:       g.addColorStop(0, `rgba(${color},${alpha})`);
641:       g.addColorStop(1, `rgba(${color},0)`);
642:       ctx.fillStyle = g;
643:       ctx.beginPath();
644:       ctx.arc(x, y, m.s * 5, 0, TAU);
645:       ctx.fill();
646:     }
647:     ctx.restore();
648:   }
