651:   drawScreenEffects(t) {
652:     const { ctx, w, h, game } = this;
653: 
654:     if (game.splashFlash > 0) {
655:       const a = game.splashFlash;
656:       const g = ctx.createRadialGradient(w / 2, h * .7, 20, w / 2, h * .7, h);
657:       g.addColorStop(0, `rgba(170,225,215,${.28 * a})`);
658:       g.addColorStop(1, `rgba(40,95,105,${.55 * a})`);
659:       ctx.fillStyle = g;
660:       ctx.fillRect(0, 0, w, h);
661:     }
662: 
663:     if (game.mode === 'ending') {
664:       const a = clamp(game.endTimer / 2.6, 0, 1) * .4;
665:       const g = ctx.createRadialGradient(w / 2, h * .55, 20, w / 2, h * .55, h * .8);
666:       g.addColorStop(0, `rgba(255,220,140,${a * .3})`);
667:       g.addColorStop(1, `rgba(90,55,15,${a * .35})`);
668:       ctx.fillStyle = g;
669:       ctx.fillRect(0, 0, w, h);
670:     }
671: 
672:     // subtle top and bottom letterbox shading
673:     const topG = ctx.createLinearGradient(0, 0, 0, 110);
674:     topG.addColorStop(0, 'rgba(3,9,10,.36)');
675:     topG.addColorStop(1, 'rgba(3,9,10,0)');
676:     ctx.fillStyle = topG;
677:     ctx.fillRect(0, 0, w, 110);
678:     const botG = ctx.createLinearGradient(0, h - 150, 0, h);
679:     botG.addColorStop(0, 'rgba(3,9,10,0)');
680:     botG.addColorStop(1, 'rgba(3,9,10,.42)');
681:     ctx.fillStyle = botG;
682:     ctx.fillRect(0, h - 150, w, 150);
