684:     // warm/cool grade
685:     ctx.save();
686:     ctx.globalCompositeOperation = 'soft-light';
687:     const grade = ctx.createLinearGradient(0, 0, 0, h);
688:     const prog = game.progress ? game.progress() : 0;
689:     grade.addColorStop(0, `rgba(${prog > .5 ? '70,110,160' : '80,150,150'},.12)`);
690:     grade.addColorStop(1, 'rgba(210,150,80,.12)');
691:     ctx.fillStyle = grade;
692:     ctx.fillRect(0, 0, w, h);
693:     ctx.restore();
694:     void t;
695:   }
