206: export function platformGeometry(p) {
207:   const dx = p.x2 - p.x1;
208:   const dy = p.y2 - p.y1;
209:   const len = Math.hypot(dx, dy);
210:   const ux = dx / len, uy = dy / len;
211:   const nx = -uy, ny = ux; // downward normal
212:   const cx = (p.x1 + p.x2) / 2 + nx * p.t / 2;
213:   const cy = (p.y1 + p.y2) / 2 + ny * p.t / 2;
214:   const angle = Math.atan2(dy, dx);
215:   const top = [
216:     { x: p.x1, y: p.y1 },
217:     { x: p.x2, y: p.y2 },
218:     { x: p.x2 + nx * p.t, y: p.y2 + ny * p.t },
219:     { x: p.x1 + nx * p.t, y: p.y1 + ny * p.t },
220:   ];
221:   return { cx, cy, len, angle, nx, ny, ux, uy, top };
222: }
