840:   /* ── camera / particles ────────────────────────────────── */
841:   updateCamera(dt) {
842:     if (this.mode === 'playing') {
843:       const p = this.player.position;
844:       const v = this.player.velocity;
845:       const targetX = clamp(p.x + 30, -720, 780);
846:       const targetY = p.y - 138 + clamp(v.y * 42, -130, 180);
847:       this.camera.x = damp(this.camera.x, targetX, 5.2, dt);
848:       this.camera.y = damp(this.camera.y, targetY, 5.2, dt);
849:       const targetZoom = this.camera.baseZoom * this.camera.userZoom;
850:       this.camera.zoom = damp(this.camera.zoom, targetZoom, 3.2, dt);
851:     } else if (this.mode === 'title' || this.mode === 'ending') {
852:       // handled elsewhere
853:     } else {
854:       this.camera.zoom = damp(this.camera.zoom, this.camera.baseZoom * this.camera.userZoom, 3, dt);
855:     }
856:     this.camera.shakeTime += dt;
857:     this.camera.shake = Math.max(0, this.camera.shake - dt * 15);
858:     const s = this.camera.shake;
859:     this.camera.shakeX = Math.sin(this.camera.shakeTime * 93) * s + Math.sin(this.camera.shakeTime * 47) * s * .5;
860:     this.camera.shakeY = Math.cos(this.camera.shakeTime * 81) * s + Math.cos(this.camera.shakeTime * 53) * s * .5;
861:   }
862: 
863:   addCameraShake(n) {
864:     this.camera.shake = Math.min(16, this.camera.shake + n);
865:   }
866: 
867:   updateParticles(dt) {
868:     const ps = this.particles;
869:     for (let i = ps.length - 1; i >= 0; i--) {
870:       const q = ps[i];
871:       q.life -= dt;
872:       if (q.life <= 0) { ps.splice(i, 1); continue; }
873:       q.vy += (q.grav || 0) * dt;
874:       q.vx *= (1 - (q.drag || 0) * dt);
875:       q.vy *= (1 - (q.drag || 0) * dt);
876:       q.x += q.vx * dt;
877:       q.y += q.vy * dt;
878:       if (q.rot !== undefined) q.rot += (q.spin || 0) * dt;
879:     }
880:     if (ps.length > 620) ps.splice(0, ps.length - 620);
881:   }
882: 
883:   addParticle(o) {
884:     this.particles.push(o);
885:   }
