574: export function drawPirate(ctx, game, time) {
575:   const b = game.player;
576:   if (!b) return;
577:   const p = b.position;
578:   const cam = game.camera;
579:   const lookX = clamp((game.mouse.wx - p.x) / 180, -1, 1);
580:   const lookY = clamp((game.mouse.wy - p.y) / 180, -1, 1);
581:   const vel = b.velocity;
582:   const grounded = game.grounded();
583:   const bob = grounded ? Math.sin(time * 1.7) * .8 + Math.sin(time * 3.1) * .25 : Math.sin(time * 5) * 1.4;
584: 
585:   ctx.save();
586:   ctx.translate(p.x, p.y);
587: 
588:   // ground shadow
589:   if (grounded) {
590:     const sx = clamp(vel.x * 12, -10, 10);
591:     ctx.save();
592:     ctx.fillStyle = 'rgba(4,8,8,.28)';
593:     ctx.beginPath();
594:     ctx.ellipse(sx, 56, 38, 8, 0, 0, TAU);
595:     ctx.fill();
596:     ctx.fillStyle = 'rgba(4,8,8,.12)';
597:     ctx.beginPath();
598:     ctx.ellipse(sx, 58, 54, 12, 0, 0, TAU);
599:     ctx.fill();
600:     ctx.restore();
601:   }
602: 
603:   ctx.translate(0, bob);
604:   torso(ctx, time);
605: 
606:   // left shoulder & arm toward hook hand
607:   const hand = { x: -25, y: 2 };
608:   const hookState = game.hook.state;
609:   if (hookState !== 'ready') {
610:     const ang = Math.atan2(game.hook.pos.y - p.y, game.hook.pos.x - p.x);
611:     hand.x = Math.cos(ang) * 30;
612:     hand.y = Math.sin(ang) * 24 - 4;
613:   }
614:   ctx.save();
615:   drawArm(ctx, -14, -20, hand.x, hand.y, 9);
616:   ctx.fillStyle = '#b97f54';
617:   ctx.beginPath();
618:   ctx.arc(hand.x, hand.y, 4.6, 0, TAU);
619:   ctx.fill();
620:   ctx.restore();
621: 
622:   // head
623:   head(ctx, time, lookX, lookY);
624: 
625:   // barrel
626:   barrelFront(ctx, time, vel);
627: 
628:   // right arm gripping the pole base
629:   const grip = game.shoulder();
630:   const gx = grip.x - p.x, gy = grip.y - p.y;
631:   ctx.save();
632:   drawArm(ctx, 16, -18, gx, gy, 10);
633:   // hand
634:   const ga = Math.atan2(gy - (-18), gx - 16);
635:   ctx.fillStyle = '#c1875b';
636:   ctx.beginPath();
637:   ctx.arc(gx, gy, 5.4, 0, TAU);
638:   ctx.fill();
639:   ctx.strokeStyle = 'rgba(90,48,28,.5)';
640:   ctx.lineWidth = 1;
641:   ctx.beginPath();
642:   ctx.arc(gx, gy, 3, ga + .3, ga + 2.4);
643:   ctx.stroke();
644:   ctx.restore();
645: 
646:   // held hook when idle
647:   if (hookState === 'ready') {
648:     const sway = Math.sin(time * 1.5) * .06;
649:     drawHookShape(ctx, hand.x + 2, hand.y + 7, sway, .8, time);
650:   }
651: 
652:   // little glints / breath
653:   if (!grounded && Math.abs(vel.y) > 1.2) {
654:     ctx.strokeStyle = 'rgba(240,232,210,.25)';
655:     ctx.lineWidth = 1;
656:     ctx.beginPath();
657:     ctx.moveTo(-18, -60);
658:     ctx.quadraticCurveTo(-26, -70, -32, -64);
659:     ctx.stroke();
660:   }
661: 
662:   ctx.restore();
663:   void cam;
664: }
