488:   drawCheckpoints(t) {
489:     const { ctx, game } = this;
490:     const cps = game.level.checkpoints;
491:     cps.forEach((cp, i) => {
492:       const reached = i <= game.checkpointIndex;
493:       const current = i === game.checkpointIndex;
494:       const x = cp.x, base = cp.footY ?? cp.y + 40;
495:       const h = 60;
496:       ctx.save();
497:       // footing shadow
498:       ctx.fillStyle = 'rgba(4,8,8,.25)';
499:       ctx.beginPath();
500:       ctx.ellipse(x, base + 1, 14, 4, 0, 0, TAU);
501:       ctx.fill();
502:       // post
503:       ctx.strokeStyle = reached ? '#5c4327' : '#3d3020';
504:       ctx.lineWidth = 4;
505:       ctx.beginPath();
506:       ctx.moveTo(x, base);
507:       ctx.lineTo(x, base - h);
508:       ctx.stroke();
509:       // lantern top
510:       ctx.fillStyle = reached ? '#f0c568' : '#8c7448';
511:       ctx.beginPath();
512:       ctx.arc(x, base - h - 2, 3.4, 0, TAU);
513:       ctx.fill();
514:       if (reached) {
515:         ctx.save();
516:         ctx.globalCompositeOperation = 'lighter';
517:         const g = ctx.createRadialGradient(x, base - h - 2, 0, x, base - h - 2, 36);
518:         g.addColorStop(0, `rgba(255,206,112,${current ? .35 : .18})`);
519:         g.addColorStop(1, 'rgba(255,190,80,0)');
520:         ctx.fillStyle = g;
521:         ctx.beginPath();
522:         ctx.arc(x, base - h - 2, 36, 0, TAU);
523:         ctx.fill();
524:         ctx.restore();
525:       }
526:       // flag
527:       const wave = Math.sin(t * 3 + i * 1.7) * 2;
528:       ctx.fillStyle = reached ? (current ? '#e9b95a' : 'rgba(208,164,82,.7)') : 'rgba(90,84,68,.6)';
529:       ctx.beginPath();
530:       ctx.moveTo(x + 2, base - h + 4);
531:       ctx.quadraticCurveTo(x + 20, base - h + 6 + wave, x + 31, base - h + 10 + wave);
532:       ctx.lineTo(x + 28, base - h + 22);
533:       ctx.quadraticCurveTo(x + 18, base - h + 17 + wave, x + 2, base - h + 20);
534:       ctx.closePath();
535:       ctx.fill();
536:       if (reached) {
537:         ctx.fillStyle = 'rgba(38,26,10,.65)';
538:         ctx.beginPath();
539:         ctx.arc(x + 15, base - h + 12, 2.4, 0, TAU);
540:         ctx.fill();
541:       }
542:       ctx.restore();
543:     });
544:   }
