702:     const attached = game.hook.state === 'attached';
703:     const col = attached ? 'rgba(255,216,130,.9)' : 'rgba(235,214,176,.75)';
704:     ctx.save();
705:     ctx.translate(x, y);
706:     ctx.rotate(t * .5);
707:     ctx.strokeStyle = col;
708:     ctx.lineWidth = 1;
709:     ctx.beginPath();
710:     ctx.arc(0, 0, grip ? 7 : 9, .3, 1.1);
711:     ctx.arc(0, 0, grip ? 7 : 9, 1.8, 2.6);
712:     ctx.arc(0, 0, grip ? 7 : 9, 3.3, 4.1);
713:     ctx.arc(0, 0, grip ? 7 : 9, 4.8, 5.6);
714:     ctx.stroke();
715:     ctx.rotate(-t * .5);
716:     ctx.fillStyle = col;
717:     ctx.beginPath();
718:     ctx.arc(0, 0, grip ? 2.2 : 1.3, 0, TAU);
719:     ctx.fill();
720:     if (attached) {
721:       ctx.strokeStyle = 'rgba(255,210,120,.28)';
722:       ctx.beginPath();
723:       ctx.arc(0, 0, 15 + Math.sin(t * 4) * 2, 0, TAU);
724:       ctx.stroke();
