788: export function drawPlatforms(ctx, game, cam) {
789:   const z = cam.zoom;
790:   const viewW = game.renderer.w / z, viewH = game.renderer.h / z;
791:   const cullL = cam.x - viewW / 2 - 320, cullR = cam.x + viewW / 2 + 320;
792:   const cullT = cam.y - viewH / 2 - 320, cullB = cam.y + viewH / 2 + 320;
793: 
794:   for (const p of game.level.platforms) {
795:     if (p.cx < cullL || p.cx > cullR || p.cy < cullT || p.cy > cullB) continue;
796:     const st = TYPE_STYLE[p.type] || TYPE_STYLE.rock;
797:     ctx.save();
798:     ctx.translate(p.cx, p.cy);
799:     ctx.rotate(p.angle);
800: 
801:     if (p.id === 'beach') {
802:       drawBeach(ctx, p, game.time);
803:     } else {
804:       drawLedge(ctx, p, st, game.time);
805:     }
806: 
807:     // fallen log: extra bark, knots and end grain
808:     if (p.log) {
809:       const L = p.len, T = p.t;
810:       ctx.save();
811:       rr(ctx, -L / 2, -T / 2, L, T, Math.min(10, T * .4));
812:       ctx.clip();
813:       ctx.strokeStyle = 'rgba(43,26,12,.62)';
814:       ctx.lineWidth = 2.2;
815:       for (let i = 0; i < 7; i++) {
816:         const y = -T / 2 + 2 + i * (T / 7);
817:         ctx.beginPath();
818:         ctx.moveTo(-L / 2, y);
819:         ctx.bezierCurveTo(-L * .2, y - 3, L * .2, y + 3, L / 2, y);
820:         ctx.stroke();
821:       }
822:       ctx.strokeStyle = 'rgba(193,146,92,.32)';
823:       ctx.lineWidth = 1;
824:       for (let i = 0; i < 5; i++) {
825:         const y = -T / 2 + 3 + i * (T / 5.5);
826:         ctx.beginPath();
827:         ctx.moveTo(-L / 2, y);
828:         ctx.bezierCurveTo(-L * .2, y - 2, L * .2, y + 2, L / 2, y);
829:         ctx.stroke();
830:       }
831:       ctx.fillStyle = 'rgba(77,101,58,.4)';
832:       for (let i = 0; i < 7; i++) {
833:         ctx.beginPath();
834:         ctx.ellipse(-L / 2 + 20 + i * (L / 8), T / 2 - 4, 9, 2.4, 0, 0, TAU);
835:         ctx.fill();
836:       }
837:       ctx.restore();
838:       ctx.fillStyle = '#7a552f';
839:       ctx.beginPath();
840:       ctx.ellipse(-L / 2 + 5, 0, 5, T / 2 - 1, 0, 0, TAU);
841:       ctx.fill();
842:       ctx.strokeStyle = 'rgba(52,33,16,.7)';
843:       ctx.lineWidth = 1;
844:       for (let i = 1; i <= 3; i++) {
845:         ctx.beginPath();
846:         ctx.ellipse(-L / 2 + 5, 0, 1.6 * i, (T / 2 - 2) * (i / 3.4), 0, 0, TAU);
847:         ctx.stroke();
848:       }
849:     }
850: 
851:     // rope wraps on wreck timber
852:     if (p.ship && p.type === 'wood') {
853:       ctx.strokeStyle = 'rgba(168,140,92,.5)';
854:       ctx.lineWidth = 1.2;
855:       for (let i = 0; i < 3; i++) {
856:         const x = -p.len / 2 + 14 + i * 5;
857:         ctx.beginPath();
858:         ctx.moveTo(x, -p.t / 2);
859:         ctx.lineTo(x + 3, p.t / 2);
860:         ctx.stroke();
861:       }
862:     }
863: 
864:     ctx.restore();
865:   }
866: }
