870: export function drawSeaStack(ctx, game, time) {
871:   if (!game._stack) {
872:     const rand = mulberry32(91827);
873:     const pts = [];
874:     for (let y = 620; y >= -10800; y -= 58) {
875:       const k = clamp((620 - y) / 11420, 0, 1);
876:       const ease = k * k * (3 - 2 * k);
877:       const cx = 250 + 180 * Math.sin(y / 1350) + 80 * Math.sin(y / 460 + 1.2);
878:       const half = lerp(1180, 650, ease) + Math.sin(y / 230) * 58 + (rand() - .5) * 34;
879:       // occasional buttress juts out of the sunset-facing edge
880:       const jut = (rand() > .82 ? 34 + rand() * 90 : 0) + (rand() > .94 ? 40 : 0);
881:       const left = cx - half - jut + (rand() - .5) * 16;
882:       const right = cx + half + (rand() - .5) * 18;
883:       pts.push({ y, cx, half, left, right, jut, k });
884:     }
885:     game._stack = pts;
886: 
887:     // large features, generated once
888:     const r2 = mulberry32(55231);
889:     game._stackDetail = {
890:       facets: Array.from({ length: 120 }, () => {
891:         const y = 500 - r2() * 11000;
892:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
893:         const x = p ? p.left + r2() * (p.right - p.left) : -400 + r2() * 1200;
894:         return {
895:           x, y, w: 110 + r2() * 460, h: 180 + r2() * 720,
896:           a: .028 + r2() * .06, warm: r2() > .55,
897:         };
898:       }),
899:       strata: Array.from({ length: 90 }, () => ({
900:         y: 560 - r2() * 11200,
901:         w: 1.5 + r2() * 9,
902:         a: .06 + r2() * .12,
903:         bend: 20 + r2() * 70,
904:       })),
905:       buttresses: Array.from({ length: 11 }, (_, i) => ({
906:         y: 380 - i * 980 - r2() * 420,
907:         w: 90 + r2() * 260,
908:         h: 300 + r2() * 820,
909:         a: .18 + r2() * .2,
910:       })),
911:       caves: Array.from({ length: 6 }, () => ({
912:         y: 200 - r2() * 10200,
913:         w: 34 + r2() * 90,
914:         h: 20 + r2() * 54,
915:         a: .5 + r2() * .3,
916:       })),
917:       moss: Array.from({ length: 170 }, () => {
918:         const y = 300 - r2() * 10800;
919:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
920:         const x = p ? p.left + r2() * (p.right - p.left) : -300 + r2() * 1000;
921:         return { x, y, r: 10 + r2() * 70, a: .035 + r2() * .09, green: r2() > .35 };
922:       }),
923:       shelves: Array.from({ length: 38 }, () => {
924:         const y = 480 - r2() * 11200;
925:         return {
926:           y,
927:           len: 120 + r2() * 420,
928:           drop: 18 + r2() * 80,
929:           a: .12 + r2() * .14,
930:         };
931:       }),
932:       boulders: Array.from({ length: 40 }, () => {
933:         const y = 420 - r2() * 11000;
934:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
935:         const x = p ? p.left + 60 + r2() * Math.max(120, p.right - p.left - 120) : -300 + r2() * 1000;
936:         return { x, y, rx: 14 + r2() * 58, ry: 9 + r2() * 32, a: .06 + r2() * .12, rot: r2() * 3 };
937:       }),
938:       wide: Array.from({ length: 30 }, () => {
939:         const y = 450 - r2() * 11100;
940:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
941:         const left = p ? p.left : -800;
942:         const right = p ? p.right : 1200;
943:         return {
944:           y,
945:           x: left + 80 + r2() * Math.max(80, right - left - 260),
946:           len: 160 + r2() * 460,
947:           drop: 28 + r2() * 90,
948:           a: .13 + r2() * .16,
949:         };
950:       }),
951:       gullies: Array.from({ length: 14 }, () => {
952:         const y = 380 - r2() * 10700;
953:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
954:         const left = p ? p.left : -800;
955:         const right = p ? p.right : 1200;
956:         return {
957:           x: left + 100 + r2() * Math.max(100, right - left - 300),
958:           y,
959:           w: 40 + r2() * 120,
960:           h: 300 + r2() * 700,
961:           a: .08 + r2() * .12,
962:         };
963:       }),
964:       pillars: Array.from({ length: 24 }, (_, i) => {
965:         const y = 420 - i * 470 - r2() * 220;
966:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
967:         const left = p ? p.left : -800;
968:         const right = p ? p.right : 1200;
969:         return {
970:           x: left + 70 + r2() * Math.max(80, right - left - 380),
971:           y,
972:           w: 100 + r2() * 210,
973:           h: 420 + r2() * 900,
974:           a: .1 + r2() * .14,
975:         };
976:       }),
977:       cracks: Array.from({ length: 30 }, () => {
978:         const y = 420 - r2() * 10800;
979:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
980:         return {
981:           x: p ? p.left + 30 + r2() * 320 : -600 + r2() * 400,
982:           y,
983:           h: 120 + r2() * 520,
984:           lean: (r2() - .5) * 90,
985:           a: .1 + r2() * .12,
986:         };
987:       }),
988:       spurs: Array.from({ length: 36 }, (_, i) => {
989:         const y = 480 - i * 322 - r2() * 160;
990:         return { y, len: 45 + r2() * 170, drop: 18 + r2() * 54, a: .55 + r2() * .4 };
991:       }),
992:       vines: Array.from({ length: 54 }, () => {
993:         const idx = Math.floor(r2() * (pts.length - 30));
994:         const p = pts[idx];
995:         return {
996:           x: p.left + 20 + r2() * (p.right - p.left),
997:           y: p.y,
998:           len: 30 + r2() * 190,
999:           lean: (r2() - .5) * 18,
1000:         };
1001:       }),
1002:     };
1003:   }
1004: 
1005:   const pts = game._stack;
1006:   const D = game._stackDetail;
1007: 
1008:   /* far, hazy sister cliff behind and to the right */
1009:   ctx.save();
1010:   ctx.beginPath();
1011:   ctx.moveTo(pts[0].left - 260, pts[0].y + 40);
1012:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].left - 260 + Math.sin(i * .7) * 40, pts[i].y + 40);
1013:   for (let i = pts.length - 1; i >= 0; i--) ctx.lineTo(pts[i].right + 300, pts[i].y + 40);
1014:   ctx.closePath();
1015:   ctx.fillStyle = 'rgba(87,120,116,.3)';
1016:   ctx.fill();
1017:   ctx.restore();
1018: 
1019:   /* main mass */
1020:   ctx.save();
1021:   ctx.beginPath();
1022:   ctx.moveTo(pts[0].left, pts[0].y);
1023:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].left, pts[i].y);
1024:   for (let i = pts.length - 1; i >= 0; i--) ctx.lineTo(pts[i].right, pts[i].y);
1025:   ctx.closePath();
1026: 
1027:   const g = ctx.createLinearGradient(-500, 600, 800, -10800);
1028:   g.addColorStop(0, '#4b4c38');
1029:   g.addColorStop(.14, '#37463a');
1030:   g.addColorStop(.32, '#2d3f3d');
1031:   g.addColorStop(.55, '#26383f');
1032:   g.addColorStop(.78, '#1f3040');
1033:   g.addColorStop(1, '#293b4c');
1034:   ctx.fillStyle = g;
1035:   ctx.fill();
1036: 
1037:   ctx.save();
1038:   ctx.clip();
1039: 
1040:   // warm sunset bounce on the seaward flank
1041:   const warm = ctx.createLinearGradient(-980, 0, 340, 0);
1042:   warm.addColorStop(0, 'rgba(255,178,104,.24)');
1043:   warm.addColorStop(.24, 'rgba(238,150,86,.1)');
1044:   warm.addColorStop(.6, 'rgba(200,120,80,.03)');
1045:   warm.addColorStop(1, 'rgba(0,0,0,0)');
1046:   ctx.fillStyle = warm;
1047:   ctx.fillRect(-1100, -10900, 2000, 11600);
1048: 
1049:   // cross-light: lit seaward edge, deep shadow inland
1050:   const cross = ctx.createLinearGradient(-760, 0, 1000, 0);
1051:   cross.addColorStop(0, 'rgba(255,186,112,.1)');
1052:   cross.addColorStop(.18, 'rgba(24,34,34,0)');
1053:   cross.addColorStop(.55, 'rgba(8,16,20,.16)');
1054:   cross.addColorStop(1, 'rgba(2,8,13,.42)');
1055:   ctx.fillStyle = cross;
1056:   ctx.fillRect(-1100, -10900, 2200, 11600);
1057: 
1058:   // chunky facets
1059:   for (const f of D.facets) {
1060:     ctx.fillStyle = f.warm
1061:       ? `rgba(255,220,164,${f.a})`
1062:       : `rgba(3,9,11,${f.a + .05})`;
1063:     ctx.beginPath();
1064:     ctx.moveTo(f.x, f.y);
1065:     ctx.lineTo(f.x + f.w, f.y + f.h * .11);
1066:     ctx.lineTo(f.x + f.w * .7, f.y + f.h);
1067:     ctx.lineTo(f.x - f.w * .1, f.y + f.h * .62);
1068:     ctx.closePath();
1069:     ctx.fill();
1070:   }
1071: 
1072:   // massive shadowed buttresses along the face
1073:   for (const b of D.buttresses) {
1074:     const bg = ctx.createLinearGradient(0, b.y, 0, b.y + b.h);
1075:     bg.addColorStop(0, `rgba(2,7,9,${b.a * .5})`);
1076:     bg.addColorStop(.65, `rgba(2,7,9,${b.a})`);
1077:     bg.addColorStop(1, 'rgba(2,7,9,0)');
1078:     ctx.fillStyle = bg;
1079:     ctx.beginPath();
1080:     ctx.moveTo(-700, b.y);
1081:     ctx.lineTo(-700 + b.w * .4, b.y + b.h * .18);
1082:     ctx.lineTo(-700 + b.w, b.y + b.h);
1083:     ctx.lineTo(-700 - b.w * .2, b.y + b.h * .86);
1084:     ctx.closePath();
1085:     ctx.fill();
1086:     // lit edge of the buttress
1087:     ctx.strokeStyle = `rgba(255,205,140,${b.a * .7})`;
1088:     ctx.lineWidth = 1.6;
1089:     ctx.beginPath();
1090:     ctx.moveTo(-700, b.y);
1091:     ctx.quadraticCurveTo(-700 + b.w * .35, b.y + b.h * .35, -700 + b.w, b.y + b.h);
1092:     ctx.stroke();
1093:   }
1094: 
1095:   // vertical erosion gullies
1096:   for (const g of D.gullies) {
1097:     const gg = ctx.createLinearGradient(g.x, 0, g.x + g.w, 0);
1098:     gg.addColorStop(0, 'rgba(3,8,10,0)');
1099:     gg.addColorStop(.45, `rgba(3,8,10,${g.a})`);
1100:     gg.addColorStop(.7, `rgba(3,8,10,${g.a * .8})`);
1101:     gg.addColorStop(1, 'rgba(3,8,10,0)');
1102:     ctx.fillStyle = gg;
1103:     ctx.fillRect(g.x, g.y, g.w, g.h);
1104:     ctx.strokeStyle = `rgba(255,198,132,${g.a * .5})`;
1105:     ctx.lineWidth = 1;
1106:     ctx.beginPath();
1107:     ctx.moveTo(g.x + g.w * .82, g.y);
1108:     ctx.quadraticCurveTo(g.x + g.w * .92, g.y + g.h * .5, g.x + g.w * .7, g.y + g.h);
1109:     ctx.stroke();
1110:   }
1111: 
1112:   // fluted pillars: the cliff's vertical architecture
1113:   for (const p of D.pillars) {
1114:     const pg = ctx.createLinearGradient(p.x, 0, p.x + p.w, 0);
1115:     pg.addColorStop(0, `rgba(255,200,138,${p.a * .45})`);
1116:     pg.addColorStop(.16, 'rgba(28,38,36,0)');
1117:     pg.addColorStop(.55, `rgba(5,12,14,${p.a})`);
1118:     pg.addColorStop(1, `rgba(3,9,12,${p.a * 1.15})`);
1119:     ctx.fillStyle = pg;
1120:     ctx.beginPath();
1121:     ctx.moveTo(p.x, p.y);
1122:     ctx.lineTo(p.x + p.w * .82, p.y + 24);
1123:     ctx.lineTo(p.x + p.w, p.y + p.h);
1124:     ctx.lineTo(p.x + p.w * .3, p.y + p.h * .92);
1125:     ctx.lineTo(p.x - 12, p.y + p.h * .65);
1126:     ctx.closePath();
1127:     ctx.fill();
1128:     ctx.strokeStyle = `rgba(255,198,130,${p.a * .5})`;
1129:     ctx.lineWidth = 1.4;
1130:     ctx.beginPath();
1131:     ctx.moveTo(p.x, p.y);
1132:     ctx.quadraticCurveTo(p.x - 8, p.y + p.h * .4, p.x - 12, p.y + p.h * .65);
1133:     ctx.stroke();
1134:     // horizontal notches
1135:     ctx.strokeStyle = 'rgba(3,9,10,.3)';
1136:     ctx.lineWidth = 1.2;
1137:     for (let i = 1; i < 6; i++) {
1138:       const yy = p.y + (p.h * i) / 6;
1139:       ctx.beginPath();
1140:       ctx.moveTo(p.x - 4, yy);
1141:       ctx.quadraticCurveTo(p.x + p.w * .5, yy + 10, p.x + p.w, yy - 4);
1142:       ctx.stroke();
1143:     }
1144:   }
1145: 
1146:   // broad shelves inside the face give the wall its scale
1147:   for (const s of D.wide) {
1148:     ctx.fillStyle = `rgba(3,9,10,${s.a})`;
1149:     ctx.beginPath();
1150:     ctx.moveTo(s.x, s.y);
1151:     ctx.lineTo(s.x + s.len, s.y + 9);
1152:     ctx.lineTo(s.x + s.len * .88, s.y + s.drop);
1153:     ctx.lineTo(s.x + s.len * .2, s.y + s.drop * .7);
1154:     ctx.lineTo(s.x + 4, s.y + s.drop * .4);
1155:     ctx.closePath();
1156:     ctx.fill();
1157:     ctx.strokeStyle = `rgba(255,196,128,${s.a * .55})`;
1158:     ctx.lineWidth = 1.2;
1159:     ctx.beginPath();
1160:     ctx.moveTo(s.x, s.y);
1161:     ctx.lineTo(s.x + s.len, s.y + 9);
1162:     ctx.stroke();
1163:   }
1164: 
1165:   // horizontal rock shelves pushing out of the seaward face
1166:   for (const s of D.shelves) {
1167:     const idx = clamp(Math.round((620 - s.y) / 58), 0, pts.length - 1);
1168:     const p = pts[idx];
1169:     if (!p) continue;
1170:     const x0 = p.left + 5;
1171:     const y0 = p.y;
1172:     ctx.fillStyle = `rgba(3,9,10,${s.a})`;
1173:     ctx.beginPath();
1174:     ctx.moveTo(x0, y0);
1175:     ctx.lineTo(x0 + s.len, y0 + 9);
1176:     ctx.lineTo(x0 + s.len * .82, y0 + s.drop);
1177:     ctx.lineTo(x0 + 8, y0 + s.drop * .68);
1178:     ctx.closePath();
1179:     ctx.fill();
1180:     ctx.strokeStyle = `rgba(255,200,130,${s.a * .8})`;
1181:     ctx.lineWidth = 1.4;
1182:     ctx.beginPath();
1183:     ctx.moveTo(x0, y0);
1184:     ctx.lineTo(x0 + s.len, y0 + 9);
1185:     ctx.stroke();
1186:   }
1187: 
1188:   // boulders and overhangs embedded in the face
1189:   for (const b of D.boulders) {
1190:     const bg = ctx.createLinearGradient(0, b.y - b.ry, 0, b.y + b.ry);
1191:     bg.addColorStop(0, `rgba(255,214,164,${b.a * .8})`);
1192:     bg.addColorStop(.5, `rgba(60,72,62,${b.a * .35})`);
1193:     bg.addColorStop(1, `rgba(0,0,0,${b.a * 1.2})`);
1194:     ctx.fillStyle = bg;
1195:     const br = mulberry32(Math.round(b.x * 7 + b.y));
1196:     blob(ctx, b.x, b.y, b.rx, b.ry, br, 8, .24);
1197:     ctx.fill();
1198:     ctx.strokeStyle = `rgba(255,206,148,${b.a * .8})`;
1199:     ctx.lineWidth = 1.2;
1200:     ctx.beginPath();
1201:     ctx.ellipse(b.x, b.y, b.rx * .86, b.ry * .82, b.rot, Math.PI * 1.05, Math.PI * 1.95);
1202:     ctx.stroke();
1203:   }
1204: 
1205:   // deep vertical fractures
1206:   for (const c of D.cracks) {
1207:     ctx.strokeStyle = `rgba(2,7,9,${c.a})`;
1208:     ctx.lineWidth = 2 + c.a * 12;
1209:     ctx.beginPath();
1210:     ctx.moveTo(c.x, c.y);
1211:     ctx.bezierCurveTo(c.x + c.lean * .3, c.y + c.h * .3, c.x - c.lean * .4, c.y + c.h * .65, c.x + c.lean, c.y + c.h);
1212:     ctx.stroke();
1213:     ctx.strokeStyle = `rgba(255,210,150,${c.a * .28})`;
1214:     ctx.lineWidth = 1;
1215:     ctx.beginPath();
1216:     ctx.moveTo(c.x + 2, c.y);
1217:     ctx.bezierCurveTo(c.x + c.lean * .3 + 2, c.y + c.h * .3, c.x - c.lean * .4 + 2, c.y + c.h * .65, c.x + c.lean + 2, c.y + c.h);
1218:     ctx.stroke();
1219:   }
1220: 
1221:   // horizontal strata
1222:   for (const s of D.strata) {
1223:     ctx.strokeStyle = `rgba(4,9,10,${s.a})`;
1224:     ctx.lineWidth = s.w;
1225:     ctx.beginPath();
1226:     ctx.moveTo(-1000, s.y);
1227:     ctx.bezierCurveTo(-380, s.y + s.bend, 300, s.y - s.bend * .65, 1200, s.y + s.bend * .4);
