105:     this.engine = Engine.create({
106:       gravity: { x: 0, y: 1, scale: 0.001 },
107:       enableSleeping: false,
108:       positionIterations: 8,
109:       velocityIterations: 6,
110:       constraintIterations: 6,
111:     });
112:     this.world = this.engine.world;
113:     Composite.add(this.world, this.level.bodies);
114: 
115:     this.player = Bodies.circle(START.x, START.y, PLAYER_R, {
116:       mass: PLAYER_MASS,
117:       friction: 0.62,
118:       frictionStatic: 3.2,
119:       frictionAir: 0.006,
120:       restitution: 0.02,
121:       label: 'player',
122:       slop: 0.02,
123:     });
124:     Body.setInertia(this.player, Infinity);
125:     this.player.collisionFilter.group = -1;
126:     Composite.add(this.world, this.player);
127: 
128:     this.pole = Bodies.rectangle(START.x + 160, START.y - 40, POLE_LEN, 17, {
129:       mass: 6,
130:       friction: 0.98,
131:       frictionStatic: 4,
132:       frictionAir: 0.0025,
133:       restitution: 0.01,
134:       angle: -0.32,
135:       label: 'pole',
136:       slop: 0.02,
137:     });
138:     this.pole.collisionFilter.group = -1;
139:     Composite.add(this.world, this.pole);
140: 
141:     this.joint = Constraint.create({
142:       bodyA: this.player,
143:       pointA: { x: 18, y: -18 },
144:       bodyB: this.pole,
145:       pointB: { x: -POLE_HALF, y: 0 },
146:       length: 0,
147:       stiffness: 0.95,
148:       damping: 0.12,
149:     });
150:     Composite.add(this.world, this.joint);
151: 
152:     this.hook = {
153:       state: 'ready', // ready | flying | attached | retracting
154:       pos: { x: 0, y: 0 }, from: { x: 0, y: 0 }, to: { x: 0, y: 0 },
155:       anchor: null, ropeLen: 0, t: 0, dur: .1, miss: false,
156:       cooldown: 0, attachedFor: 0, reeled: 0,
157:     };
158: 
159:     Events.on(this.engine, 'collisionStart', (ev) => this.onCollision(ev));
160:     Events.on(this.engine, 'collisionActive', (ev) => this.onCollisionActive(ev));
161:   }
162: 
163:   onCollision(ev) {
164:     if (this.mode !== 'playing') return;
165:     for (const pair of ev.pairs) {
166:       const a = pair.bodyA, b = pair.bodyB;
167:       const rel = Vector.magnitude(Vector.sub(a.velocity, b.velocity));
168:       const poleHit = a === this.pole || b === this.pole;
169:       const playerHit = a === this.player || b === this.player;
170:       if (!poleHit && !playerHit) continue;
171:       const other = poleHit ? (a === this.pole ? b : a) : (a === this.player ? b : a);
172:       const type = other.plugin?.type || 'rock';
173:       if (poleHit && rel > 0.35) {
174:         this.audio.knock(type, rel * .8);
175:         this.addCameraShake(clamp(rel * 2.2, 0, 7));
176:         if (rel > 0.8) this.spawnImpact(this.pole.position, type, rel);
177:       }
178:       if (playerHit && rel > 0.65) {
179:         this.audio.thud(rel * .7);
180:         this.addCameraShake(clamp(rel * 3.4, 1, 12));
181:         this.spawnImpact(this.player.position, type, rel * .7);
182:       }
183:     }
184:   }
185: 
186:   onCollisionActive(ev) {
187:     if (this.mode !== 'playing') return;
188:     for (const pair of ev.pairs) {
189:       const a = pair.bodyA, b = pair.bodyB;
190:       if (a !== this.pole && b !== this.pole) continue;
191:       const other = a === this.pole ? b : a;
192:       const tip = this.poleTip();
193:       if (this.pole.angularVelocity !== 0 && this.time - this.lastDust > .09) {
194:         const speed = Math.abs(this.pole.angularVelocity) * POLE_HALF;
195:         if (speed > .75) {
196:           this.lastDust = this.time;
197:           this.spawnDust(tip, other.plugin?.type || 'rock', speed);
198:         }
199:       }
200:     }
201:   }
202: 
203:   /* ── setup helpers ─────────────────────────────────────── */
204:   setupInput() {
205:     window.addEventListener('resize', () => this.renderer.resize());
206:     window.addEventListener('mousemove', (e) => {
207:       this.mouse.x = e.clientX;
208:       this.mouse.y = e.clientY;
209:     });
210:     this.canvas.addEventListener('pointerdown', (e) => {
211:       if (this.mode !== 'playing') return;
212:       this.audio.init();
213:       if (e.button === 0) this.grip = true;
214:       if (e.button === 2) this.fireHook();
215:     });
216:     window.addEventListener('pointerup', (e) => {
217:       if (e.button === 0) this.grip = false;
218:       if (e.button === 2 && this.mode === 'playing') this.releaseHook();
219:     });
220:     this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
221:     window.addEventListener('wheel', (e) => {
222:       if (this.mode !== 'playing') return;
223:       e.preventDefault();
224:       const c = this.camera;
225:       c.userZoom = clamp(c.userZoom * (e.deltaY > 0 ? .94 : 1.06), .62, 1.5);
226:     }, { passive: false });
227: 
228:     window.addEventListener('keydown', (e) => {
229:       if (e.repeat) return;
230:       const k = e.key.toLowerCase();
231:       if (k === 'a' || k === 'arrowleft') this.keys.left = true;
232:       if (k === 'd' || k === 'arrowright') this.keys.right = true;
233:       if (k === 'm') this.toggleSound();
234:       if (k === 'r' && this.mode === 'playing') this.returnToCheckpoint(false);
235:       if (k === 'escape' || k === 'p') {
236:         if (this.mode === 'playing') this.pause();
237:         else if (this.mode === 'paused') this.resume();
238:       }
239:       if (k === 'h') {
240:         if (this.mode === 'title' || this.mode === 'paused') this.openHow();
241:       }
242:       if (this.debug && ['1', '2', '3', '4', '5'].includes(k)) {
243:         this.teleport(parseInt(k, 10) - 1);
244:       }
245:     });
246:     window.addEventListener('keyup', (e) => {
247:       const k = e.key.toLowerCase();
248:       if (k === 'a' || k === 'arrowleft') this.keys.left = false;
249:       if (k === 'd' || k === 'arrowright') this.keys.right = false;
250:     });
251:     document.addEventListener('visibilitychange', () => {
252:       if (document.hidden && this.mode === 'playing') this.pause();
253:     });
254:   }
255: 
256:   setupUI() {
257:     $('#begin-btn').addEventListener('click', () => { this.audio.init(); this.beginRun(); });
258:     $('#how-btn').addEventListener('click', () => this.openHow());
259:     $('#how-close').addEventListener('click', () => this.closeHow());
260:     $('#how-begin').addEventListener('click', () => { this.closeHow(); this.beginRun(); });
261:     $('#resume-btn').addEventListener('click', () => this.resume());
262:     $('#restart-btn').addEventListener('click', () => { this.resume(); this.returnToCheckpoint(false); });
263:     $('#quit-btn').addEventListener('click', () => this.backToTitle());
264:     $('#again-btn').addEventListener('click', () => { this.hide('#end-screen'); this.beginRun(); });
265:     $('#end-title-btn').addEventListener('click', () => this.backToTitle());
266: 
267:     this.updateSaveUI();
268:     $('#sound-lbl').textContent = this.audio.muted ? 'off' : 'on';
269:   }
270: 
271:   buildTrack() {
272:     const marks = $('#track-marks');
273:     const labels = $('#track-labels');
274:     marks.innerHTML = '';
275:     labels.innerHTML = '';
276:     const span = START.y - SUMMIT.y;
277:     for (const z of ZONES) {
278:       const lowY = Math.min(z.top, -10300);
279:       const highY = Math.max(z.bottom, SUMMIT.y);
280:       const lowP = clamp((START.y - lowY) / span, 0, 1) * 100;
281:       const highP = clamp((START.y - highY) / span, 0, 1) * 100;
282:       const m = document.createElement('span');
283:       m.className = 'track-mark';
284:       m.style.bottom = `${lowP}%`;
285:       marks.appendChild(m);
286:       const l = document.createElement('span');
287:       l.className = 'track-label';
288:       l.dataset.zone = z.id;
289:       l.textContent = z.name.replace('Wreck of the ', '').replace('Temple of the ', '');
290:       l.style.bottom = `${(lowP + highP) / 2}%`;
291:       if (l.style.bottom === '0%') l.style.bottom = '4%';
292:       labels.appendChild(l);
293:     }
294:   }
295: 
296:   /* ── game flow ─────────────────────────────────────────── */
297:   async boot() {
298:     try { await document.fonts.ready; } catch {}
299:     this.renderer.preload();
300:     this.mode = 'title';
301:     this.state = 'title';
302:     $('#loading').classList.add('gone');
303:     this.running = true;
304:     requestAnimationFrame(this.loop);
305:     setTimeout(() => { if (this.mode === 'title') this.showTitleIdle = true; }, 100);
306:   }
307: 
308:   beginRun() {
309:     this.hide('#title-screen');
310:     this.hide('#how-screen');
311:     this.hide('#pause-screen');
312:     this.hide('#end-screen');
313:     this.setHUD(true);
314:     this.mode = 'playing';
315:     this.stats = { falls: 0, resets: 0, hooks: 0 };
316:     this.elapsed = 0;
317:     this.checkpointIndex = this.startIndex;
318:     this.visitedZones = new Set([this.zone?.id]);
319:     this.tutorialStage = 0;
320:     this.tutorialClock = 0;
321:     this.endTimer = 0;
322:     this.chestOpen = 0;
323:     this.resetToStart(this.startIndex, false);
324:     this.audio.init();
325:     this.audio.setZone(this.level.zoneAt(this.player.position.y).id);
326:     const z = this.level.zoneAt(this.player.position.y);
327:     this.zone = z;
328:     this.visitedZones = new Set([z.id]);
329:     this.showZone(z, false);
330:     this.setHint('mouse', 'Move the mouse — the pole follows. Plant the tip. Pull.', 0);
331:     setTimeout(() => {
332:       if (this.mode === 'playing') this.say(NARRATION.start, 8000);
333:     }, 900);
334:     this.updateHUD();
335:   }
336: 
337:   backToTitle() {
338:     this.hide('#pause-screen');
339:     this.hide('#end-screen');
340:     this.hide('#how-screen');
341:     this.show('#title-screen');
342:     this.setHUD(false);
343:     this.mode = 'title';
344:     this.resetToStart(0, false);
345:     this.camera.x = START.x;
346:     this.camera.y = START.y - 30;
347:     this.camera.userZoom = 1;
348:     this.updateSaveUI();
349:   }
350: 
351:   pause() {
352:     if (this.mode !== 'playing') return;
353:     this.mode = 'paused';
354:     this.grip = false;
355:     this.releaseHook(true);
356:     $('#pause-alt').textContent = `${this.altitude()} m`;
357:     $('#pause-cp').textContent = CHECKPOINTS[this.checkpointIndex].name;
358:     $('#pause-falls').textContent = this.stats.falls;
359:     $('#pause-time').textContent = this.formatTime(this.elapsed);
360:     $('#pause-quote').textContent = [
361:       '“Even the sea takes a breath.”',
362:       '“A moment’s rest is just a fall that hasn’t started.”',
363:       '“The gold is not going anywhere. Unfortunately, neither are you.”',
364:       '“Consider your grip. Consider your life choices.”',
365:     ][Math.floor(Math.random() * 4)];
366:     $('#sound-lbl').textContent = this.audio.muted ? 'off' : 'on';
367:     this.show('#pause-screen');
368:   }
369: 
370:   resume() {
371:     if (this.mode !== 'paused') return;
372:     this.hide('#pause-screen');
373:     this.mode = 'playing';
374:     this.last = performance.now();
375:     this.audio.init();
376:   }
377: 
378:   openHow() {
379:     this.wasMode = this.mode;
380:     this.show('#how-screen');
381:     this.mode = 'how';
382:   }
383: 
384:   closeHow() {
385:     this.hide('#how-screen');
386:     this.mode = this.wasMode === 'playing' ? 'playing' : (this.wasMode || 'title');
387:     if (this.mode === 'title') this.show('#title-screen');
388:   }
389: 
390:   toggleSound() {
391:     this.audio.init();
392:     this.audio.setMuted(!this.audio.muted);
393:     $('#sound-lbl').textContent = this.audio.muted ? 'off' : 'on';
394:     if (!this.audio.muted) this.audio.uiClick();
395:   }
396: 
397:   resetToStart(cpIndex, toast = true) {
398:     const cp = CHECKPOINTS[clamp(cpIndex, 0, CHECKPOINTS.length - 1)];
399:     this.checkpointIndex = clamp(cpIndex, 0, CHECKPOINTS.length - 1);
400:     Body.setPosition(this.player, { x: cp.spawnX, y: cp.spawnY });
401:     Body.setVelocity(this.player, { x: 0, y: 0 });
402:     Body.setAngularVelocity(this.player, 0);
403:     this.placePole(-0.42);
404:     this.detachHook(true);
405:     this.peakY = this.player.position.y;
406:     this.fellThisDrop = false;
407:     this.lastFallNarration = -999;
408:     this.camera.x = this.player.position.x;
409:     this.camera.y = this.player.position.y - 40;
410:     if (toast) this.toast(`CHECKPOINT — ${cp.name}`);
411:     this.updateHUD();
412:   }
413: 
414:   placePole(angle = -0.3) {
415:     const px = this.player.position.x + Math.cos(angle) * POLE_HALF;
416:     const py = this.player.position.y + Math.sin(angle) * POLE_HALF;
417:     Body.setPosition(this.pole, { x: px, y: py });
418:     Body.setAngle(this.pole, angle);
419:     Body.setVelocity(this.pole, { x: 0, y: 0 });
420:     Body.setAngularVelocity(this.pole, 0);
421:   }
422: 
423:   returnToCheckpoint(silent = false) {
424:     if (this.mode !== 'playing' && !silent) return;
425:     this.stats.resets++;
426:     if (!silent) {
427:       this.audio.hookMiss();
428:       this.toast('RETURNED TO CHECKPOINT');
429:     }
430:     this.resetToStart(this.checkpointIndex, false);
431:     this.fellThisDrop = false;
432:     this.updateHUD();
433:   }
434: 
435:   seaRespawn() {
436:     this.stats.falls++;
437:     this.stats.resets++;
438:     this.audio.splash(1.2);
439:     this.splashFlash = 1;
440:     this.addFallParticles();
441:     this.resetToStart(this.checkpointIndex, false);
442:     this.toast('THE SEA RETURNS YOU');
443:     this.say('The sea is a generous host, and a terrible landlord.', 4500);
444:     this.updateHUD();
445:     this.saveProgress();
446:   }
447: 
448:   teleport(index) {
449:     this.checkpointIndex = clamp(index, 0, CHECKPOINTS.length - 1);
450:     this.resetToStart(this.checkpointIndex, true);
451:     this.mode = 'playing';
452:   }
453: 
454:   /* ── main loop ─────────────────────────────────────────── */
455:   loop(now) {
456:     if (!this.running) return;
457:     if (!this.last) this.last = now;
458:     let delta = now - this.last;
459:     this.last = now;
460:     if (delta > 90) delta = 90;
461:     const dt = delta / 1000;
462:     this.time += dt;
463: 
464:     if (this.mode === 'playing') {
465:       this.elapsed += dt;
466:       this.acc = (this.acc || 0) + delta;
467:       let steps = 0;
468:       while (this.acc >= STEP && steps < 4) {
469:         this.fixedUpdate(STEP / 1000);
470:         this.acc -= STEP;
471:         steps++;
472:       }
473:       if (steps === 4) this.acc = 0;
474:       this.frameUpdate(dt);
475:     } else if (this.mode === 'title' || this.mode === 'ending' || this.mode === 'how' || this.mode === 'paused') {
476:       // Keep the world gently alive on menus, but do not simulate play.
477:       if (this.mode === 'title') this.updateTitle(dt);
478:       if (this.mode === 'ending') this.updateEnding(dt);
479:     }
480: 
481:     this.updateCamera(dt);
482:     this.updateParticles(dt);
483:     this.updateUI(dt);
484:     this.audio.update(dt, this.poleSpeed(), this.altitude());
485: 
486:     this.renderer.draw(now / 1000, dt);
487:     requestAnimationFrame(this.loop);
488:   }
489: 
490:   poleSpeed() {
491:     return Math.abs(this.pole.angularVelocity) * POLE_HALF + Vector.magnitude(this.pole.velocity) * 60;
492:   }
493: 
494:   fixedUpdate(dt) {
495:     const p = this.player.position;
496:     this.mouse.wx = (this.mouse.x - this.renderer.w / 2) / this.camera.zoom + this.camera.x;
497:     this.mouse.wy = (this.mouse.y - this.renderer.h / 2) / this.camera.zoom + this.camera.y;
498: 
499:     const shoulder = this.shoulder();
500:     const aim = this.mouse;
501:     let target = Math.atan2(aim.wy - shoulder.y, aim.wx - shoulder.x);
502:     if (!Number.isFinite(target)) target = this.pole.angle;
503:     const diff = wrapAngle(target - this.pole.angle);
504: 
505:     // PD angular control — the pole has weight and fights back.
506:     const kP = this.grip ? 12.5 : 8.4;
507:     const kD = this.grip ? 690 : 520;
508:     const maxT = this.grip ? 20 : 15;
509:     let torque = diff * kP - this.pole.angularVelocity * kD;
510:     torque = clamp(torque, -maxT, maxT);
511:     this.pole.torque = torque;
512: 
513:     // Waddle assist
514:     const dir = (this.keys.right ? 1 : 0) - (this.keys.left ? 1 : 0);
515:     if (dir && this.grounded()) {
516:       Body.applyForce(this.player, p, { x: dir * 0.00115 * PLAYER_MASS, y: 0 });
517:       const maxV = 0.24;
518:       if (Math.abs(this.player.velocity.x) > maxV) {
519:         Body.setVelocity(this.player, { x: Math.sign(this.player.velocity.x) * maxV, y: this.player.velocity.y });
520:       }
521:     }
522: 
523:     // Hook physics
524:     if (this.hook.state === 'attached') this.applyHook(dt);
525: 
526:     Engine.update(this.engine, STEP);
527: 
528:     // Keep the player's barrel upright (the body inertia is locked; safety).
529:     Body.setAngle(this.player, 0);
530:     Body.setAngularVelocity(this.player, 0);
531: 
532:     // Guardrails: if something goes horribly right, recover.
533:     if (p.y > SEA_LIMIT + 100 && this.mode === 'playing') {
534:       this.seaRespawn();
535:     }
536:     const out = !Number.isFinite(p.x) || !Number.isFinite(p.y) || p.y > 5000 || Math.abs(p.x) > 5000;
537:     if (out) this.returnToCheckpoint(true);
538:   }
539: 
540:   frameUpdate(dt) {
541:     const p = this.player.position;
542:     const y = p.y;
543: 
544:     // altitude progress and falls
545:     const alt = (START.y - y) / PX_PER_M;
546:     if (y < this.peakY - 2) this.peakY = y;
547:     if (this.save.bestAlt < alt) {
548:       this.save.bestAlt = alt;
549:       if (this.time - this.lastSave > 4) {
550:         this.lastSave = this.time;
551:         this.saveProgress();
552:       }
553:     }
554:     if (!this.fellThisDrop && y > this.peakY + 430) {
555:       this.fellThisDrop = true;
556:       this.stats.falls++;
557:       this.audio.fallSting();
558:       if (this.time - this.lastFallNarration > 12) {
559:         this.lastFallNarration = this.time;
560:         this.say(FALL_LINES[Math.floor(Math.random() * FALL_LINES.length)], 4200);
561:       }
562:       this.updateHUD();
563:     }
564:     if (this.fellThisDrop && y < this.peakY - 120) this.fellThisDrop = false;
565: 
566:     // checkpoints
567:     const cp = CHECKPOINTS[this.checkpointIndex + 1];
568:     if (cp) {
569:       const near = Math.hypot(p.x - cp.x, p.y - cp.y) < 270;
570:       if (near && this.grounded()) {
571:         this.checkpointIndex++;
572:         this.audio.checkpoint();
573:         this.toast(`CHECKPOINT — ${cp.name}`);
574:         this.say(NARRATION.checkpoint, 4200);
575:         this.spawnGoldBurst({ x: cp.x, y: cp.y - 20 }, 18, false);
576:         this.saveProgress();
577:         this.updateHUD();
578:       }
579:     }
580: 
581:     // Zones
582:     const z = this.level.zoneAt(y);
583:     if (z && z.id !== this.zone.id) {
584:       this.zone = z;
585:       this.audio.setZone(z.id);
586:       this.showZone(z, true);
587:       if (!this.visitedZones.has(z.id)) {
588:         this.visitedZones.add(z.id);
589:         setTimeout(() => {
590:           if (this.mode === 'playing' && this.zone.id === z.id) this.say(z.quote, 7500);
591:         }, 1100);
592:       }
593:     }
594: 
595:     // tutorial hint stages
596:     this.tutorialClock += dt;
597:     if (this.tutorialStage === 0 && (this.tutorialClock > 7 || alt > 2)) this.tutorialStage = 1;
598:     if (this.tutorialStage === 1 && alt > 16) this.tutorialStage = 2;
599:     if (this.tutorialStage === 2 && this.stats.hooks > 0) this.tutorialStage = 3;
600:     if (this.tutorialStage === 0) {
601:       this.setHint('mouse', 'Move the mouse — the pole follows. Plant the tip. Pull.', 0);
602:     } else if (this.tutorialStage === 1) {
603:       this.setHint('lmb', 'Hold left mouse to grip. Lever the pole against a ledge.', 0);
604:     } else if (this.tutorialStage === 2) {
605:       this.setHint('rmb', 'Right mouse throws your hook. Hold to reel in.', 0);
606:     } else if (this.hook.state === 'attached') {
607:       this.setHint('reel', 'HOLD RIGHT MOUSE to haul in. Release to let go.', 0);
608:     } else {
609:       this.setHint('r', 'R returns you to the last checkpoint flag.', 0);
610:     }
611: 
612:     // hook aim / cooldown
613:     const h = this.hook;
614:     if (h.cooldown > 0) h.cooldown = Math.max(0, h.cooldown - dt);
615:     if (h.state === 'flying') {
616:       h.t += dt;
617:       const t = clamp(h.t / h.dur, 0, 1);
618:       const e = 1 - Math.pow(1 - t, 3);
619:       h.pos.x = lerp(h.from.x, h.to.x, e);
620:       h.pos.y = lerp(h.from.y, h.to.y, e);
621:       if (h.miss && Math.random() < .55) this.addParticle({
622:         x: h.pos.x, y: h.pos.y, vx: (Math.random() - .5) * 80, vy: (Math.random() - .5) * 80,
623:         life: .4, max: .4, size: 1.6, color: 'rgba(230,210,170,.5)', type: 'spark', grav: 0,
624:       });
625:       if (t >= 1) {
626:         if (h.miss) {
627:           h.state = 'retracting'; h.t = 0; h.dur = .16;
