229: export function buildLevel() {
230:   const bodies = [];
231:   const platforms = [];
232: 
233:   PLATFORMS.forEach((p, i) => {
234:     const g = platformGeometry(p);
235:     const body = M.Bodies.rectangle(g.cx, g.cy, g.len, p.t, {
236:       isStatic: true,
237:       angle: g.angle,
238:       friction: FRICTION[p.type] ?? .8,
239:       frictionStatic: 3,
240:       restitution: 0,
241:       label: 'terrain',
242:       chamfer: { radius: 2 },
243:     });
244:     body.plugin = { platform: p.id || `p${i}`, type: p.type };
245:     const item = {
246:       ...p,
247:       id: p.id || `p${i}`,
248:       ...g,
249:       body,
250:       index: i,
251:       friction: FRICTION[p.type] ?? .8,
252:     };
253:     bodies.push(body);
254:     platforms.push(item);
255:   });
256: 
257:   // Raycast segments from every static body's true world vertices.
258:   const segments = [];
259:   for (const plat of platforms) {
260:     const v = plat.body.vertices;
261:     for (let i = 0; i < v.length; i++) {
262:       const a = v[i], b = v[(i + 1) % v.length];
263:       segments.push({ ax: a.x, ay: a.y, bx: b.x, by: b.y, platform: plat });
264:     }
265:   }
266: 
267:   // Zone lookup helper
268:   const zoneAt = (y) => {
269:     for (const z of ZONES) if (y <= z.top && y > z.bottom) return z;
270:     return y > ZONES[0].top ? ZONES[0] : ZONES[ZONES.length - 1];
271:   };
272: 
273:   return {
274:     bodies, platforms, segments, zoneAt,
275:     checkpoints: CHECKPOINTS,
276:     props: PROPS,
277:     undercliff: UNDERCLIFF,
278:     start: START, summit: SUMMIT, seaY: SEA_Y, world: WORLD,
279:   };
280: }
