33:   // grain
34:   ctx.save();
35:   rr(ctx, -L / 2, -T / 2, L, T, T / 2);
36:   ctx.clip();
37:   ctx.strokeStyle = 'rgba(64,40,16,.4)';
38:   ctx.lineWidth = .9;
39:   for (let i = 0; i < 4; i++) {
