56:   }
57:   // high light
58:   ctx.strokeStyle = 'rgba(255,222,166,.28)';
59:   ctx.lineWidth = 1.4;
60:   ctx.beginPath();
61:   ctx.moveTo(-L / 2 + 8, -T / 2 + 3.5);
