75:   }
76:   ctx.strokeStyle = 'rgba(156,110,62,.35)';
77:   ctx.lineWidth = 1;
78:   for (let i = 0; i < 6; i++) {
79:     const x = -L / 2 + 9 + i * 6;
80:     ctx.beginPath();
81:     ctx.moveTo(x, -T / 2 + 1);
82:     ctx.lineTo(x + 3, T / 2 - 1);
