19:     const x = -L / 2 + (i / topN) * L;
20:     const y = -T / 2 + (i === 0 || i === topN ? 0 : (rand() - .5) * 1.1);
21:     pts.push({ x, y });
22:   }
23:   // near-vertical ends keep the shelf reading as a shelf
24:   const side = Math.min(14, T * .16);
25:   pts.push({ x: L / 2 - 1, y: -T / 2 + T * .26 });
26:   pts.push({ x: L / 2 - side, y: T / 2 });
27:   const botN = Math.max(4, Math.round(L / 70));
28:   for (let i = botN; i >= 0; i--) {
29:     const u = i / botN;
30:     const x = -L / 2 + (.01 + u * .98) * L;
31:     const extra = T * (.02 + rand() * .28);
32:     const tooth = rand() > .72 ? 12 + rand() * 24 : 0;
33:     pts.push({ x, y: T / 2 + extra + tooth });
34:   }
35:   pts.push({ x: -L / 2 + side, y: T / 2 });
36:   pts.push({ x: -L / 2 + 1, y: -T / 2 + T * .26 });
37:   return pts;
38: }
