816: export function drawChest(ctx, x, y, time, open, scale = 1) {
817:   ctx.save();
818:   ctx.translate(x, y);
819:   ctx.scale(scale, scale);
820:   shadowBlob(ctx, 0, 3, 52, 10, .35);
