830:   rr(ctx, -44, -34, 88, 38, 3); ctx.fill();
831:   ctx.strokeStyle = '#2a1707'; ctx.lineWidth = 2.4; ctx.stroke();
832:   // bands
833:   ctx.fillStyle = '#c79b45';
834:   for (const bx of [-26, 26]) ctx.fillRect(bx - 3, -34, 6, 38);
835:   ctx.fillStyle = '#e3ba62';
836:   // lid
837:   ctx.save();
838:   ctx.translate(0, -34);
839:   ctx.rotate(-open * 1.12);
840:   const lidG = ctx.createLinearGradient(0, -26, 0, 0);
841:   lidG.addColorStop(0, '#a06c2e');
842:   lidG.addColorStop(1, '#6d4519');
843:   ctx.fillStyle = lidG;
844:   ctx.beginPath();
845:   ctx.moveTo(-44, 0);
846:   ctx.quadraticCurveTo(-44, -28, -22, -30);
847:   ctx.lineTo(22, -30);
848:   ctx.quadraticCurveTo(44, -28, 44, 0);
849:   ctx.closePath();
850:   ctx.fill();
851:   ctx.strokeStyle = '#2a1707'; ctx.lineWidth = 2.4; ctx.stroke();
852:   ctx.fillStyle = '#c79b45';
853:   for (const bx of [-26, 26]) ctx.fillRect(bx - 3, -28, 6, 28);
854:   ctx.restore();
855:   // gold interior
856:   if (open > .05) {
857:     ctx.fillStyle = 'rgba(255,224,140,.9)';
858:     ctx.fillRect(-40, -36, 80, 6 + open * 6);
859:     ctx.fillStyle = '#ffe9a8';
860:     ctx.beginPath(); ctx.ellipse(0, -34, 36, 6, 0, 0, TAU); ctx.fill();
