308:   drawClouds(t, prog) {
309:     const { ctx, w, h } = this;
310:     const z = this.cam.zoom;
311:     const sunX = w * .23;
312:     const sunY = h * (.47 - prog * .52);
313:     ctx.save();
314:     for (const c of this.clouds) {
315:       const f = .18;
316:       const sx = (c.x - this.cam.x * f) * z * .7 + w * .5 + Math.sin(t * .02 + c.y) * 14;
317:       const sy = (c.y - this.cam.y * f) * z * .7 + h * .5;
318:       if (sy < -220 * c.s || sy > h + 220 * c.s) continue;
319:       if (sx < -420 * c.s || sx > w + 420 * c.s) continue;
320:       const alpha = c.a * (1 - prog * .2) * 1.25;
321:       ctx.globalAlpha = alpha;
322:       const sprite = c.warm > prog * 1.2 ? this.cloudSprite : this.cloudSpriteCool;
323:       const cw = 512 * c.s * .7, ch = 220 * c.s * .7;
324:       ctx.drawImage(sprite, sx - cw / 2, sy - ch / 2, cw, ch);
325:     }
326:     ctx.restore();
327: 
328:     // lit cloud banks around the low sun
329:     ctx.save();
330:     ctx.globalCompositeOperation = 'lighter';
331:     const banks = [
332:       [0, -.09, 420, 30, .13],
333:       [.14, .04, 520, 24, .1],
334:       [-.13, .12, 360, 20, .08],
335:       [.05, -.2, 620, 34, .07],
336:     ];
337:     for (const [dx, dy, bw, bh, a] of banks) {
338:       const bx = sunX + w * dx, by = sunY + h * dy;
339:       const bg = ctx.createRadialGradient(bx, by, 0, bx, by, bw);
340:       bg.addColorStop(0, `rgba(255,214,158,${a * (1 - prog * .4)})`);
341:       bg.addColorStop(.55, `rgba(240,178,128,${a * .4 * (1 - prog * .4)})`);
342:       bg.addColorStop(1, 'rgba(240,178,128,0)');
343:       ctx.fillStyle = bg;
344:       ctx.beginPath();
345:       ctx.ellipse(bx, by, bw, bh, 0, 0, TAU);
346:       ctx.fill();
347:     }
348:     ctx.restore();
349: 
350:     // a few birds riding the warm air
351:     ctx.save();
352:     ctx.strokeStyle = `rgba(34,52,52,${.5 * (1 - prog * .5)})`;
353:     ctx.lineWidth = 1.4;
354:     for (let i = 0; i < 5; i++) {
355:       const bx = w * (.3 + i * .1) + Math.sin(t * .18 + i) * 20;
356:       const by = h * (.23 + (i % 3) * .05) + Math.sin(t * .7 + i * 2) * 5;
357:       const fl = Math.sin(t * 3.2 + i) * 4;
358:       const s = 3 + (i % 2) * 2;
359:       ctx.beginPath();
360:       ctx.moveTo(bx - s, by + fl * .3);
361:       ctx.quadraticCurveTo(bx - s * .4, by - s * .5 - fl, bx, by);
362:       ctx.quadraticCurveTo(bx + s * .4, by - s * .5 - fl, bx + s, by + fl * .3);
363:       ctx.stroke();
364:     }
365:     ctx.restore();
366:   }
