57: function palm(ctx, time, rand) {
58:   const h = 130 + rand() * 70;
59:   const sway = Math.sin(time * .7 + rand() * 9) * 3;
60:   shadowBlob(ctx, 4, 3, 42, 10, .28);
61:   // base rocks
62:   ctx.fillStyle = '#3c3a2b';
63:   blob(ctx, 0, 0, 24, 8, rand, 7, .2); ctx.fill();
64:   // trunk
65:   ctx.strokeStyle = '#5e4428';
66:   ctx.lineWidth = 8;
67:   ctx.lineCap = 'round';
68:   ctx.beginPath();
69:   ctx.moveTo(0, -4);
70:   ctx.bezierCurveTo(2, -h * .35, 12, -h * .7, 8 + sway, -h);
71:   ctx.stroke();
72:   ctx.strokeStyle = 'rgba(176,134,82,.4)';
73:   ctx.lineWidth = 2.2;
74:   ctx.beginPath();
75:   ctx.moveTo(-2, -6);
76:   ctx.bezierCurveTo(0, -h * .35, 10, -h * .7, 6 + sway, -h);
77:   ctx.stroke();
78:   // trunk rings
79:   ctx.strokeStyle = 'rgba(48,31,16,.55)';
80:   ctx.lineWidth = 1;
81:   for (let i = 1; i < 8; i++) {
82:     const t = i / 8;
83:     const x = lerp(0, 8 + sway, t) + Math.sin(t * 3) * 5;
84:     const y = -h * t;
85:     ctx.beginPath();
86:     ctx.moveTo(x - 4, y);
87:     ctx.quadraticCurveTo(x, y + 2, x + 4, y);
88:     ctx.stroke();
89:   }
90:   // fronds
91:   const topX = 8 + sway, topY = -h;
92:   const n = 7;
93:   for (let i = 0; i < n; i++) {
94:     const a = -Math.PI * .95 + (i / (n - 1)) * Math.PI * 1.9 + Math.sin(time * .8 + i) * .04;
95:     const len = 46 + (i % 3) * 14;
96:     const ex = topX + Math.cos(a) * len;
97:     const ey = topY + Math.sin(a) * len * .55 + 12;
98:     const mx = topX + Math.cos(a) * len * .55;
99:     const my = topY + Math.sin(a) * len * .55 - 10;
100:     const px = -Math.sin(a) * 9, py = Math.cos(a) * 4;
101:     ctx.fillStyle = i % 3 === 0 ? '#496b37' : i % 3 === 1 ? '#3d5c2e' : '#557a3e';
102:     ctx.beginPath();
103:     ctx.moveTo(topX, topY);
104:     ctx.quadraticCurveTo(mx + px, my + py, ex, ey);
105:     ctx.quadraticCurveTo(mx - px, my - py, topX, topY);
106:     ctx.fill();
107:     ctx.strokeStyle = 'rgba(24,38,18,.5)';
108:     ctx.lineWidth = .8;
109:     ctx.beginPath();
110:     ctx.moveTo(topX, topY);
111:     ctx.quadraticCurveTo(mx, my, ex, ey);
112:     ctx.stroke();
113:     // leaf notches
114:     for (let j = 1; j < 5; j++) {
115:       const t = j / 5;
116:       const lx = lerp(topX, ex, t) + Math.cos(a + 1.57) * 4;
117:       const ly = lerp(topY, ey, t) + Math.sin(a + 1.57) * 4;
118:       ctx.beginPath();
119:       ctx.moveTo(lx, ly - 2);
120:       ctx.lineTo(lx + Math.cos(a + 1.2) * 9, ly + Math.sin(a + 1.2) * 9 + 2);
121:       ctx.stroke();
122:     }
123:   }
124:   // coconuts
125:   ctx.fillStyle = '#4a3520';
126:   for (let i = 0; i < 3; i++) {
127:     ctx.beginPath();
128:     ctx.arc(topX + (rand() - .5) * 10, topY + 4 + (rand() - .5) * 6, 3.2, 0, TAU);
129:     ctx.fill();
130:   }
131: }
