137:     const len = 26 + rand() * 26;
138:     const sway = Math.sin(time * 1.1 + i) * 2;
139:     const ex = Math.cos(a) * len + sway, ey = Math.sin(a) * len * .5 - len * .4;
140:     ctx.strokeStyle = '#4b6b39';
141:     ctx.lineWidth = 1.6;
142:     ctx.beginPath();
