100:     for (let r = 0; r < rows; r++) {
101:       const off = (r % 2) * 26 + rand() * 10;
102:       for (let x = -L / 2 + off; x < L / 2; x += 52 + rand() * 12) {
103:         tex.blocks.push({ x, y: -T / 2 + (r / rows) * T, h: T / rows, w: 46 + rand() * 18 });
104:       }
105:     }
106:     // loose stones that sit on broad shoulders
107:     for (let i = 0; i < Math.min(7, Math.max(2, Math.floor(L / 90))); i++) {
108:       tex.boulders.push({ x: (rand() - .5) * L * .9, r: 3.5 + rand() * 8, a: rand() });
109:     }
110:     for (let i = 0; i < Math.floor(L / 34); i++) {
111:       tex.lichen.push({ x: (rand() - .5) * L * .94, y: (rand() - .5) * T * .7, r: 4 + rand() * 14, a: .04 + rand() * .1 });
112:     }
113:     for (let i = 0; i < Math.max(2, Math.floor(L / 10)); i++) {
114:       tex.vines.push({ x: (rand() - .5) * L * .95, len: 14 + rand() * 70, lean: (rand() - .5) * 8, a: rand() });
115:     }
116:     p.tex = tex;
117:     p.shape = buildLedgeShape(p, rand);
118:     p.seed = rand();
119:   }
120: }
