122: /** Unused large silhouette, kept for compatibility. */
123: export function drawIslandBackdrop(ctx, game, time) {
124:   if (!game._island) {
125:     const rand = mulberry32(99181);
126:     const pts = [];
127:     for (let y = 520; y >= -10520; y -= 260) {
128:       const k = (520 - y) / 11040;
129:       const cx = 170 * Math.sin(y / 1180) + 120 * Math.sin(y / 430 + 1.2) + 120;
130:       const w = 760 + 230 * Math.sin(y / 840 + .6) + 120 * Math.sin(y / 330) + lerp(120, -80, k);
131:       pts.push({ y, left: cx - w / 2 + (rand() - .5) * 90, right: cx + w / 2 + (rand() - .5) * 90, cx });
132:     }
133:     game._island = pts;
134:   }
135:   const pts = game._island;
136:   ctx.save();
137:   ctx.beginPath();
138:   ctx.moveTo(pts[0].left, pts[0].y);
139:   for (let i = 1; i < pts.length; i++) {
140:     const a = pts[i - 1], b = pts[i];
141:     ctx.quadraticCurveTo(a.left, (a.y + b.y) / 2, (a.left + b.left) / 2, (a.y + b.y) / 2);
142:   }
143:   for (let i = pts.length - 1; i >= 0; i--) {
144:     const b = pts[i], a = pts[Math.max(0, i - 1)];
145:     if (i === pts.length - 1) ctx.lineTo(b.right, b.y);
146:     else ctx.quadraticCurveTo(b.right, (a.y + b.y) / 2, (b.right + a.right) / 2, (a.y + b.y) / 2);
147:   }
148:   ctx.closePath();
149:   const g = ctx.createLinearGradient(0, 500, 0, -10600);
150:   g.addColorStop(0, '#3b2f21');
151:   g.addColorStop(.15, '#2a3025');
152:   g.addColorStop(.35, '#23352b');
153:   g.addColorStop(.55, '#252f2c');
154:   g.addColorStop(.78, '#2b2d2b');
155:   g.addColorStop(1, '#24282c');
156:   ctx.fillStyle = g;
157:   ctx.fill();
158:   ctx.restore();
159: }
