273:   return {
274:     bodies, platforms, segments, zoneAt,
275:     checkpoints: CHECKPOINTS,
276:     props: PROPS,
277:     undercliff: UNDERCLIFF,
278:     start: START, summit: SUMMIT, seaY: SEA_Y, world: WORLD,
279:   };
280: }
