209:   drawStars(prog, t) {
210:     const { ctx, w, h } = this;
211:     const a = clamp((prog - .28) / .45, 0, 1);
212:     if (a <= .01) return;
213:     ctx.save();
214:     for (const s of this.stars) {
215:       const tw = .55 + .45 * Math.sin(t * 1.7 + s.tw);
216:       ctx.fillStyle = `rgba(225,236,236,${a * s.a * tw})`;
217:       ctx.beginPath();
218:       ctx.arc(s.x * w, s.y * h, s.r * (s.big ? 1.5 : 1), 0, TAU);
219:       ctx.fill();
220:       if (s.big) {
221:         ctx.strokeStyle = `rgba(220,235,240,${a * .22 * tw})`;
222:         ctx.lineWidth = .7;
223:         ctx.beginPath();
224:         ctx.moveTo(s.x * w - 5, s.y * h);
225:         ctx.lineTo(s.x * w + 5, s.y * h);
226:         ctx.moveTo(s.x * w, s.y * h - 5);
227:         ctx.lineTo(s.x * w, s.y * h + 5);
228:         ctx.stroke();
229:       }
230:     }
231:     ctx.restore();
232:   }
