801:   /* ── geometry helpers ──────────────────────────────────── */
802:   shoulder() {
803:     return { x: this.player.position.x + 18, y: this.player.position.y - 18 };
804:   }
805:   hand() {
806:     return { x: this.player.position.x - 26, y: this.player.position.y + 4 };
807:   }
808:   poleTip() {
809:     const a = this.pole.angle;
810:     return {
811:       x: this.pole.position.x + Math.cos(a) * POLE_HALF,
812:       y: this.pole.position.y + Math.sin(a) * POLE_HALF,
813:     };
814:   }
815:   grounded() {
816:     const p = this.player.position;
817:     for (let i = -2; i <= 2; i++) {
818:       const x = p.x + i * 16;
819:       const hit = castRay(this.level.segments, x, p.y, x, p.y + PLAYER_R + 18);
820:       if (hit && hit.dist <= PLAYER_R + 20) return true;
821:     }
822:     return false;
823:   }
824:   altitude() {
825:     return Math.max(0, Math.round((START.y - this.player.position.y) / PX_PER_M));
826:   }
827:   progress() {
828:     return clamp((START.y - this.player.position.y) / (START.y - SUMMIT.y), 0, 1);
829:   }
830:   formatTime(s) {
831:     const m = Math.floor(s / 60);
832:     const sec = Math.floor(s % 60);
833:     return `${m}:${String(sec).padStart(2, '0')}`;
834:   }
835:   updateMouseWorld() {
836:     this.mouse.wx = (this.mouse.x - this.renderer.w / 2) / this.camera.zoom + this.camera.x;
837:     this.mouse.wy = (this.mouse.y - this.renderer.h / 2) / this.camera.zoom + this.camera.y;
838:   }
839: 
840:   /* ── camera / particles ────────────────────────────────── */
841:   updateCamera(dt) {
842:     if (this.mode === 'playing') {
843:       const p = this.player.position;
844:       const v = this.player.velocity;
845:       const targetX = clamp(p.x + 30, -720, 780);
846:       const targetY = p.y - 138 + clamp(v.y * 42, -130, 180);
847:       this.camera.x = damp(this.camera.x, targetX, 5.2, dt);
848:       this.camera.y = damp(this.camera.y, targetY, 5.2, dt);
849:       const targetZoom = this.camera.baseZoom * this.camera.userZoom;
850:       this.camera.zoom = damp(this.camera.zoom, targetZoom, 3.2, dt);
851:     } else if (this.mode === 'title' || this.mode === 'ending') {
852:       // handled elsewhere
853:     } else {
854:       this.camera.zoom = damp(this.camera.zoom, this.camera.baseZoom * this.camera.userZoom, 3, dt);
855:     }
856:     this.camera.shakeTime += dt;
857:     this.camera.shake = Math.max(0, this.camera.shake - dt * 15);
858:     const s = this.camera.shake;
859:     this.camera.shakeX = Math.sin(this.camera.shakeTime * 93) * s + Math.sin(this.camera.shakeTime * 47) * s * .5;
860:     this.camera.shakeY = Math.cos(this.camera.shakeTime * 81) * s + Math.cos(this.camera.shakeTime * 53) * s * .5;
861:   }
862: 
863:   addCameraShake(n) {
864:     this.camera.shake = Math.min(16, this.camera.shake + n);
865:   }
866: 
867:   updateParticles(dt) {
868:     const ps = this.particles;
869:     for (let i = ps.length - 1; i >= 0; i--) {
870:       const q = ps[i];
871:       q.life -= dt;
872:       if (q.life <= 0) { ps.splice(i, 1); continue; }
873:       q.vy += (q.grav || 0) * dt;
874:       q.vx *= (1 - (q.drag || 0) * dt);
875:       q.vy *= (1 - (q.drag || 0) * dt);
876:       q.x += q.vx * dt;
877:       q.y += q.vy * dt;
878:       if (q.rot !== undefined) q.rot += (q.spin || 0) * dt;
879:     }
880:     if (ps.length > 620) ps.splice(0, ps.length - 620);
881:   }
882: 
883:   addParticle(o) {
884:     this.particles.push(o);
885:   }
886: 
887:   spawnDust(pos, type, speed) {
888:     const color = type === 'sand' ? 'rgba(214,186,132,.5)'
889:       : type === 'moss' ? 'rgba(116,146,84,.5)'
890:         : type === 'stone' ? 'rgba(170,168,150,.42)'
891:           : 'rgba(150,120,82,.5)';
892:     for (let i = 0; i < 3; i++) {
893:       this.addParticle({
894:         x: pos.x + (Math.random() - .5) * 10,
895:         y: pos.y + (Math.random() - .5) * 10,
896:         vx: (Math.random() - .5) * 90,
897:         vy: -Math.random() * 50,
898:         life: .45 + Math.random() * .35, max: .8,
899:         size: 1.5 + Math.random() * 2.6,
900:         color, type: 'dust', grav: 160, drag: 1.4,
901:       });
902:     }
903:   }
904: 
905:   spawnImpact(pos, type, power) {
906:     const colors = {
907:       sand: 'rgba(226,199,144,.8)', wood: 'rgba(168,121,70,.8)', deck: 'rgba(168,121,70,.8)',
908:       rock: 'rgba(190,184,160,.75)', moss: 'rgba(133,166,96,.8)', stone: 'rgba(205,200,180,.8)', gold: 'rgba(255,220,130,.9)',
909:     };
910:     const c = colors[type] || colors.rock;
911:     const n = Math.min(18, 4 + Math.floor(power * 7));
912:     for (let i = 0; i < n; i++) {
913:       const a = Math.random() * Math.PI * 2;
914:       const sp = 30 + Math.random() * 180 * Math.min(1.6, power);
915:       this.addParticle({
916:         x: pos.x, y: pos.y,
917:         vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 30,
918:         life: .35 + Math.random() * .6, max: .95,
919:         size: 1 + Math.random() * 2.8, color: c, type: type === 'stone' || type === 'gold' ? 'spark' : 'dust',
920:         grav: 300, drag: .8,
921:       });
