47:     this.mouse = { x: window.innerWidth / 2, y: window.innerHeight / 2, wx: 0, wy: 0 };
48:     this.keys = { left: false, right: false };
49:     this.grip = false;
50:     this.running = false;
51: 
52:     this.stats = { falls: 0, resets: 0, hooks: 0 };
53:     this.checkpointIndex = 0;
54:     this.visitedZones = new Set();
55:     this.zone = ZONES[0];
56:     this.peakY = START.y;
57:     this.fellThisDrop = false;
58:     this.lastFallNarration = -999;
59:     this.tutorialStage = 0;
60:     this.tutorialClock = 0;
61:     this.hintKey = '';
62:     this.hintUntil = 0;
63:     this.toastTimer = 0;
64:     this.bannerTimer = 0;
65:     this.narrationTimer = 0;
66:     this.camera = {
67:       x: START.x, y: START.y, zoom: 1, baseZoom: .8, userZoom: 1,
68:       shake: 0, shakeTime: 0, shakeX: 0, shakeY: 0,
69:     };
70:     this.splashFlash = 0;
71:     this.endTimer = 0;
72:     this.chestOpen = 0;
73:     this.waterTime = 0;
74:     this.particles = [];
75:     this.lastPoleKnock = 0;
76:     this.lastDust = 0;
77:     this.aimSwing = 0;
78:     this.lastSave = 0;
79:     this.debug = params.has('debug');
80:     this.startIndex = 0;
81:     if (params.has('cp')) {
82:       const idx = parseInt(params.get('cp'), 10);
83:       if (!Number.isNaN(idx)) this.startIndex = clamp(idx, 0, CHECKPOINTS.length - 1);
84:     }
85:     if (params.has('summit')) this.startIndex = CHECKPOINTS.length - 1;
86: 
87:     this.save = this.loadSave();
