390:   toggleSound() {
391:     this.audio.init();
392:     this.audio.setMuted(!this.audio.muted);
393:     $('#sound-lbl').textContent = this.audio.muted ? 'off' : 'on';
394:     if (!this.audio.muted) this.audio.uiClick();
395:   }
396: 
397:   resetToStart(cpIndex, toast = true) {
398:     const cp = CHECKPOINTS[clamp(cpIndex, 0, CHECKPOINTS.length - 1)];
399:     this.checkpointIndex = clamp(cpIndex, 0, CHECKPOINTS.length - 1);
400:     Body.setPosition(this.player, { x: cp.spawnX, y: cp.spawnY });
401:     Body.setVelocity(this.player, { x: 0, y: 0 });
402:     Body.setAngularVelocity(this.player, 0);
403:     this.placePole(-0.42);
404:     this.detachHook(true);
405:     this.peakY = this.player.position.y;
406:     this.fellThisDrop = false;
407:     this.lastFallNarration = -999;
408:     this.camera.x = this.player.position.x;
409:     this.camera.y = this.player.position.y - 40;
410:     if (toast) this.toast(`CHECKPOINT — ${cp.name}`);
411:     this.updateHUD();
412:   }
413: 
414:   placePole(angle = -0.3) {
415:     const px = this.player.position.x + Math.cos(angle) * POLE_HALF;
416:     const py = this.player.position.y + Math.sin(angle) * POLE_HALF;
417:     Body.setPosition(this.pole, { x: px, y: py });
418:     Body.setAngle(this.pole, angle);
419:     Body.setVelocity(this.pole, { x: 0, y: 0 });
420:     Body.setAngularVelocity(this.pole, 0);
421:   }
422: 
423:   returnToCheckpoint(silent = false) {
424:     if (this.mode !== 'playing' && !silent) return;
425:     this.stats.resets++;
426:     if (!silent) {
427:       this.audio.hookMiss();
428:       this.toast('RETURNED TO CHECKPOINT');
429:     }
430:     this.resetToStart(this.checkpointIndex, false);
431:     this.fellThisDrop = false;
432:     this.updateHUD();
433:   }
434: 
435:   seaRespawn() {
436:     this.stats.falls++;
437:     this.stats.resets++;
438:     this.audio.splash(1.2);
439:     this.splashFlash = 1;
440:     this.addFallParticles();
441:     this.resetToStart(this.checkpointIndex, false);
442:     this.toast('THE SEA RETURNS YOU');
443:     this.say('The sea is a generous host, and a terrible landlord.', 4500);
444:     this.updateHUD();
445:     this.saveProgress();
446:   }
447: 
448:   teleport(index) {
449:     this.checkpointIndex = clamp(index, 0, CHECKPOINTS.length - 1);
450:     this.resetToStart(this.checkpointIndex, true);
451:     this.mode = 'playing';
452:   }
453: 
454:   /* ── main loop ─────────────────────────────────────────── */
455:   loop(now) {
456:     if (!this.running) return;
457:     if (!this.last) this.last = now;
458:     let delta = now - this.last;
459:     this.last = now;
460:     if (delta > 90) delta = 90;
461:     const dt = delta / 1000;
462:     this.time += dt;
463: 
464:     if (this.mode === 'playing') {
465:       this.elapsed += dt;
466:       this.acc = (this.acc || 0) + delta;
467:       let steps = 0;
468:       while (this.acc >= STEP && steps < 4) {
469:         this.fixedUpdate(STEP / 1000);
470:         this.acc -= STEP;
471:         steps++;
472:       }
473:       if (steps === 4) this.acc = 0;
474:       this.frameUpdate(dt);
475:     } else if (this.mode === 'title' || this.mode === 'ending' || this.mode === 'how' || this.mode === 'paused') {
476:       // Keep the world gently alive on menus, but do not simulate play.
477:       if (this.mode === 'title') this.updateTitle(dt);
478:       if (this.mode === 'ending') this.updateEnding(dt);
479:     }
480: 
481:     this.updateCamera(dt);
482:     this.updateParticles(dt);
483:     this.updateUI(dt);
484:     this.audio.update(dt, this.poleSpeed(), this.altitude());
485: 
486:     this.renderer.draw(now / 1000, dt);
487:     requestAnimationFrame(this.loop);
488:   }
489: 
490:   poleSpeed() {
491:     return Math.abs(this.pole.angularVelocity) * POLE_HALF + Vector.magnitude(this.pole.velocity) * 60;
492:   }
493: 
494:   fixedUpdate(dt) {
495:     const p = this.player.position;
496:     this.mouse.wx = (this.mouse.x - this.renderer.w / 2) / this.camera.zoom + this.camera.x;
497:     this.mouse.wy = (this.mouse.y - this.renderer.h / 2) / this.camera.zoom + this.camera.y;
498: 
499:     const shoulder = this.shoulder();
500:     const aim = this.mouse;
501:     let target = Math.atan2(aim.wy - shoulder.y, aim.wx - shoulder.x);
502:     if (!Number.isFinite(target)) target = this.pole.angle;
503:     const diff = wrapAngle(target - this.pole.angle);
504: 
505:     // PD angular control — the pole has weight and fights back.
506:     const kP = this.grip ? 12.5 : 8.4;
507:     const kD = this.grip ? 690 : 520;
508:     const maxT = this.grip ? 20 : 15;
509:     let torque = diff * kP - this.pole.angularVelocity * kD;
510:     torque = clamp(torque, -maxT, maxT);
511:     this.pole.torque = torque;
512: 
513:     // Waddle assist
514:     const dir = (this.keys.right ? 1 : 0) - (this.keys.left ? 1 : 0);
515:     if (dir && this.grounded()) {
516:       Body.applyForce(this.player, p, { x: dir * 0.00115 * PLAYER_MASS, y: 0 });
517:       const maxV = 0.24;
518:       if (Math.abs(this.player.velocity.x) > maxV) {
519:         Body.setVelocity(this.player, { x: Math.sign(this.player.velocity.x) * maxV, y: this.player.velocity.y });
520:       }
521:     }
522: 
523:     // Hook physics
524:     if (this.hook.state === 'attached') this.applyHook(dt);
525: 
526:     Engine.update(this.engine, STEP);
527: 
528:     // Keep the player's barrel upright (the body inertia is locked; safety).
529:     Body.setAngle(this.player, 0);
530:     Body.setAngularVelocity(this.player, 0);
531: 
532:     // Guardrails: if something goes horribly right, recover.
533:     if (p.y > SEA_LIMIT + 100 && this.mode === 'playing') {
534:       this.seaRespawn();
535:     }
536:     const out = !Number.isFinite(p.x) || !Number.isFinite(p.y) || p.y > 5000 || Math.abs(p.x) > 5000;
537:     if (out) this.returnToCheckpoint(true);
538:   }
539: 
540:   frameUpdate(dt) {
541:     const p = this.player.position;
542:     const y = p.y;
543: 
544:     // altitude progress and falls
545:     const alt = (START.y - y) / PX_PER_M;
546:     if (y < this.peakY - 2) this.peakY = y;
547:     if (this.save.bestAlt < alt) {
548:       this.save.bestAlt = alt;
549:       if (this.time - this.lastSave > 4) {
550:         this.lastSave = this.time;
551:         this.saveProgress();
552:       }
553:     }
554:     if (!this.fellThisDrop && y > this.peakY + 430) {
555:       this.fellThisDrop = true;
556:       this.stats.falls++;
557:       this.audio.fallSting();
558:       if (this.time - this.lastFallNarration > 12) {
559:         this.lastFallNarration = this.time;
560:         this.say(FALL_LINES[Math.floor(Math.random() * FALL_LINES.length)], 4200);
561:       }
562:       this.updateHUD();
563:     }
564:     if (this.fellThisDrop && y < this.peakY - 120) this.fellThisDrop = false;
565: 
566:     // checkpoints
567:     const cp = CHECKPOINTS[this.checkpointIndex + 1];
568:     if (cp) {
569:       const near = Math.hypot(p.x - cp.x, p.y - cp.y) < 270;
570:       if (near && this.grounded()) {
571:         this.checkpointIndex++;
572:         this.audio.checkpoint();
573:         this.toast(`CHECKPOINT — ${cp.name}`);
574:         this.say(NARRATION.checkpoint, 4200);
575:         this.spawnGoldBurst({ x: cp.x, y: cp.y - 20 }, 18, false);
576:         this.saveProgress();
577:         this.updateHUD();
578:       }
579:     }
580: 
581:     // Zones
582:     const z = this.level.zoneAt(y);
583:     if (z && z.id !== this.zone.id) {
584:       this.zone = z;
585:       this.audio.setZone(z.id);
586:       this.showZone(z, true);
587:       if (!this.visitedZones.has(z.id)) {
588:         this.visitedZones.add(z.id);
589:         setTimeout(() => {
590:           if (this.mode === 'playing' && this.zone.id === z.id) this.say(z.quote, 7500);
591:         }, 1100);
592:       }
593:     }
594: 
595:     // tutorial hint stages
596:     this.tutorialClock += dt;
597:     if (this.tutorialStage === 0 && (this.tutorialClock > 7 || alt > 2)) this.tutorialStage = 1;
598:     if (this.tutorialStage === 1 && alt > 16) this.tutorialStage = 2;
599:     if (this.tutorialStage === 2 && this.stats.hooks > 0) this.tutorialStage = 3;
600:     if (this.tutorialStage === 0) {
601:       this.setHint('mouse', 'Move the mouse — the pole follows. Plant the tip. Pull.', 0);
602:     } else if (this.tutorialStage === 1) {
603:       this.setHint('lmb', 'Hold left mouse to grip. Lever the pole against a ledge.', 0);
604:     } else if (this.tutorialStage === 2) {
605:       this.setHint('rmb', 'Right mouse throws your hook. Hold to reel in.', 0);
606:     } else if (this.hook.state === 'attached') {
607:       this.setHint('reel', 'HOLD RIGHT MOUSE to haul in. Release to let go.', 0);
608:     } else {
609:       this.setHint('r', 'R returns you to the last checkpoint flag.', 0);
610:     }
611: 
612:     // hook aim / cooldown
613:     const h = this.hook;
614:     if (h.cooldown > 0) h.cooldown = Math.max(0, h.cooldown - dt);
615:     if (h.state === 'flying') {
616:       h.t += dt;
617:       const t = clamp(h.t / h.dur, 0, 1);
618:       const e = 1 - Math.pow(1 - t, 3);
619:       h.pos.x = lerp(h.from.x, h.to.x, e);
620:       h.pos.y = lerp(h.from.y, h.to.y, e);
621:       if (h.miss && Math.random() < .55) this.addParticle({
622:         x: h.pos.x, y: h.pos.y, vx: (Math.random() - .5) * 80, vy: (Math.random() - .5) * 80,
623:         life: .4, max: .4, size: 1.6, color: 'rgba(230,210,170,.5)', type: 'spark', grav: 0,
624:       });
625:       if (t >= 1) {
626:         if (h.miss) {
627:           h.state = 'retracting'; h.t = 0; h.dur = .16;
628:           this.audio.hookMiss();
629:         } else {
630:           h.state = 'attached';
631:           h.anchor = { x: h.to.x, y: h.to.y };
632:           h.ropeLen = Math.max(40, Math.hypot(p.x - h.anchor.x, p.y - h.anchor.y));
633:           h.attachedFor = 0;
634:           this.stats.hooks++;
635:           this.audio.hookLatch();
636:           this.spawnImpact(h.anchor, 'stone', 1.2);
637:           this.addCameraShake(2);
638:         }
639:       }
640:     } else if (h.state === 'attached') {
641:       h.attachedFor += dt;
642:       h.pos.x = h.anchor.x; h.pos.y = h.anchor.y;
643:       if (this.grip || this.reeling) {
644:         // reel is driven by right-mouse held; this.reeling is set on fire
645:       }
646:       if (this.reeling) {
647:         h.ropeLen = Math.max(38, h.ropeLen - 170 * dt);
648:         if (Math.random() < .4) this.audio.reel();
649:         if (Math.random() < .5) this.addParticle({
650:           x: h.anchor.x, y: h.anchor.y, vx: (Math.random() - .5) * 50, vy: Math.random() * 40,
651:           life: .5, max: .5, size: 1.3, color: 'rgba(220,205,170,.45)', type: 'spark', grav: 120,
652:         });
653:       }
654:       if (h.attachedFor > 9 || Math.hypot(p.x - h.anchor.x, p.y - h.anchor.y) > 760) {
655:         this.releaseHook();
656:         this.toast('THE ROPE SLIPS');
657:       }
658:     } else if (h.state === 'retracting') {
659:       h.t += dt;
660:       const t = clamp(h.t / h.dur, 0, 1);
661:       const hand = this.hand();
662:       h.pos.x = lerp(h.pos.x, hand.x, t * .35);
663:       h.pos.y = lerp(h.pos.y, hand.y, t * .35);
664:       if (t >= 1) { h.state = 'ready'; h.cooldown = .35; h.anchor = null; }
665:     } else {
666:       const hand = this.hand();
667:       h.pos.x = hand.x; h.pos.y = hand.y;
668:     }
669: 
670:     // victory
671:     if (Math.hypot(p.x - SUMMIT.x, p.y - SUMMIT.y) < 150) this.startEnding();
672: 
673:     // splash flash decay
674:     this.splashFlash = Math.max(0, this.splashFlash - dt * 1.6);
675:     this.updateHUD();
676:   }
