867:   updateParticles(dt) {
868:     const ps = this.particles;
869:     for (let i = ps.length - 1; i >= 0; i--) {
870:       const q = ps[i];
871:       q.life -= dt;
872:       if (q.life <= 0) { ps.splice(i, 1); continue; }
873:       q.vy += (q.grav || 0) * dt;
874:       q.vx *= (1 - (q.drag || 0) * dt);
875:       q.vy *= (1 - (q.drag || 0) * dt);
876:       q.x += q.vx * dt;
877:       q.y += q.vy * dt;
878:       if (q.rot !== undefined) q.rot += (q.spin || 0) * dt;
879:     }
880:     if (ps.length > 620) ps.splice(0, ps.length - 620);
881:   }
