131:   draw(t, dt) {
132:     const { ctx, w, h, game } = this;
133:     this.cam = game.camera;
134:     if (!this.ready) this.preload();
135:     this.screenTransform();
136:     ctx.clearRect(0, 0, w, h);
137: 
138:     const prog = game.progress ? game.progress() : 0;
139:     this.drawSky(prog, t);
140:     this.drawStars(prog, t);
141:     this.drawSun(prog, t);
142:     this.drawClouds(t, prog);
143:     this.drawHorizon(prog, t);
144: 
145:     this.parallax(1);
146:     drawSeaStack(ctx, game, t);
147:     drawUndercliffs(ctx, game, this.cam, t);
148:     this.drawBackProps(t);
149:     drawPlatforms(ctx, game, this.cam, t);
150:     this.drawWater(t);
151:     this.drawFrontProps(t);
152:     this.drawCheckpoints(t);
153:     this.drawChest(t);
154:     this.drawRopeAndPole(t);
155:     this.drawPirateLayer(t);
156:     this.drawParticles(t);
157:     this.drawMotes(t);
158: 
159:     this.screenTransform();
160:     this.drawScreenEffects(t);
161:     this.drawCursor(t);
162:     this.drawDebug();
163:   }
164: 
165:   /* ── sky ───────────────────────────────────────────────── */
166:   drawSky(prog, t) {
167:     const { ctx, w, h } = this;
168:     const low = prog < .52 ? SKY.low : SKY.mid;
169:     const high = prog < .52 ? SKY.mid : SKY.high;
170:     const tt = prog < .52 ? prog / .52 : (prog - .52) / .48;
171:     const top = mix(low.top, high.top, tt);
172:     const mid = mix(low.mid, high.mid, tt);
173:     const lowc = mix(low.low, high.low, tt);
174:     const hor = mix(low.hor, high.hor, tt);
175:     const under = mix(low.under, high.under, tt);
176:     const g = ctx.createLinearGradient(0, 0, 0, h);
177:     g.addColorStop(0, top);
178:     g.addColorStop(.26, top);
179:     g.addColorStop(.5, mid);
180:     g.addColorStop(.72, lowc);
181:     g.addColorStop(.88, hor);
182:     g.addColorStop(1, under);
183:     ctx.fillStyle = g;
184:     ctx.fillRect(0, 0, w, h);
185: 
186:     // the low sun is the whole scene's key light
187:     const sx = w * .23, sy = h * (.47 - prog * .52);
188:     const glow = ctx.createRadialGradient(sx, sy, 6, sx, sy, Math.max(w, h) * .78);
189:     glow.addColorStop(0, `rgba(255,235,194,${.6 * (1 - prog * .55)})`);
190:     glow.addColorStop(.08, `rgba(255,205,142,${.4 * (1 - prog * .55)})`);
191:     glow.addColorStop(.3, `rgba(238,158,98,${.15 * (1 - prog * .55)})`);
192:     glow.addColorStop(.62, `rgba(180,120,92,${.05 * (1 - prog * .55)})`);
193:     glow.addColorStop(1, 'rgba(0,0,0,0)');
194:     ctx.save();
195:     ctx.globalCompositeOperation = 'lighter';
196:     ctx.fillStyle = glow;
197:     ctx.fillRect(0, 0, w, h);
198:     ctx.restore();
199: 
200:     // warm band sitting on the horizon
201:     const hz = ctx.createLinearGradient(0, h * .58, 0, h);
202:     hz.addColorStop(0, 'rgba(255,196,116,0)');
203:     hz.addColorStop(.55, `rgba(255,196,116,${.1 * (1 - prog * .85)})`);
204:     hz.addColorStop(1, 'rgba(120,72,50,0)');
205:     ctx.fillStyle = hz;
206:     ctx.fillRect(0, 0, w, h);
207:   }
208: 
209:   drawStars(prog, t) {
210:     const { ctx, w, h } = this;
211:     const a = clamp((prog - .28) / .45, 0, 1);
212:     if (a <= .01) return;
213:     ctx.save();
214:     for (const s of this.stars) {
215:       const tw = .55 + .45 * Math.sin(t * 1.7 + s.tw);
216:       ctx.fillStyle = `rgba(225,236,236,${a * s.a * tw})`;
217:       ctx.beginPath();
218:       ctx.arc(s.x * w, s.y * h, s.r * (s.big ? 1.5 : 1), 0, TAU);
219:       ctx.fill();
220:       if (s.big) {
221:         ctx.strokeStyle = `rgba(220,235,240,${a * .22 * tw})`;
222:         ctx.lineWidth = .7;
223:         ctx.beginPath();
224:         ctx.moveTo(s.x * w - 5, s.y * h);
225:         ctx.lineTo(s.x * w + 5, s.y * h);
226:         ctx.moveTo(s.x * w, s.y * h - 5);
227:         ctx.lineTo(s.x * w, s.y * h + 5);
228:         ctx.stroke();
229:       }
230:     }
231:     ctx.restore();
232:   }
233: 
234:   drawSun(prog, t) {
235:     const { ctx, w, h } = this;
236:     const sunX = w * .23;
237:     const sunY = h * (.47 - prog * .52);
238:     const vis = clamp(1 - prog * .55, 0, 1);
239:     if (sunY > -240) {
240:       const warm = prog < .6;
241:       ctx.save();
242:       ctx.globalCompositeOperation = 'lighter';
243: 
244:       // broad bloom
245:       const R = Math.min(w, h) * .62;
246:       const g = ctx.createRadialGradient(sunX, sunY, 10, sunX, sunY, R);
247:       g.addColorStop(0, warm ? `rgba(255,236,196,${.62 * vis})` : `rgba(210,230,240,${.2 * vis})`);
248:       g.addColorStop(.1, warm ? `rgba(255,205,138,${.28 * vis})` : `rgba(190,220,235,${.1 * vis})`);
249:       g.addColorStop(.38, warm ? `rgba(240,148,88,${.07 * vis})` : `rgba(150,190,220,${.025 * vis})`);
250:       g.addColorStop(1, 'rgba(0,0,0,0)');
251:       ctx.fillStyle = g;
252:       ctx.fillRect(0, 0, w, h);
253: 
254:       // crepuscular rays
255:       const rays = 9;
256:       for (let i = 0; i < rays; i++) {
257:         const a = -0.55 + i * .14 + Math.sin(t * .05 + i * 1.7) * .015;
258:         const len = h * (.42 + (i % 3) * .16);
259:         const rg = ctx.createLinearGradient(sunX, sunY, sunX + Math.cos(a) * len, sunY + Math.sin(a) * len);
260:         rg.addColorStop(0, `rgba(255,214,152,${.05 * vis})`);
261:         rg.addColorStop(.6, `rgba(255,196,130,${.018 * vis})`);
262:         rg.addColorStop(1, 'rgba(255,190,120,0)');
263:         ctx.fillStyle = rg;
264:         ctx.beginPath();
265:         ctx.moveTo(sunX, sunY);
266:         ctx.lineTo(sunX + Math.cos(a - .035) * len, sunY + Math.sin(a - .035) * len);
267:         ctx.lineTo(sunX + Math.cos(a + .035) * len, sunY + Math.sin(a + .035) * len);
268:         ctx.closePath();
269:         ctx.fill();
270:       }
271: 
272:       // disc
273:       const disc = ctx.createRadialGradient(sunX, sunY, 2, sunX, sunY, 64);
274:       disc.addColorStop(0, `rgba(255,250,226,${.98 * vis})`);
275:       disc.addColorStop(.32, `rgba(255,221,150,${.86 * vis})`);
276:       disc.addColorStop(.62, `rgba(255,186,104,${.42 * vis})`);
277:       disc.addColorStop(1, 'rgba(255,170,90,0)');
278:       ctx.fillStyle = disc;
279:       ctx.beginPath();
280:       ctx.arc(sunX, sunY, 66, 0, TAU);
281:       ctx.fill();
282:       ctx.restore();
283:     }
284: 
285:     // moon at altitude
286:     if (prog > .55) {
287:       const ma = clamp((prog - .55) / .3, 0, 1);
288:       const mx = w * .17, my = h * .17;
289:       ctx.save();
290:       ctx.globalCompositeOperation = 'lighter';
291:       const rg = ctx.createRadialGradient(mx, my, 2, mx, my, 120);
292:       rg.addColorStop(0, `rgba(220,235,235,${.16 * ma})`);
293:       rg.addColorStop(1, 'rgba(0,0,0,0)');
294:       ctx.fillStyle = rg;
295:       ctx.fillRect(mx - 120, my - 120, 240, 240);
296:       ctx.restore();
297:       ctx.fillStyle = `rgba(224,232,224,${.8 * ma})`;
298:       ctx.beginPath();
299:       ctx.arc(mx, my, 22, 0, TAU);
300:       ctx.fill();
301:       ctx.fillStyle = `rgba(170,185,183,${.4 * ma})`;
302:       ctx.beginPath(); ctx.arc(mx - 7, my - 4, 5, 0, TAU); ctx.fill();
303:       ctx.beginPath(); ctx.arc(mx + 6, my + 7, 3.4, 0, TAU); ctx.fill();
304:       ctx.beginPath(); ctx.arc(mx + 4, my - 9, 2.4, 0, TAU); ctx.fill();
305:     }
306:   }
307: 
308:   drawClouds(t, prog) {
309:     const { ctx, w, h } = this;
310:     const z = this.cam.zoom;
311:     const sunX = w * .23;
312:     const sunY = h * (.47 - prog * .52);
313:     ctx.save();
314:     for (const c of this.clouds) {
315:       const f = .18;
316:       const sx = (c.x - this.cam.x * f) * z * .7 + w * .5 + Math.sin(t * .02 + c.y) * 14;
317:       const sy = (c.y - this.cam.y * f) * z * .7 + h * .5;
318:       if (sy < -220 * c.s || sy > h + 220 * c.s) continue;
319:       if (sx < -420 * c.s || sx > w + 420 * c.s) continue;
320:       const alpha = c.a * (1 - prog * .2) * 1.25;
321:       ctx.globalAlpha = alpha;
322:       const sprite = c.warm > prog * 1.2 ? this.cloudSprite : this.cloudSpriteCool;
323:       const cw = 512 * c.s * .7, ch = 220 * c.s * .7;
324:       ctx.drawImage(sprite, sx - cw / 2, sy - ch / 2, cw, ch);
325:     }
326:     ctx.restore();
327: 
328:     // lit cloud banks around the low sun
329:     ctx.save();
330:     ctx.globalCompositeOperation = 'lighter';
331:     const banks = [
332:       [0, -.09, 420, 30, .13],
333:       [.14, .04, 520, 24, .1],
334:       [-.13, .12, 360, 20, .08],
335:       [.05, -.2, 620, 34, .07],
336:     ];
337:     for (const [dx, dy, bw, bh, a] of banks) {
338:       const bx = sunX + w * dx, by = sunY + h * dy;
339:       const bg = ctx.createRadialGradient(bx, by, 0, bx, by, bw);
340:       bg.addColorStop(0, `rgba(255,214,158,${a * (1 - prog * .4)})`);
341:       bg.addColorStop(.55, `rgba(240,178,128,${a * .4 * (1 - prog * .4)})`);
342:       bg.addColorStop(1, 'rgba(240,178,128,0)');
343:       ctx.fillStyle = bg;
344:       ctx.beginPath();
345:       ctx.ellipse(bx, by, bw, bh, 0, 0, TAU);
346:       ctx.fill();
347:     }
348:     ctx.restore();
349: 
350:     // a few birds riding the warm air
351:     ctx.save();
352:     ctx.strokeStyle = `rgba(34,52,52,${.5 * (1 - prog * .5)})`;
353:     ctx.lineWidth = 1.4;
354:     for (let i = 0; i < 5; i++) {
355:       const bx = w * (.3 + i * .1) + Math.sin(t * .18 + i) * 20;
356:       const by = h * (.23 + (i % 3) * .05) + Math.sin(t * .7 + i * 2) * 5;
357:       const fl = Math.sin(t * 3.2 + i) * 4;
358:       const s = 3 + (i % 2) * 2;
359:       ctx.beginPath();
360:       ctx.moveTo(bx - s, by + fl * .3);
361:       ctx.quadraticCurveTo(bx - s * .4, by - s * .5 - fl, bx, by);
362:       ctx.quadraticCurveTo(bx + s * .4, by - s * .5 - fl, bx + s, by + fl * .3);
363:       ctx.stroke();
364:     }
365:     ctx.restore();
366:   }
367: 
368:   drawHorizon(prog, t) {
369:     const { ctx, w, h } = this;
370:     const z = this.cam.zoom;
371:     const horizon = (SEA_Y - this.cam.y * .12) * z + h / 2;
372:     if (horizon < h * .18 || horizon > h * 1.3) return;
373:     ctx.save();
374:     // distant haze
375:     const hz = ctx.createLinearGradient(0, horizon - 90, 0, horizon + 30);
376:     hz.addColorStop(0, 'rgba(180,190,170,0)');
377:     hz.addColorStop(.7, `rgba(210,190,155,${.13 * (1 - prog)})`);
378:     hz.addColorStop(1, 'rgba(230,196,150,0)');
379:     ctx.fillStyle = hz;
380:     ctx.fillRect(0, horizon - 90, w, 120);
381:     // far islands
382:     const drift = -this.cam.x * .02;
383:     for (let i = 0; i < 3; i++) {
384:       const ix = w * (.18 + i * .33) + drift;
385:       const s = [1.4, .9, 1.1][i];
386:       const iy = horizon + 4;
387:       ctx.fillStyle = i === 1 ? 'rgba(43,62,58,.55)' : 'rgba(37,56,55,.68)';
388:       ctx.beginPath();
389:       ctx.moveTo(ix - 170 * s, iy);
390:       ctx.bezierCurveTo(ix - 120 * s, iy - 55 * s, ix - 60 * s, iy - 34 * s, ix - 20 * s, iy - 74 * s);
391:       ctx.bezierCurveTo(ix + 10 * s, iy - 100 * s, ix + 34 * s, iy - 38 * s, ix + 74 * s, iy - 53 * s);
392:       ctx.bezierCurveTo(ix + 120 * s, iy - 32 * s, ix + 150 * s, iy - 20 * s, ix + 190 * s, iy);
393:       ctx.closePath();
394:       ctx.fill();
395:     }
396:     ctx.restore();
397:   }
