399:   /* ── world layers ──────────────────────────────────────── */
400:   drawBackProps(t) {
401:     const { ctx, game } = this;
402:     const back = new Set(['hull', 'mast', 'sail', 'arch', 'skullgate', 'waterfall']);
403:     for (const p of game.level.props) {
404:       if (!back.has(p.type)) continue;
405:       drawProp(ctx, p, t, game);
406:     }
407:   }
