244:     body.plugin = { platform: p.id || `p${i}`, type: p.type };
245:     const item = {
246:       ...p,
247:       id: p.id || `p${i}`,
248:       ...g,
249:       body,
250:       index: i,
251:       friction: FRICTION[p.type] ?? .8,
252:     };
253:     bodies.push(body);
254:     platforms.push(item);
255:   });
