666: export function drawFlyingHook(ctx, game, time) {
667:   const h = game.hook;
668:   if (!h || h.state === 'ready') return;
669:   if (h.state === 'attached') {
670:     const ang = Math.atan2(h.anchor.y - game.player.position.y, h.anchor.x - game.player.position.x);
671:     drawHookShape(ctx, h.pos.x, h.pos.y, ang - .4, 1, time);
672:     // sparks at contact
673:     if (Math.random() < .1) {
674:       ctx.fillStyle = 'rgba(255,230,170,.7)';
675:       ctx.beginPath();
676:       ctx.arc(h.pos.x + (Math.random() - .5) * 8, h.pos.y + (Math.random() - .5) * 8, 1, 0, TAU);
677:       ctx.fill();
678:     }
679:   } else if (h.state === 'flying') {
680:     const ang = Math.atan2(h.to.y - h.from.y, h.to.x - h.from.x);
681:     drawHookShape(ctx, h.pos.x, h.pos.y, ang + Math.sin(time * 20) * .3, .9, time);
682:     ctx.save();
683:     ctx.globalCompositeOperation = 'lighter';
684:     ctx.fillStyle = 'rgba(255,220,150,.14)';
685:     ctx.beginPath();
686:     ctx.arc(h.pos.x, h.pos.y, 10, 0, TAU);
687:     ctx.fill();
688:     ctx.restore();
689:   } else {
690:     drawHookShape(ctx, h.pos.x, h.pos.y, .5, .8, time);
691:   }
692: }

