282: /** Ray vs. terrain segments. Returns nearest hit or null. */
283: export function castRay(segments, x0, y0, x1, y1, maxDist = Infinity) {
284:   const rx = x1 - x0, ry = y1 - y0;
285:   const rlen = Math.hypot(rx, ry);
286:   if (rlen < 0.0001) return null;
287:   const dx = rx / rlen, dy = ry / rlen;
288:   let best = null;
289:   let bestT = maxDist;
290:   for (const s of segments) {
291:     const sx = s.bx - s.ax, sy = s.by - s.ay;
292:     const denom = dx * sy - dy * sx;
293:     if (Math.abs(denom) < 1e-9) continue;
294:     const qx = s.ax - x0, qy = s.ay - y0;
295:     const t = (qx * sy - qy * sx) / denom;
296:     const u = (qx * dy - qy * dx) / denom;
297:     if (t >= 0 && t < bestT && u >= 0 && u <= 1) {
298:       bestT = t;
299:       best = { x: x0 + dx * t, y: y0 + dy * t, dist: t, platform: s.platform, seg: s };
300:     }
301:   }
302:   return best;
303: }
304: 
305: export function isNearSurface(segments, x, y, radius) {
306:   let closest = null;
307:   let best = radius;
308:   for (const s of segments) {
309:     const vx = s.bx - s.ax, vy = s.by - s.ay;
310:     const wx = x - s.ax, wy = y - s.ay;
311:     const l2 = vx * vx + vy * vy;
312:     let t = l2 ? (wx * vx + wy * vy) / l2 : 0;
313:     t = Math.max(0, Math.min(1, t));
314:     const px = s.ax + vx * t, py = s.ay + vy * t;
315:     const d = Math.hypot(x - px, y - py);
316:     if (d < best) { best = d; closest = { x: px, y: py, dist: d, platform: s.platform }; }
317:   }
318:   return closest;
319: }

