480:     const a = Math.atan2(y2 - y1, x2 - x1);
481:     ctx.beginPath();
482:     ctx.moveTo(mx - Math.cos(a) * 2, my - Math.sin(a) * 2);
483:     ctx.lineTo(mx + Math.cos(a) * 2, my + Math.sin(a) * 2);
484:     ctx.stroke();
485:   }
486: }
