488: function drawHookShape(ctx, x, y, angle, scale, time) {
489:   ctx.save();
490:   ctx.translate(x, y);
491:   ctx.rotate(angle);
492:   ctx.scale(scale, scale);
493:   const g = ctx.createLinearGradient(-3, -6, 8, 8);
494:   g.addColorStop(0, '#9aa7a4');
495:   g.addColorStop(.35, '#d6dfda');
496:   g.addColorStop(.6, '#6f7a77');
497:   g.addColorStop(1, '#3d4645');
498:   ctx.strokeStyle = g;
499:   ctx.lineWidth = 3.4;
500:   ctx.lineCap = 'round';
501:   // shank
502:   ctx.beginPath();
503:   ctx.moveTo(-2, -10);
504:   ctx.lineTo(0, 5);
505:   ctx.stroke();
506:   // bill
507:   ctx.beginPath();
508:   ctx.moveTo(0, 5);
509:   ctx.bezierCurveTo(12, 6, 16, 16, 7, 20);
510:   ctx.bezierCurveTo(-2, 23, -10, 16, -8, 9);
511:   ctx.stroke();
512:   // barb
513:   ctx.beginPath();
514:   ctx.moveTo(-8, 10);
515:   ctx.lineTo(-13, 6);
516:   ctx.stroke();
517:   // eyelet
518:   ctx.strokeStyle = '#c7d2cd';
519:   ctx.lineWidth = 1.6;
520:   ctx.beginPath();
521:   ctx.arc(-2, -11, 2.6, 0, TAU);
522:   ctx.stroke();
523:   // glint
524:   const gl = .4 + Math.sin(time * 3) * .3;
525:   ctx.fillStyle = `rgba(255,255,255,${gl})`;
526:   ctx.beginPath();
527:   ctx.arc(3, 8, 1.1, 0, TAU);
528:   ctx.fill();
529:   ctx.restore();
530: }
