688:   updateEnding(dt) {
689:     this.endTimer += dt;
690:     this.chestOpen = clamp(this.chestOpen + dt * .7, 0, 1);
691:     const target = { x: SUMMIT.x, y: SUMMIT.y - 40 };
692:     this.camera.x = damp(this.camera.x, target.x, 1.8, dt);
693:     this.camera.y = damp(this.camera.y, target.y, 1.8, dt);
694:     this.camera.zoom = damp(this.camera.zoom, this.camera.baseZoom * 1.18, 1.3, dt);
695:     if (this.endTimer > .3 && this.endTimer < 2.6 && Math.random() < .7) {
696:       this.spawnGoldBurst({ x: SUMMIT.x + (Math.random() - .5) * 160, y: SUMMIT.y - 20 }, 1, false);
697:     }
698:   }
