305: export function isNearSurface(segments, x, y, radius) {
306:   let closest = null;
307:   let best = radius;
308:   for (const s of segments) {
309:     const vx = s.bx - s.ax, vy = s.by - s.ay;
310:     const wx = x - s.ax, wy = y - s.ay;
311:     const l2 = vx * vx + vy * vy;
312:     let t = l2 ? (wx * vx + wy * vy) / l2 : 0;
313:     t = Math.max(0, Math.min(1, t));
314:     const px = s.ax + vx * t, py = s.ay + vy * t;
315:     const d = Math.hypot(x - px, y - py);
316:     if (d < best) { best = d; closest = { x: px, y: py, dist: d, platform: s.platform }; }
317:   }
318:   return closest;
319: }

