81:     if (params.has('cp')) {
82:       const idx = parseInt(params.get('cp'), 10);
83:       if (!Number.isNaN(idx)) this.startIndex = clamp(idx, 0, CHECKPOINTS.length - 1);
84:     }
85:     if (params.has('summit')) this.startIndex = CHECKPOINTS.length - 1;
