35:     if (this.game.camera) {
36:       const c = this.game.camera;
37:       c.baseZoom = clamp(Math.max(this.w / 1300, this.h / 820), .72, 1.25);
38:       if (!this.ready) c.zoom = c.baseZoom;
39:     }
40:   }
41: 
42:   preload() {
43:     if (this.ready) return;
44:     preparePlatforms(this.game.level);
45: 
46:     // stars
47:     const rand = mulberry32(77123);
48:     this.stars = [];
49:     for (let i = 0; i < 170; i++) {
50:       this.stars.push({
51:         x: rand(), y: rand() * .72, r: .4 + rand() * 1.7,
52:         a: .25 + rand() * .75, tw: rand() * TAU, big: rand() > .93,
53:       });
54:     }
55: 
56:     // clouds
57:     this.clouds = [];
58:     for (let i = 0; i < 26; i++) {
59:       this.clouds.push({
60:         x: -2200 + rand() * 4400,
61:         y: 560 - rand() * 11200,
62:         s: .5 + rand() * 1.3,
63:         a: .08 + rand() * .16,
64:         v: .8 + rand() * 2.4,
65:         warm: rand(),
66:       });
67:     }
68:     this.cloudSprite = this.makeCloudSprite('#ffe4c0');
69:     this.cloudSpriteCool = this.makeCloudSprite('#cadfe4');
70: 
71:     // ambient motes
72:     this.motes = [];
73:     for (let i = 0; i < 150; i++) {
74:       const y = 300 - rand() * 10800;
75:       this.motes.push({
76:         x: -1200 + rand() * 2400,
77:         y,
78:         s: .6 + rand() * 1.8,
79:         ph: rand() * TAU,
80:         sp: .4 + rand() * 1.2,
81:       });
82:     }
83: 
84:     // checkpoint flag footings
85:     for (const cp of this.game.level.checkpoints) {
86:       const hit = castRay(this.game.level.segments, cp.x, cp.y, cp.x, cp.y + 220);
87:       cp.footY = hit ? hit.y : cp.y + 40;
88:     }
89: 
90:     // cached fog gradients
91:     this.ready = true;
92:   }
93: 
94:   makeCloudSprite(color) {
95:     const c = document.createElement('canvas');
96:     c.width = 512;
97:     c.height = 220;
98:     const g = c.getContext('2d');
99:     const rand = mulberry32(4312);
100:     for (let i = 0; i < 13; i++) {
101:       const x = 70 + rand() * 380;
102:       const y = 75 + rand() * 80;
103:       const r = 34 + rand() * 60;
104:       const gr = g.createRadialGradient(x, y, 0, x, y, r);
105:       gr.addColorStop(0, withA(color, .5));
106:       gr.addColorStop(.55, withA(color, .18));
107:       gr.addColorStop(1, withA(color, 0));
108:       g.fillStyle = gr;
109:       g.beginPath();
110:       g.arc(x, y, r, 0, TAU);
111:       g.fill();
112:     }
113:     return c;
114:   }
