40: export function preparePlatforms(level) {
41:   for (const p of level.platforms) {
42:     const rand = mulberry32(hashStr(p.id + p.type));
43:     const L = p.len, T = p.t;
44:     const tex = {
45:       specks: [], cracks: [], tufts: [], seams: [], nails: [], joints: [],
46:       veins: [], facets: [], blocks: [], boulders: [], lichen: [], vines: [],
47:     };
48:     const n = Math.min(54, Math.max(16, Math.floor(L / 10)));
49:     for (let i = 0; i < n; i++) {
50:       tex.specks.push({ x: (rand() - .5) * L, y: (rand() - .5) * T, r: .6 + rand() * 2.1, a: .08 + rand() * .28 });
51:     }
