55:       const y = (rand() - .5) * T * .5;
56:       const seg = [{ x, y }];
57:       let cx = x, cy = y;
58:       for (let j = 0; j < 4; j++) {
59:         cx += (rand() - .5) * T * .9;
60:         cy += (rand() - .25) * T * .5;
61:         seg.push({ x: cx, y: cy });
62:       }
63:       tex.cracks.push(seg);
64:     }
65:     const tufts = Math.max(4, Math.floor(L / 26));
66:     for (let i = 0; i < tufts; i++) {
67:       tex.tufts.push({ x: (rand() - .5) * L * .96, h: 5 + rand() * 13, lean: (rand() - .5) * 7, a: rand() });
68:     }
69:     const seams = Math.max(2, Math.floor(L / 58));
70:     for (let i = 0; i < seams; i++) tex.seams.push((rand() - .5) * L * .9);
71:     for (let i = 0; i < Math.max(4, Math.floor(L / 46)); i++) {
72:       tex.nails.push({ x: (rand() - .5) * L * .92, y: (rand() - .5) * T * .4, o: rand() });
73:     }
74:     const joints = Math.max(2, Math.floor(L / 70));
75:     for (let i = 0; i < joints; i++) tex.joints.push((rand() - .5) * L);
76:     for (let i = 0; i < Math.max(3, Math.floor(L / 55)); i++) {
77:       tex.veins.push({ x0: (rand() - .5) * L, x1: (rand() - .5) * L, y: (rand() - .5) * T * .6, w: .5 + rand() * 1.5 });
78:     }
79:     // rock facets: chunky planes that break up the box silhouette
80:     const facets = Math.max(3, Math.floor(L / 70));
81:     for (let i = 0; i < facets; i++) {
82:       const x = (rand() - .5) * L * .92;
