87:     }
88:     // sediment bands and embedded boulders
89:     tex.strata = [];
90:     const bands = Math.max(2, Math.floor(T / 26));
91:     for (let i = 0; i < bands; i++) {
92:       tex.strata.push({ y: -T / 2 + (i + .5) * (T / bands) + (rand() - .5) * 6, h: 3 + rand() * 9, a: .05 + rand() * .09 });
93:     }
94:     tex.embedded = [];
95:     for (let i = 0; i < Math.max(2, Math.floor(L / 100)); i++) {
96:       tex.embedded.push({ x: (rand() - .5) * L * .8, y: -T * .05 + rand() * T * .35, r: 6 + rand() * Math.min(22, T * .3), a: rand() });
97:     }
98:     // masonry courses for temple stone
99:     const rows = Math.max(2, Math.floor(T / 26));
100:     for (let r = 0; r < rows; r++) {
