498: function drawLedge(ctx, p, st, time) {
499:   const L = p.len, T = p.t;
500:   const tex = p.tex;
501:   const shape = p.shape;
502: 
503:   // cast shadow on the cliff behind, thrown down and inland
504:   ctx.save();
505:   ctx.translate(16, 20);
506:   poly(ctx, shape);
507:   ctx.fillStyle = 'rgba(3,9,11,.18)';
508:   ctx.fill();
509:   ctx.restore();
510: 
511:   // soft contact shadow under the ledge
512:   ctx.save();
513:   ctx.fillStyle = 'rgba(4,9,10,.18)';
514:   ctx.beginPath();
515:   ctx.ellipse(0, T * .58, L * .46, T * .22, 0, 0, TAU);
516:   ctx.fill();
517:   ctx.restore();
518: 
519:   poly(ctx, shape);
520:   const g = ctx.createLinearGradient(0, -T / 2, 0, T * .82);
521:   g.addColorStop(0, st.top);
522:   g.addColorStop(.16, st.base);
523:   g.addColorStop(.62, st.base);
524:   g.addColorStop(1, st.dark);
525:   ctx.fillStyle = g;
526:   ctx.fill();
527: 
528:   ctx.save();
529:   poly(ctx, shape);
530:   ctx.clip();
531: 
532:   // ambient shade under the walkable lip
533:   const ao = ctx.createLinearGradient(0, -T / 2, 0, -T / 2 + Math.min(T * .5, 46));
534:   ao.addColorStop(0, 'rgba(12,15,15,.28)');
535:   ao.addColorStop(1, 'rgba(12,15,15,0)');
536:   ctx.fillStyle = ao;
537:   ctx.fillRect(-L / 2, -T / 2, L, Math.min(T * .5, 46));
538: 
539:   // broad rock planes, kept subtle so they describe form rather than crumple
540:   for (const f of tex.facets) {
541:     ctx.fillStyle = f.warm ? `rgba(255,224,170,${f.a})` : `rgba(0,0,0,${f.a})`;
542:     ctx.beginPath();
543:     ctx.moveTo(f.x, f.y);
544:     ctx.lineTo(f.x + f.w, f.y + f.h * .14);
545:     ctx.lineTo(f.x + f.w * .66, f.y + f.h);
546:     ctx.lineTo(f.x - f.w * .12, f.y + f.h * .68);
547:     ctx.closePath();
548:     ctx.fill();
549:   }
550:   // sedimentary bands
551:   for (const s of tex.strata) {
552:     ctx.fillStyle = `rgba(12,14,12,${s.a})`;
553:     ctx.beginPath();
554:     ctx.moveTo(-L / 2, s.y);
555:     ctx.bezierCurveTo(-L * .2, s.y - 3, L * .2, s.y + 4, L / 2, s.y);
556:     ctx.lineTo(L / 2, s.y + s.h);
557:     ctx.bezierCurveTo(L * .2, s.y + 4 + s.h, -L * .2, s.y - 3 + s.h, -L / 2, s.y + s.h);
558:     ctx.closePath();
559:     ctx.fill();
560:   }
561: 
562:   if (p.type === 'sand') {
563:     // (the beach uses its own painter)
564:   } else if (p.type === 'wood' || p.type === 'deck') {
565:     ctx.strokeStyle = withA(st.texture, .65);
566:     ctx.lineWidth = 1.1;
567:     for (let i = 0; i < 10; i++) {
568:       const y = -T / 2 + (i + .5) * (T / 10.4);
569:       ctx.beginPath();
570:       ctx.moveTo(-L / 2, y);
571:       ctx.bezierCurveTo(-L / 4, y - 2.5, L / 4, y + 2.5, L / 2, y);
572:       ctx.stroke();
573:     }
574:     ctx.strokeStyle = 'rgba(30,17,7,.5)';
575:     for (const s of tex.seams) {
576:       ctx.beginPath();
577:       ctx.moveTo(s, -T / 2);
578:       ctx.lineTo(s + (p.seed - .5) * 6, T / 2);
579:       ctx.stroke();
580:     }
581:     for (const n of tex.nails) {
582:       ctx.fillStyle = 'rgba(38,30,22,.8)';
583:       ctx.beginPath(); ctx.arc(n.x, n.y, 1.5, 0, TAU); ctx.fill();
584:       ctx.fillStyle = 'rgba(210,190,150,.22)';
585:       ctx.beginPath(); ctx.arc(n.x - .4, n.y - .5, .7, 0, TAU); ctx.fill();
586:     }
587:     if (p.type === 'deck') {
588:       for (const sx of [-L * .36, L * .36]) {
589:         ctx.fillStyle = 'rgba(38,36,32,.72)';
590:         ctx.fillRect(sx - 3, -T / 2, 6, T);
591:         ctx.fillStyle = 'rgba(160,155,140,.16)';
592:         ctx.fillRect(sx - 3, -T / 2, 1.4, T);
593:       }
594:     }
595:   } else if (p.type === 'moss') {
596:     // dark stone splits
597:     ctx.strokeStyle = 'rgba(18,28,16,.4)';
598:     ctx.lineWidth = 1.2;
599:     for (const c of tex.cracks) {
600:       ctx.beginPath();
601:       ctx.moveTo(c[0].x, c[0].y);
602:       for (let i = 1; i < c.length; i++) ctx.lineTo(c[i].x, c[i].y);
603:       ctx.stroke();
604:     }
605:     // mossy top cap with a ragged lower edge
606:     const capH = Math.min(24, T * .3);
607:     ctx.fillStyle = 'rgba(92,118,60,.95)';
608:     ctx.beginPath();
609:     ctx.moveTo(-L / 2, -T / 2);
610:     ctx.lineTo(L / 2, -T / 2);
611:     let cx = L / 2;
612:     while (cx > -L / 2) {
613:       const w = 26 + Math.abs(Math.sin(cx * .07)) * 26;
614:       ctx.quadraticCurveTo(cx - w * .5, -T / 2 + capH * (1.1 + Math.sin(cx * .13) * .35), cx - w, -T / 2 + capH * .5);
615:       cx -= w;
616:     }
617:     ctx.closePath();
618:     ctx.fill();
619:     // bright moss highlight
620:     ctx.fillStyle = 'rgba(168,196,104,.18)';
621:     ctx.fillRect(-L / 2, -T / 2, L, Math.min(10, T * .16));
622:   } else if (p.type === 'stone' || p.type === 'gold') {
623:     // masonry courses, chipped and stained
624:     for (const b of tex.blocks) {
625:       ctx.fillStyle = 'rgba(22,20,17,.16)';
626:       ctx.fillRect(b.x + 1.5, b.y + 1.5, b.w - 3, b.h - 3);
627:       ctx.fillStyle = p.type === 'gold' ? 'rgba(196,164,96,.05)' : 'rgba(220,212,186,.04)';
628:       ctx.fillRect(b.x + 2, b.y + 2, b.w - 4, b.h * .34);
629:     }
630:     ctx.strokeStyle = 'rgba(26,24,20,.36)';
631:     ctx.lineWidth = 1.2;
632:     for (const c of tex.cracks) {
633:       ctx.beginPath();
634:       ctx.moveTo(c[0].x, c[0].y);
635:       for (let i = 1; i < c.length; i++) ctx.lineTo(c[i].x, c[i].y);
636:       ctx.stroke();
637:     }
638:     if (p.type === 'gold') {
639:       ctx.save();
640:       ctx.globalCompositeOperation = 'lighter';
641:       for (const v of tex.veins) {
642:         ctx.strokeStyle = 'rgba(255,208,108,.36)';
643:         ctx.lineWidth = 1.6 + v.w;
644:         ctx.beginPath();
645:         ctx.moveTo(v.x0, v.y);
646:         ctx.bezierCurveTo(v.x0 + 10, v.y - 6, v.x1 - 10, v.y + 6, v.x1, v.y);
647:         ctx.stroke();
648:       }
649:       ctx.restore();
650:     }
651:   } else {
652:     // craggy rock
653:     ctx.strokeStyle = withA(st.texture, .75);
654:     ctx.lineWidth = 1.2;
655:     for (const c of tex.cracks) {
656:       ctx.beginPath();
657:       ctx.moveTo(c[0].x, c[0].y);
658:       for (let i = 1; i < c.length; i++) ctx.lineTo(c[i].x, c[i].y);
659:       ctx.stroke();
660:     }
661:     for (const l of tex.lichen) {
662:       ctx.fillStyle = l.a > .09 ? `rgba(139,158,102,${l.a})` : `rgba(226,214,180,${l.a})`;
663:       ctx.beginPath();
664:       ctx.ellipse(l.x, l.y, l.r, l.r * .45, l.x * .02, 0, TAU);
665:       ctx.fill();
666:     }
667:   }
668: 
669:   // boulders embedded in the face
670:   if (p.type === 'rock' || p.type === 'moss' || p.type === 'stone') {
671:     for (const b of tex.embedded) {
672:       const bg = ctx.createLinearGradient(0, b.y - b.r, 0, b.y + b.r);
673:       bg.addColorStop(0, 'rgba(255,226,176,.09)');
674:       bg.addColorStop(.55, 'rgba(30,32,28,.06)');
675:       bg.addColorStop(1, 'rgba(0,0,0,.2)');
676:       ctx.fillStyle = bg;
677:       ctx.beginPath();
678:       ctx.ellipse(b.x, b.y, b.r, b.r * .58, b.a * .6 - .3, 0, TAU);
679:       ctx.fill();
680:       ctx.strokeStyle = 'rgba(0,0,0,.14)';
681:       ctx.lineWidth = 1;
682:       ctx.beginPath();
683:       ctx.ellipse(b.x, b.y, b.r, b.r * .58, b.a * .6 - .3, 0, TAU);
684:       ctx.stroke();
685:     }
686:   }
687: 
688:   // speckle grain
689:   ctx.fillStyle = withA(st.texture, .35);
690:   for (const s of tex.specks) {
691:     ctx.globalAlpha = s.a;
692:     ctx.beginPath();
693:     ctx.arc(s.x, s.y, s.r, 0, TAU);
694:     ctx.fill();
695:   }
696:   ctx.globalAlpha = 1;
697: 
698:   // deep shadow along the broken underside
699:   const sh = ctx.createLinearGradient(0, T * .3, 0, T);
700:   sh.addColorStop(0, 'rgba(0,0,0,0)');
701:   sh.addColorStop(1, 'rgba(0,0,0,.4)');
702:   ctx.fillStyle = sh;
703:   ctx.fillRect(-L / 2, T * .3, L, T * .8);
704: 
705:   // thick lit shelf along the walkable top
706:   const capH = Math.min(9, T * .18);
707:   const capG = ctx.createLinearGradient(0, -T / 2, 0, -T / 2 + capH);
708:   capG.addColorStop(0, st.top);
709:   capG.addColorStop(.65, st.base);
710:   capG.addColorStop(1, 'rgba(0,0,0,.28)');
711:   ctx.fillStyle = capG;
712:   ctx.fillRect(-L / 2, -T / 2, L, capH);
713:   ctx.strokeStyle = 'rgba(255,232,182,.4)';
714:   ctx.lineWidth = 1;
715:   ctx.beginPath();
716:   ctx.moveTo(-L / 2, -T / 2 + 1);
717:   ctx.lineTo(L / 2, -T / 2 + 1);
718:   ctx.stroke();
719: 
720:   ctx.restore();
721: 
722:   // hanging vines from mossy rock
723:   if (p.type === 'moss' || p.type === 'stone') {
724:     for (const v of tex.vines) {
725:       if (v.a < .45) continue;
726:       const len = v.len;
727:       ctx.strokeStyle = p.type === 'moss' ? 'rgba(68,92,50,.62)' : 'rgba(66,78,52,.4)';
728:       ctx.lineWidth = 1.1;
729:       ctx.beginPath();
730:       ctx.moveTo(v.x, T * .7);
731:       ctx.bezierCurveTo(v.x + v.lean, T * .7 + len * .35, v.x - v.lean, T * .7 + len * .7, v.x + v.lean * .5, T * .7 + len);
732:       ctx.stroke();
733:     }
734:   }
735: 
736:   // grass / weed silhouettes above the lip
737:   if (p.type === 'moss' || p.id === 'beach') {
738:     ctx.strokeStyle = p.type === 'moss' ? 'rgba(140,170,96,.95)' : 'rgba(126,142,78,.7)';
739:     ctx.lineWidth = 1.5;
740:     for (const t of tex.tufts) {
741:       ctx.beginPath();
742:       ctx.moveTo(t.x, -T / 2 + 1);
743:       ctx.quadraticCurveTo(t.x + t.lean * .4, -T / 2 - t.h * .6, t.x + t.lean, -T / 2 - t.h);
744:       ctx.stroke();
745:       ctx.beginPath();
746:       ctx.moveTo(t.x, -T / 2 + 1);
747:       ctx.quadraticCurveTo(t.x - t.lean * .6, -T / 2 - t.h * .5, t.x - t.lean * 1.2, -T / 2 - t.h * .7);
748:       ctx.stroke();
749:     }
750:   }
751: 
752:   // small boulders on the shoulder
753:   for (const b of tex.boulders) {
754:     ctx.fillStyle = p.type === 'moss' ? '#4c583a' : (p.type === 'gold' ? '#6e5a32' : '#4c473c');
755:     ctx.beginPath();
756:     ctx.ellipse(b.x, -T / 2 - b.r * .25, b.r, b.r * .55, 0, 0, TAU);
757:     ctx.fill();
758:     ctx.fillStyle = 'rgba(255,240,205,.12)';
759:     ctx.beginPath();
760:     ctx.ellipse(b.x - b.r * .2, -T / 2 - b.r * .45, b.r * .5, b.r * .24, 0, 0, TAU);
761:     ctx.fill();
762:   }
763: 
764:   // sunlit lip + warm rim light from the sunset side
765:   ctx.lineCap = 'round';
766:   ctx.strokeStyle = st.edge;
767:   ctx.lineWidth = p.type === 'gold' ? 3.4 : 2.2;
768:   ctx.globalAlpha = p.type === 'gold' ? .95 : .68;
769:   ctx.beginPath();
770:   ctx.moveTo(-L / 2 + 3, -T / 2 + 1);
771:   ctx.lineTo(L / 2 - 3, -T / 2 + 1);
772:   ctx.stroke();
773:   ctx.globalAlpha = 1;
774:   ctx.strokeStyle = 'rgba(255,226,166,.34)';
775:   ctx.lineWidth = .8;
776:   ctx.beginPath();
777:   ctx.moveTo(-L / 2 + 5, -T / 2 + .2);
778:   ctx.lineTo(L / 2 - 5, -T / 2 + .2);
779:   ctx.stroke();
780: 
781:   // outline keeps the silhouette crisp against the cliff
782:   ctx.strokeStyle = 'rgba(0,0,0,.3)';
783:   ctx.lineWidth = 1;
784:   poly(ctx, shape);
785:   ctx.stroke();
786: }
