870: export function drawSeaStack(ctx, game, time) {
871:   if (!game._stack) {
872:     const rand = mulberry32(91827);
873:     const pts = [];
874:     for (let y = 620; y >= -10800; y -= 58) {
875:       const k = clamp((620 - y) / 11420, 0, 1);
876:       const ease = k * k * (3 - 2 * k);
877:       const cx = 250 + 180 * Math.sin(y / 1350) + 80 * Math.sin(y / 460 + 1.2);
878:       const half = lerp(1180, 650, ease) + Math.sin(y / 230) * 58 + (rand() - .5) * 34;
879:       // occasional buttress juts out of the sunset-facing edge
880:       const jut = (rand() > .82 ? 34 + rand() * 90 : 0) + (rand() > .94 ? 40 : 0);
881:       const left = cx - half - jut + (rand() - .5) * 16;
882:       const right = cx + half + (rand() - .5) * 18;
883:       pts.push({ y, cx, half, left, right, jut, k });
884:     }
885:     game._stack = pts;
886: 
887:     // large features, generated once
888:     const r2 = mulberry32(55231);
889:     game._stackDetail = {
890:       facets: Array.from({ length: 120 }, () => {
891:         const y = 500 - r2() * 11000;
892:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
893:         const x = p ? p.left + r2() * (p.right - p.left) : -400 + r2() * 1200;
894:         return {
895:           x, y, w: 110 + r2() * 460, h: 180 + r2() * 720,
896:           a: .028 + r2() * .06, warm: r2() > .55,
897:         };
898:       }),
899:       strata: Array.from({ length: 90 }, () => ({
900:         y: 560 - r2() * 11200,
901:         w: 1.5 + r2() * 9,
902:         a: .06 + r2() * .12,
903:         bend: 20 + r2() * 70,
904:       })),
905:       buttresses: Array.from({ length: 11 }, (_, i) => ({
906:         y: 380 - i * 980 - r2() * 420,
907:         w: 90 + r2() * 260,
908:         h: 300 + r2() * 820,
909:         a: .18 + r2() * .2,
910:       })),
911:       caves: Array.from({ length: 6 }, () => ({
912:         y: 200 - r2() * 10200,
913:         w: 34 + r2() * 90,
914:         h: 20 + r2() * 54,
915:         a: .5 + r2() * .3,
916:       })),
917:       moss: Array.from({ length: 170 }, () => {
918:         const y = 300 - r2() * 10800;
919:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
920:         const x = p ? p.left + r2() * (p.right - p.left) : -300 + r2() * 1000;
921:         return { x, y, r: 10 + r2() * 70, a: .035 + r2() * .09, green: r2() > .35 };
922:       }),
923:       shelves: Array.from({ length: 38 }, () => {
924:         const y = 480 - r2() * 11200;
925:         return {
926:           y,
927:           len: 120 + r2() * 420,
928:           drop: 18 + r2() * 80,
929:           a: .12 + r2() * .14,
930:         };
931:       }),
932:       boulders: Array.from({ length: 40 }, () => {
933:         const y = 420 - r2() * 11000;
934:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
935:         const x = p ? p.left + 60 + r2() * Math.max(120, p.right - p.left - 120) : -300 + r2() * 1000;
936:         return { x, y, rx: 14 + r2() * 58, ry: 9 + r2() * 32, a: .06 + r2() * .12, rot: r2() * 3 };
937:       }),
938:       wide: Array.from({ length: 30 }, () => {
939:         const y = 450 - r2() * 11100;
940:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
941:         const left = p ? p.left : -800;
942:         const right = p ? p.right : 1200;
943:         return {
944:           y,
945:           x: left + 80 + r2() * Math.max(80, right - left - 260),
946:           len: 160 + r2() * 460,
947:           drop: 28 + r2() * 90,
948:           a: .13 + r2() * .16,
949:         };
950:       }),
951:       gullies: Array.from({ length: 14 }, () => {
952:         const y = 380 - r2() * 10700;
953:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
954:         const left = p ? p.left : -800;
955:         const right = p ? p.right : 1200;
956:         return {
957:           x: left + 100 + r2() * Math.max(100, right - left - 300),
958:           y,
959:           w: 40 + r2() * 120,
960:           h: 300 + r2() * 700,
961:           a: .08 + r2() * .12,
962:         };
963:       }),
964:       pillars: Array.from({ length: 24 }, (_, i) => {
965:         const y = 420 - i * 470 - r2() * 220;
966:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
967:         const left = p ? p.left : -800;
968:         const right = p ? p.right : 1200;
969:         return {
970:           x: left + 70 + r2() * Math.max(80, right - left - 380),
971:           y,
972:           w: 100 + r2() * 210,
973:           h: 420 + r2() * 900,
974:           a: .1 + r2() * .14,
975:         };
976:       }),
977:       cracks: Array.from({ length: 30 }, () => {
978:         const y = 420 - r2() * 10800;
979:         const p = pts[clamp(Math.round((620 - y) / 58), 0, pts.length - 1)];
980:         return {
981:           x: p ? p.left + 30 + r2() * 320 : -600 + r2() * 400,
982:           y,
983:           h: 120 + r2() * 520,
984:           lean: (r2() - .5) * 90,
985:           a: .1 + r2() * .12,
986:         };
987:       }),
988:       spurs: Array.from({ length: 36 }, (_, i) => {
989:         const y = 480 - i * 322 - r2() * 160;
990:         return { y, len: 45 + r2() * 170, drop: 18 + r2() * 54, a: .55 + r2() * .4 };
991:       }),
992:       vines: Array.from({ length: 54 }, () => {
993:         const idx = Math.floor(r2() * (pts.length - 30));
994:         const p = pts[idx];
995:         return {
996:           x: p.left + 20 + r2() * (p.right - p.left),
997:           y: p.y,
998:           len: 30 + r2() * 190,
999:           lean: (r2() - .5) * 18,
1000:         };
1001:       }),
1002:     };
1003:   }
1004: 
1005:   const pts = game._stack;
1006:   const D = game._stackDetail;
1007: 
1008:   /* far, hazy sister cliff behind and to the right */
1009:   ctx.save();
1010:   ctx.beginPath();
1011:   ctx.moveTo(pts[0].left - 260, pts[0].y + 40);
1012:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].left - 260 + Math.sin(i * .7) * 40, pts[i].y + 40);
1013:   for (let i = pts.length - 1; i >= 0; i--) ctx.lineTo(pts[i].right + 300, pts[i].y + 40);
1014:   ctx.closePath();
1015:   ctx.fillStyle = 'rgba(87,120,116,.3)';
1016:   ctx.fill();
1017:   ctx.restore();
1018: 
1019:   /* main mass */
1020:   ctx.save();
1021:   ctx.beginPath();
1022:   ctx.moveTo(pts[0].left, pts[0].y);
1023:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].left, pts[i].y);
1024:   for (let i = pts.length - 1; i >= 0; i--) ctx.lineTo(pts[i].right, pts[i].y);
1025:   ctx.closePath();
