271:   buildTrack() {
272:     const marks = $('#track-marks');
273:     const labels = $('#track-labels');
274:     marks.innerHTML = '';
275:     labels.innerHTML = '';
276:     const span = START.y - SUMMIT.y;
277:     for (const z of ZONES) {
278:       const lowY = Math.min(z.top, -10300);
279:       const highY = Math.max(z.bottom, SUMMIT.y);
280:       const lowP = clamp((START.y - lowY) / span, 0, 1) * 100;
281:       const highP = clamp((START.y - highY) / span, 0, 1) * 100;
282:       const m = document.createElement('span');
283:       m.className = 'track-mark';
284:       m.style.bottom = `${lowP}%`;
285:       marks.appendChild(m);
286:       const l = document.createElement('span');
287:       l.className = 'track-label';
288:       l.dataset.zone = z.id;
289:       l.textContent = z.name.replace('Wreck of the ', '').replace('Temple of the ', '');
290:       l.style.bottom = `${(lowP + highP) / 2}%`;
291:       if (l.style.bottom === '0%') l.style.bottom = '4%';
292:       labels.appendChild(l);
293:     }
294:   }
