296:   /* ── game flow ─────────────────────────────────────────── */
297:   async boot() {
298:     try { await document.fonts.ready; } catch {}
299:     this.renderer.preload();
300:     this.mode = 'title';
301:     this.state = 'title';
302:     $('#loading').classList.add('gone');
303:     this.running = true;
304:     requestAnimationFrame(this.loop);
305:     setTimeout(() => { if (this.mode === 'title') this.showTitleIdle = true; }, 100);
306:   }
307: 
308:   beginRun() {
309:     this.hide('#title-screen');
310:     this.hide('#how-screen');
311:     this.hide('#pause-screen');
312:     this.hide('#end-screen');
313:     this.setHUD(true);
314:     this.mode = 'playing';
315:     this.stats = { falls: 0, resets: 0, hooks: 0 };
316:     this.elapsed = 0;
317:     this.checkpointIndex = this.startIndex;
318:     this.visitedZones = new Set([this.zone?.id]);
319:     this.tutorialStage = 0;
320:     this.tutorialClock = 0;
321:     this.endTimer = 0;
322:     this.chestOpen = 0;
323:     this.resetToStart(this.startIndex, false);
324:     this.audio.init();
325:     this.audio.setZone(this.level.zoneAt(this.player.position.y).id);
326:     const z = this.level.zoneAt(this.player.position.y);
327:     this.zone = z;
328:     this.visitedZones = new Set([z.id]);
329:     this.showZone(z, false);
330:     this.setHint('mouse', 'Move the mouse — the pole follows. Plant the tip. Pull.', 0);
331:     setTimeout(() => {
332:       if (this.mode === 'playing') this.say(NARRATION.start, 8000);
333:     }, 900);
334:     this.updateHUD();
335:   }
336: 
337:   backToTitle() {
338:     this.hide('#pause-screen');
339:     this.hide('#end-screen');
340:     this.hide('#how-screen');
341:     this.show('#title-screen');
342:     this.setHUD(false);
343:     this.mode = 'title';
344:     this.resetToStart(0, false);
345:     this.camera.x = START.x;
346:     this.camera.y = START.y - 30;
347:     this.camera.userZoom = 1;
348:     this.updateSaveUI();
349:   }
350: 
351:   pause() {
352:     if (this.mode !== 'playing') return;
353:     this.mode = 'paused';
354:     this.grip = false;
355:     this.releaseHook(true);
356:     $('#pause-alt').textContent = `${this.altitude()} m`;
357:     $('#pause-cp').textContent = CHECKPOINTS[this.checkpointIndex].name;
358:     $('#pause-falls').textContent = this.stats.falls;
359:     $('#pause-time').textContent = this.formatTime(this.elapsed);
360:     $('#pause-quote').textContent = [
361:       '“Even the sea takes a breath.”',
362:       '“A moment’s rest is just a fall that hasn’t started.”',
363:       '“The gold is not going anywhere. Unfortunately, neither are you.”',
364:       '“Consider your grip. Consider your life choices.”',
365:     ][Math.floor(Math.random() * 4)];
366:     $('#sound-lbl').textContent = this.audio.muted ? 'off' : 'on';
367:     this.show('#pause-screen');
368:   }
369: 
370:   resume() {
371:     if (this.mode !== 'paused') return;
372:     this.hide('#pause-screen');
373:     this.mode = 'playing';
374:     this.last = performance.now();
375:     this.audio.init();
376:   }
377: 
378:   openHow() {
379:     this.wasMode = this.mode;
380:     this.show('#how-screen');
381:     this.mode = 'how';
382:   }
383: 
384:   closeHow() {
385:     this.hide('#how-screen');
386:     this.mode = this.wasMode === 'playing' ? 'playing' : (this.wasMode || 'title');
387:     if (this.mode === 'title') this.show('#title-screen');
388:   }
