577:   /* ── particles ─────────────────────────────────────────── */
578:   drawParticles(t) {
579:     const { ctx, game } = this;
580:     ctx.save();
581:     for (const q of game.particles) {
582:       const life = clamp(q.life / (q.max || 1), 0, 1);
583:       ctx.globalAlpha = q.type === 'gold' ? Math.min(1, life * 1.6) : Math.min(.85, life * 1.5);
584:       if (q.type === 'gold') {
585:         ctx.save();
586:         ctx.translate(q.x, q.y);
587:         ctx.rotate(q.rot || 0);
588:         ctx.fillStyle = q.color;
589:         ctx.beginPath();
590:         ctx.ellipse(0, 0, q.size * 1.6, q.size * .6, 0, 0, TAU);
591:         ctx.fill();
592:         ctx.globalCompositeOperation = 'lighter';
593:         ctx.globalAlpha *= .4;
594:         ctx.beginPath();
595:         ctx.arc(0, 0, q.size * 2.4, 0, TAU);
596:         ctx.fillStyle = 'rgba(255,205,100,.4)';
597:         ctx.fill();
598:         ctx.restore();
599:       } else if (q.type === 'spark') {
600:         ctx.fillStyle = q.color;
601:         const a = Math.atan2(q.vy, q.vx);
602:         ctx.save();
603:         ctx.translate(q.x, q.y);
604:         ctx.rotate(a);
605:         ctx.fillRect(-q.size * 2, -q.size * .35, q.size * 3.4, q.size * .7);
606:         ctx.restore();
607:       } else {
608:         ctx.fillStyle = q.color;
609:         ctx.beginPath();
610:         ctx.arc(q.x, q.y, q.size * (q.type === 'splash' ? 1.2 : 1), 0, TAU);
611:         ctx.fill();
612:       }
613:     }
614:     ctx.restore();
615:     ctx.globalAlpha = 1;
616:   }
