532: export function drawRope(ctx, game, time) {
533:   const h = game.hook;
534:   if (!h || h.state === 'ready') return;
535:   const hand = game.hand();
536:   const end = h.pos;
537:   const dist = Math.hypot(end.x - hand.x, end.y - hand.y);
538:   const slack = h.state === 'attached' ? clamp(h.ropeLen - dist, 0, 90) : 10;
539:   const nx = -(end.y - hand.y) / (dist || 1);
540:   const ny = (end.x - hand.x) / (dist || 1);
541:   const mx = (hand.x + end.x) / 2 + nx * slack * .55;
542:   const my = (hand.y + end.y) / 2 + ny * slack * .55 + slack * .25;
543:   ctx.save();
544:   ctx.strokeStyle = 'rgba(26,22,16,.75)';
545:   ctx.lineWidth = 3.4;
546:   ctx.lineCap = 'round';
547:   ctx.beginPath();
548:   ctx.moveTo(hand.x, hand.y);
549:   ctx.quadraticCurveTo(mx, my, end.x, end.y);
550:   ctx.stroke();
551:   ctx.strokeStyle = 'rgba(196,168,116,.75)';
552:   ctx.lineWidth = 1.6;
553:   ctx.beginPath();
554:   ctx.moveTo(hand.x, hand.y);
555:   ctx.quadraticCurveTo(mx, my, end.x, end.y);
556:   ctx.stroke();
557:   // twist dashes
558:   ctx.strokeStyle = 'rgba(90,70,40,.55)';
559:   ctx.lineWidth = 1;
560:   const steps = Math.max(4, Math.floor(dist / 16));
561:   for (let i = 1; i < steps; i++) {
562:     const t = i / steps;
563:     const it = 1 - t;
564:     const px = it * it * hand.x + 2 * it * t * mx + t * t * end.x;
565:     const py = it * it * hand.y + 2 * it * t * my + t * t * end.y;
566:     ctx.beginPath();
567:     ctx.moveTo(px - 2, py);
568:     ctx.lineTo(px + 2, py);
569:     ctx.stroke();
