23: const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
24: const lerp = (a, b, t) => a + (b - a) * t;
25: const damp = (a, b, l, dt) => lerp(a, b, 1 - Math.exp(-l * dt));
26: const wrapAngle = (a) => {
27:   while (a > Math.PI) a -= Math.PI * 2;
28:   while (a < -Math.PI) a += Math.PI * 2;
29:   return a;
30: };
