208:       this.mouse.y = e.clientY;
209:     });
210:     this.canvas.addEventListener('pointerdown', (e) => {
211:       if (this.mode !== 'playing') return;
212:       this.audio.init();
213:       if (e.button === 0) this.grip = true;
214:       if (e.button === 2) this.fireHook();
215:     });
216:     window.addEventListener('pointerup', (e) => {
217:       if (e.button === 0) this.grip = false;
218:       if (e.button === 2 && this.mode === 'playing') this.releaseHook();
219:     });
220:     this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
221:     window.addEventListener('wheel', (e) => {
222:       if (this.mode !== 'playing') return;
223:       e.preventDefault();
224:       const c = this.camera;
225:       c.userZoom = clamp(c.userZoom * (e.deltaY > 0 ? .94 : 1.06), .62, 1.5);
