999:   updateHUD() {
1000:     const alt = this.altitude();
1001:     $('#altitude').textContent = alt;
1002:     $('#falls').textContent = this.stats.falls;
1003:     const best = Math.max(this.save.bestAlt || 0, alt);
1004:     $('#best-alt').textContent = Math.round(best);
1005:     $('#timer').textContent = this.formatTime(this.elapsed);
1006:     const p = this.progress();
1007:     $('#track-fill').style.height = `${p * 100}%`;
1008:     $('#track-you').style.bottom = `${p * 100}%`;
1009:     document.querySelectorAll('.track-mark').forEach((m, i) => {
1010:       m.classList.toggle('done', p * 100 >= parseFloat(m.style.bottom));
1011:     });
1012:     const hs = this.hook.state;
1013:     const stateEl = $('#hook-state');
1014:     const labels = { ready: 'READY', flying: 'THROWN', attached: 'BITES', retracting: 'RETURNING' };
1015:     stateEl.textContent = labels[hs] || 'READY';
1016:     stateEl.classList.toggle('live', hs === 'attached');
1017:     stateEl.classList.toggle('miss', hs === 'retracting');
