283:       const highP = clamp((START.y - highY) / span, 0, 1) * 100;
284:       const m = document.createElement('span');
285:       m.className = 'track-mark';
286:       m.style.bottom = `${lowP}%`;
287:       marks.appendChild(m);
288:       const l = document.createElement('span');
289:       l.className = 'track-label';
290:       l.dataset.zone = z.id;
291:       l.textContent = z.name.replace('Wreck of the ', '').replace('Temple of the ', '');
292:       l.style.bottom = `${(lowP + highP) / 2}%`;
293:       if (l.style.bottom === '0%') l.style.bottom = '4%';
294:       labels.appendChild(l);
295:     }
296:   }
