456:   /* ── main loop ─────────────────────────────────────────── */
457:   loop(now) {
458:     if (!this.running) return;
459:     if (!this.last) this.last = now;
460:     let delta = now - this.last;
461:     this.last = now;
462:     if (delta > 90) delta = 90;
463:     const dt = delta / 1000;
464:     this.time += dt;
465: 
466:     if (this.mode === 'playing') {
467:       this.elapsed += dt;
468:       this.acc = (this.acc || 0) + delta;
469:       let steps = 0;
470:       while (this.acc >= STEP && steps < 4) {
471:         this.fixedUpdate(STEP / 1000);
472:         this.acc -= STEP;
473:         steps++;
474:       }
475:       if (steps === 4) this.acc = 0;
476:       this.frameUpdate(dt);
477:     } else if (this.mode === 'title' || this.mode === 'ending' || this.mode === 'how' || this.mode === 'paused') {
478:       // Keep the world gently alive on menus, but do not simulate play.
479:       if (this.mode === 'title') this.updateTitle(dt);
480:       if (this.mode === 'ending') this.updateEnding(dt);
481:     }
482: 
483:     this.updateCamera(dt);
484:     this.updateParticles(dt);
485:     this.updateUI(dt);
486:     this.audio.update(dt, this.poleSpeed(), this.altitude());
487: 
488:     this.renderer.draw(now / 1000, dt);
489:     requestAnimationFrame(this.loop);
490:   }
491: 
492:   poleSpeed() {
493:     return Math.abs(this.pole.angularVelocity) * POLE_HALF + Vector.magnitude(this.pole.velocity) * 60;
494:   }
495: 
496:   fixedUpdate(dt) {
497:     const p = this.player.position;
498:     this.mouse.wx = (this.mouse.x - this.renderer.w / 2) / this.camera.zoom + this.camera.x;
499:     this.mouse.wy = (this.mouse.y - this.renderer.h / 2) / this.camera.zoom + this.camera.y;
500: 
501:     const shoulder = this.shoulder();
502:     const aim = this.mouse;
503:     let target = Math.atan2(aim.wy - shoulder.y, aim.wx - shoulder.x);
504:     if (!Number.isFinite(target)) target = this.pole.angle;
505:     const diff = wrapAngle(target - this.pole.angle);
506: 
507:     // PD angular control — the pole has weight and fights back.
508:     const kP = this.grip ? 12.5 : 8.4;
509:     const kD = this.grip ? 690 : 520;
510:     const maxT = this.grip ? 20 : 15;
511:     let torque = diff * kP - this.pole.angularVelocity * kD;
512:     torque = clamp(torque, -maxT, maxT);
513:     this.pole.torque = torque;
514: 
515:     // Waddle assist
516:     const dir = (this.keys.right ? 1 : 0) - (this.keys.left ? 1 : 0);
517:     if (dir && this.grounded()) {
518:       Body.applyForce(this.player, p, { x: dir * 0.00115 * PLAYER_MASS, y: 0 });
519:       const maxV = 0.24;
520:       if (Math.abs(this.player.velocity.x) > maxV) {
521:         Body.setVelocity(this.player, { x: Math.sign(this.player.velocity.x) * maxV, y: this.player.velocity.y });
522:       }
523:     }
524: 
525:     // Hook physics
526:     if (this.hook.state === 'attached') this.applyHook(dt);
527: 
528:     Engine.update(this.engine, STEP);
529: 
530:     // Keep the player's barrel upright (the body inertia is locked; safety).
531:     Body.setAngle(this.player, 0);
532:     Body.setAngularVelocity(this.player, 0);
533: 
534:     // Guardrails: if something goes horribly right, recover.
535:     if (p.y > SEA_LIMIT + 100 && this.mode === 'playing') {
536:       this.seaRespawn();
537:     }
538:     const out = !Number.isFinite(p.x) || !Number.isFinite(p.y) || p.y > 5000 || Math.abs(p.x) > 5000;
539:     if (out) this.returnToCheckpoint(true);
540:   }
541: 
542:   frameUpdate(dt) {
543:     const p = this.player.position;
544:     const y = p.y;
545: 
546:     // altitude progress and falls
547:     const alt = (START.y - y) / PX_PER_M;
548:     if (y < this.peakY - 2) this.peakY = y;
549:     if (this.save.bestAlt < alt) {
550:       this.save.bestAlt = alt;
551:       if (this.time - this.lastSave > 4) {
552:         this.lastSave = this.time;
553:         this.saveProgress();
554:       }
555:     }
556:     if (!this.fellThisDrop && y > this.peakY + 430) {
557:       this.fellThisDrop = true;
558:       this.stats.falls++;
559:       this.audio.fallSting();
560:       if (this.time - this.lastFallNarration > 12) {
561:         this.lastFallNarration = this.time;
562:         this.say(FALL_LINES[Math.floor(Math.random() * FALL_LINES.length)], 4200);
563:       }
564:       this.updateHUD();
565:     }
566:     if (this.fellThisDrop && y < this.peakY - 120) this.fellThisDrop = false;
567: 
568:     // checkpoints
569:     const cp = CHECKPOINTS[this.checkpointIndex + 1];
570:     if (cp) {
571:       const near = Math.hypot(p.x - cp.x, p.y - cp.y) < 270;
572:       if (near && this.grounded()) {
573:         this.checkpointIndex++;
574:         this.audio.checkpoint();
575:         this.toast(`CHECKPOINT — ${cp.name}`);
576:         this.say(NARRATION.checkpoint, 4200);
577:         this.spawnGoldBurst({ x: cp.x, y: cp.y - 20 }, 18, false);
578:         this.saveProgress();
579:         this.updateHUD();
580:       }
581:     }
582: 
583:     // Zones
584:     const z = this.level.zoneAt(y);
585:     if (z && z.id !== this.zone.id) {
586:       this.zone = z;
587:       this.audio.setZone(z.id);
588:       this.showZone(z, true);
589:       if (!this.visitedZones.has(z.id)) {
590:         this.visitedZones.add(z.id);
591:         setTimeout(() => {
592:           if (this.mode === 'playing' && this.zone.id === z.id) this.say(z.quote, 7500);
593:         }, 1100);
594:       }
595:     }
596: 
597:     // tutorial hint stages
598:     this.tutorialClock += dt;
599:     if (this.tutorialStage === 0 && (this.tutorialClock > 7 || alt > 2)) this.tutorialStage = 1;
600:     if (this.tutorialStage === 1 && alt > 16) this.tutorialStage = 2;
601:     if (this.tutorialStage === 2 && this.stats.hooks > 0) this.tutorialStage = 3;
602:     if (this.tutorialStage === 0) {
603:       this.setHint('mouse', 'Move the mouse — the pole follows. Plant the tip. Pull.', 0);
604:     } else if (this.tutorialStage === 1) {
605:       this.setHint('lmb', 'Hold left mouse to grip. Lever the pole against a ledge.', 0);
606:     } else if (this.tutorialStage === 2) {
607:       this.setHint('rmb', 'Right mouse throws your hook. Hold to reel in.', 0);
608:     } else if (this.hook.state === 'attached') {
609:       this.setHint('reel', 'HOLD RIGHT MOUSE to haul in. Release to let go.', 0);
610:     } else {
611:       this.setHint('r', 'R returns you to the last checkpoint flag.', 0);
612:     }
613: 
614:     // hook aim / cooldown
615:     const h = this.hook;
616:     if (h.cooldown > 0) h.cooldown = Math.max(0, h.cooldown - dt);
617:     if (h.state === 'flying') {
618:       h.t += dt;
619:       const t = clamp(h.t / h.dur, 0, 1);
620:       const e = 1 - Math.pow(1 - t, 3);
621:       h.pos.x = lerp(h.from.x, h.to.x, e);
622:       h.pos.y = lerp(h.from.y, h.to.y, e);
623:       if (h.miss && Math.random() < .55) this.addParticle({
624:         x: h.pos.x, y: h.pos.y, vx: (Math.random() - .5) * 80, vy: (Math.random() - .5) * 80,
625:         life: .4, max: .4, size: 1.6, color: 'rgba(230,210,170,.5)', type: 'spark', grav: 0,
626:       });
627:       if (t >= 1) {
628:         if (h.miss) {
629:           h.state = 'retracting'; h.t = 0; h.dur = .16;
630:           this.audio.hookMiss();
631:         } else {
632:           h.state = 'attached';
633:           h.anchor = { x: h.to.x, y: h.to.y };
634:           h.ropeLen = Math.max(40, Math.hypot(p.x - h.anchor.x, p.y - h.anchor.y));
635:           h.attachedFor = 0;
636:           this.stats.hooks++;
637:           this.audio.hookLatch();
638:           this.spawnImpact(h.anchor, 'stone', 1.2);
639:           this.addCameraShake(2);
640:         }
641:       }
642:     } else if (h.state === 'attached') {
643:       h.attachedFor += dt;
644:       h.pos.x = h.anchor.x; h.pos.y = h.anchor.y;
645:       if (this.grip || this.reeling) {
646:         // reel is driven by right-mouse held; this.reeling is set on fire
647:       }
648:       if (this.reeling) {
649:         h.ropeLen = Math.max(38, h.ropeLen - 170 * dt);
650:         if (Math.random() < .4) this.audio.reel();
651:         if (Math.random() < .5) this.addParticle({
652:           x: h.anchor.x, y: h.anchor.y, vx: (Math.random() - .5) * 50, vy: Math.random() * 40,
653:           life: .5, max: .5, size: 1.3, color: 'rgba(220,205,170,.45)', type: 'spark', grav: 120,
654:         });
655:       }
656:       if (h.attachedFor > 9 || Math.hypot(p.x - h.anchor.x, p.y - h.anchor.y) > 760) {
657:         this.releaseHook();
658:         this.toast('THE ROPE SLIPS');
659:       }
660:     } else if (h.state === 'retracting') {
661:       h.t += dt;
662:       const t = clamp(h.t / h.dur, 0, 1);
663:       const hand = this.hand();
664:       h.pos.x = lerp(h.pos.x, hand.x, t * .35);
665:       h.pos.y = lerp(h.pos.y, hand.y, t * .35);
666:       if (t >= 1) { h.state = 'ready'; h.cooldown = .35; h.anchor = null; }
667:     } else {
668:       const hand = this.hand();
669:       h.pos.x = hand.x; h.pos.y = hand.y;
670:     }
671: 
672:     // victory
673:     if (Math.hypot(p.x - SUMMIT.x, p.y - SUMMIT.y) < 150) this.startEnding();
674: 
675:     // splash flash decay
676:     this.splashFlash = Math.max(0, this.splashFlash - dt * 1.6);
677:     this.updateHUD();
678:   }
679: 
680:   updateTitle(dt) {
681:     const z = this.camera.baseZoom * 1.1;
682:     const targetX = START.x - (this.renderer.w * .095) / z;
683:     const targetY = START.y - 20;
684:     this.camera.x = damp(this.camera.x, targetX + Math.sin(this.time * .09) * 10, 1.4, dt);
685:     this.camera.y = damp(this.camera.y, targetY + Math.sin(this.time * .13) * 6, 1.4, dt);
686:     this.camera.zoom = damp(this.camera.zoom, z, 1.4, dt);
687:     this.player.torque = 0;
688:   }
689: 
690:   updateEnding(dt) {
691:     this.endTimer += dt;
692:     this.chestOpen = clamp(this.chestOpen + dt * .7, 0, 1);
693:     const target = { x: SUMMIT.x, y: SUMMIT.y - 40 };
694:     this.camera.x = damp(this.camera.x, target.x, 1.8, dt);
695:     this.camera.y = damp(this.camera.y, target.y, 1.8, dt);
696:     this.camera.zoom = damp(this.camera.zoom, this.camera.baseZoom * 1.18, 1.3, dt);
697:     if (this.endTimer > .3 && this.endTimer < 2.6 && Math.random() < .7) {
698:       this.spawnGoldBurst({ x: SUMMIT.x + (Math.random() - .5) * 160, y: SUMMIT.y - 20 }, 1, false);
699:     }
700:   }
701: 
702:   startEnding() {
703:     if (this.mode !== 'playing') return;
704:     this.mode = 'ending';
705:     this.endTimer = 0;
706:     this.chestOpen = 0;
707:     this.releaseHook(true);
708:     this.grip = false;
709:     this.save.summits = (this.save.summits || 0) + 1;
710:     this.save.bestAlt = Math.max(this.save.bestAlt || 0, 1000);
711:     this.saveProgress();
712:     this.audio.treasure();
713:     this.say(NARRATION.summit, 6000);
714:     this.setHint('', '', 0);
715:     this.spawnGoldBurst({ x: SUMMIT.x, y: SUMMIT.y - 30 }, 60, true);
716:     setTimeout(() => {
717:       if (this.mode !== 'ending') return;
718:       $('#end-time').textContent = this.formatTime(this.elapsed);
719:       $('#end-falls').textContent = this.stats.falls;
720:       $('#end-resets').textContent = this.stats.resets;
721:       $('#end-hooks').textContent = this.stats.hooks;
722:       $('#end-line').textContent = this.stats.falls === 0
723:         ? 'Not a single fall. That is either extraordinary skill or a deeply suspicious lack of ambition.'
724:         : this.stats.falls < 8
725:           ? 'The treasure was the friends you made along the way. It is also, it turns out, a great deal of gold.'
726:           : 'You fell, repeatedly, with the dedication of a professional. The gold is yours. So is the view.';
727:       this.show('#end-screen');
728:       this.setHUD(false);
729:     }, 2600);
730:   }
731: 
732:   /* ── hook ──────────────────────────────────────────────── */
733:   fireHook() {
734:     const h = this.hook;
735:     if (h.state === 'flying' || h.state === 'attached' || h.state === 'retracting') return;
736:     if (h.cooldown > 0) return;
737:     this.audio.init();
738:     this.updateMouseWorld();
739:     const p = this.player.position;
740:     const hand = this.hand();
741:     let dx = this.mouse.wx - p.x, dy = this.mouse.wy - p.y;
742:     const d = Math.hypot(dx, dy) || 1;
743:     dx /= d; dy /= d;
744:     const hit = castRay(this.level.segments, hand.x, hand.y, hand.x + dx * HOOK_RANGE, hand.y + dy * HOOK_RANGE, HOOK_RANGE);
745:     h.state = 'flying';
746:     h.miss = !hit;
747:     h.from = { x: hand.x, y: hand.y };
748:     h.to = hit ? { x: hit.x, y: hit.y } : { x: hand.x + dx * HOOK_RANGE, y: hand.y + dy * HOOK_RANGE };
749:     h.pos = { ...h.from };
750:     h.t = 0;
751:     h.attachedFor = 0;
752:     h.anchor = null;
753:     h.dur = hit ? clamp(Math.hypot(hit.x - hand.x, hit.y - hand.y) / 3400, .07, .2) : .19;
754:     this.reeling = true;
755:     this.audio.hookFire();
756:     if (hit) this.toast('');
757:   }
758: 
759:   applyHook(dt) {
760:     const h = this.hook;
761:     if (!h.anchor) return;
762:     const p = this.player.position;
763:     const dx = h.anchor.x - p.x, dy = h.anchor.y - p.y;
764:     const dist = Math.hypot(dx, dy);
765:     if (dist < 1) return;
766:     if (dist > h.ropeLen) {
767:       const nx = dx / dist, ny = dy / dist;
768:       const stretch = dist - h.ropeLen;
769:       const rv = this.player.velocity.x * nx + this.player.velocity.y * ny;
770:       const accel = clamp(stretch * 0.00009 + Math.max(0, rv) * 0.012, 0, 0.02);
771:       Body.applyForce(this.player, p, { x: nx * accel * PLAYER_MASS, y: ny * accel * PLAYER_MASS });
772:       if (stretch > 220) {
773:         // rope rescue cap so a bad catch does not fling you into orbit
